  if (!B) return;
  var NEW = [{"id":"SKD-TKP-0042","sub":"Pelayanan Publik","q":"Anda melihat spanduk informasi layanan kantor masih mencantumkan tarif lama yang sudah dihapus. Tindakan Anda adalah...","options":["A. Segera melapor ke bagian informasi untuk diganti, sementara menjelaskan tarif terbaru kepada warga yang bertanya","B. Mencatat untuk dilaporkan pada rapat bulanan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Membiarkan karena spanduk bukan tugas Anda, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menunggu ada yang mengeluh, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Mengambil keuntungan dari tarif lama"],"ans":0,"scores":[5,4,2,3,1],"trick":"Informasi layanan harus akurat dan segera diperbarui.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), C (2), E (1). Informasi layanan harus akurat dan segera diperbarui."},{"id":"SKD-TKP-0048","sub":"Pelayanan Publik","q":"Setiap Senin pagi pelayanan di unit Anda selalu menumpuk dan warga menunggu lebih dari dua jam. Pimpinan meminta masukan. Usulan Anda adalah...","options":["A. Mengatakan penumpukan wajar terjadi pada awal pekan, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","B. Menganalisis data kunjungan, lalu mengusulkan penambahan loket sementara, pengaturan jadwal petugas, dan pendaftaran daring pada hari itu","C. Mengusulkan agar warga diimbau datang pada hari lain, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Mengusulkan penambahan kursi dan fasilitas ruang tunggu, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Tidak memberi usulan karena itu bukan wewenang Anda"],"ans":1,"scores":[2,5,4,3,1],"trick":"Cari akar masalah dengan data, lalu usulkan solusi terukur.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Cari akar masalah dengan data, lalu usulkan solusi terukur."},{"id":"SKD-TKP-0054","sub":"Pelayanan Publik","q":"Anda ditugaskan melayani warga di desa terpencil melalui layanan keliling. Di tengah jalan, mobil mengalami masalah dan kemungkinan terlambat tiba dua jam. Sikap Anda adalah...","options":["A. Kembali ke kantor karena sudah terlambat","B. Melanjutkan perjalanan dan melayani sebisanya jika masih ada warga","C. Menghubungi kepala desa agar warga diberi kabar, mencari bantuan perbaikan, dan tetap melayani begitu tiba, bila perlu memperpanjang jam layanan","D. Membatalkan layanan hari itu dan menjadwalkan ulang minggu depan tanpa mengabari desa","E. Mengabaikan keterlambatan karena warga pasti mengerti"],"ans":2,"scores":[2,4,5,3,1],"trick":"Komunikasi dan komitmen layanan tetap dijaga walau ada kendala.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), D (3), A (2), E (1). Komunikasi dan komitmen layanan tetap dijaga walau ada kendala."},{"id":"SKD-TKP-0060","sub":"Pelayanan Publik","q":"Anda staf layanan BPJS di kecamatan. Seorang peserta bertanya soal tunggakan iuran padahal ia merasa sudah membayar. Tindakan Anda adalah...","options":["A. Menjelaskan bahwa sistem belum mencatat pembayaran dan meminta peserta membawa bukti bayar untuk dicek, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Menyarankan peserta menelepon pusat layanan nasional, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Mengatakan itu bukan urusan Anda","D. Memeriksa riwayat pembayaran bersama peserta, menjelaskan hasilnya, dan membantu proses koreksi atau pembayaran jika ada selisih","E. Meminta peserta membawa bukti bayar lain kali tanpa mengecek, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":3,"scores":[4,3,1,5,2],"trick":"Telusuri fakta bersama pemohon dan bantu selesaikan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), B (3), E (2), C (1). Telusuri fakta bersama pemohon dan bantu selesaikan."},{"id":"SKD-TKP-0066","sub":"Pelayanan Publik","q":"Seorang pemohon izin usaha menawarkan amplop berisi uang 'terima kasih' agar berkasnya diproses lebih cepat. Berkas tersebut sebenarnya sudah lengkap. Sikap Anda adalah...","options":["A. Menolak halus tanpa melaporkan kepada siapa pun, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menerima uang karena berkas memang lengkap dan tidak merugikan siapa pun","C. Meminta pemohon menyimpan uangnya dan berjanji memprosesnya secepat mungkin, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menerima dengan syarat dicatat sebagai sumbangan kantor, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","E. Menolak dengan sopan, menjelaskan bahwa layanan tidak dipungut biaya, memproses sesuai antrean, dan melaporkan upaya tersebut kepada atasan"],"ans":4,"scores":[4,1,3,2,5],"trick":"Gratifikasi ditolak dan dilaporkan, walaupun berkas sah.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), C (3), D (2), B (1). Gratifikasi ditolak dan dilaporkan, walaupun berkas sah."},{"id":"SKD-TKP-0072","sub":"Pelayanan Publik","q":"Seorang wartawan meminta informasi tentang layanan publik yang sedang dikeluhkan, padahal Anda bukan juru bicara instansi. Sikap Anda adalah...","options":["A. Menyambut dengan ramah dan mengarahkan ke juru bicara atau bagian humas, lalu memberi tahu atasan tentang permintaan wawancara itu","B. Menolak berbicara dan berlalu, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Menjelaskan masalah internal dan menyalahkan atasan","D. Memberikan pendapat pribadi tentang masalah tersebut","E. Memberi informasi umum tanpa melibatkan humas, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":0,"scores":[5,3,1,2,4],"trick":"Informasi resmi disampaikan lewat juru bicara.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), D (2), C (1). Informasi resmi disampaikan lewat juru bicara."},{"id":"SKD-TKP-0078","sub":"Pelayanan Publik","q":"Anda staf unit layanan perpustakaan daerah. Sejumlah pelajar datang berebut koleksi referensi ujian, sementara komputer katalog hanya satu yang berfungsi. Tindakan Anda adalah...","options":["A. Membatasi jumlah pelajar yang boleh masuk, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","B. Mengatur giliran penggunaan, membantu pencarian koleksi manual, dan mengusulkan perbaikan atau penambahan perangkat katalog","C. Membiarkan pelajar berebut tanpa pengaturan","D. Meminta pelajar mencari buku sendiri di rak, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menutup layanan katalog sampai perbaikan selesai, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":1,"scores":[3,5,1,4,2],"trick":"Atur layanan agar adil dan carikan solusi sementara.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), A (3), E (2), C (1). Atur layanan agar adil dan carikan solusi sementara."},{"id":"SKD-TKP-0084","sub":"Pelayanan Publik","q":"Seorang warga mengeluhkan petugas yang tidak ramah dan menyebut ciri-ciri petugas yang mirip dengan rekan Anda. Atasan meminta pendapat Anda. Tindakan Anda adalah...","options":["A. Menyalahkan warga yang mengadu","B. Membenarkan semua tuduhan warga, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Menyampaikan fakta secara objektif tanpa menyudutkan, mendukung klarifikasi, dan mengusulkan pelatihan pelayanan prima untuk tim","D. Mengatakan tidak tahu apa pun, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Menghindari pembicaraan dengan atasan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":2,"scores":[1,2,5,4,3],"trick":"Objektif dan konstruktif dalam menyikapi keluhan.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), B (2), A (1). Objektif dan konstruktif dalam menyikapi keluhan."},{"id":"SKD-TKP-0090","sub":"Pelayanan Publik","q":"Anda baru bertugas di bagian pelayanan perizinan. Seorang pemohon bertanya tentang aturan baru yang belum Anda pahami. Sikap Anda adalah...","options":["A. Mengatakan aturan itu tidak ada","B. Memberikan jawaban berdasarkan kebiasaan sebelumnya, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Meminta pemohon bertanya ke petugas lain, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Jujur belum tahu, segera memeriksa regulasi atau bertanya pada senior, lalu memberi jawaban pasti kepada pemohon","E. Menjawab sekenanya agar tidak terlihat kurang paham, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":3,"scores":[1,4,3,5,2],"trick":"Pelayanan didasarkan informasi akurat; akui keterbatasan lalu cari kebenarannya.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), E (2), A (1). Pelayanan didasarkan informasi akurat; akui keterbatasan lalu cari kebenarannya."},{"id":"SKD-TKP-0096","sub":"Pelayanan Publik","q":"Anda bertugas di loket pembayaran pajak daerah. Sistem pembayaran daring mendadak tidak bisa diakses padahal hari ini batas akhir pembayaran tanpa denda. Tindakan Anda adalah...","options":["A. Menutup layanan karena sistem bermasalah","B. Menerima pembayaran tunai sementara tanpa pencatatan resmi, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Menyatakan denda tetap berlaku sesuai aturan","D. Meminta wajib pajak mencoba lagi nanti, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Melaporkan gangguan ke tim teknis, mencatat wajib pajak yang terdampak, dan mengusulkan kebijakan relaksasi denda kepada pimpinan"],"ans":4,"scores":[1,4,2,3,5],"trick":"Gangguan sistem adalah beban penyedia layanan, bukan warga.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), D (3), C (2), A (1). Gangguan sistem adalah beban penyedia layanan, bukan warga."},{"id":"SKD-TKP-0102","sub":"Pelayanan Publik","q":"Saat pelayanan puncak, rekan Anda kewalahan sementara loket Anda sepi. Sebagian warga mulai menumpuk di loket rekan. Tindakan Anda adalah...","options":["A. Mengambil inisiatif membuka layanan untuk antrean yang menumpuk dan memberi tahu rekan serta petugas pengatur antrean","B. Mengarahkan beberapa warga ke loket Anda tanpa koordinasi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menunggu sampai ada yang meminta bantuan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Beristirahat karena bagian Anda sudah selesai","E. Tetap melayani sedikit warga di loket sendiri, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":0,"scores":[5,3,4,1,2],"trick":"Proaktif membantu agar layanan tidak menumpuk.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), E (2), D (1). Proaktif membantu agar layanan tidak menumpuk."},{"id":"SKD-TKP-0108","sub":"Pelayanan Publik","q":"Seorang warga mengeluh bahwa petugas lain meminta biaya tambahan di luar tarif resmi. Anda belum melihat sendiri kejadiannya. Tindakan Anda adalah...","options":["A. Mengabaikan karena belum melihat sendiri","B. Mencatat laporan dengan detail, menyarankan warga melapor resmi, dan menyampaikan ke atasan atau unit pengawasan untuk ditelusuri","C. Menegur rekan tersebut secara langsung tanpa melapor, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Meminta warga membawa bukti sebelum melapor, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Mengatakan mungkin salah paham"],"ans":1,"scores":[1,5,3,4,2],"trick":"Laporan pungli ditindaklanjuti lewat jalur pengawasan.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), E (2), A (1). Laporan pungli ditindaklanjuti lewat jalur pengawasan."},{"id":"SKD-TKP-0114","sub":"Pelayanan Publik","q":"Rekan Anda sering datang terlambat sehingga loket pelayanan buka lewat jam yang dijanjikan dan warga menunggu. Tindakan Anda adalah...","options":["A. Menyampaikan keluhan ke rekan lain","B. Memberi tahu warga agar komplain langsung kepada rekan itu","C. Menegur dengan santun, mengajak mencari solusi bersama, dan melaporkan ke atasan jika keterlambatan terus berlanjut","D. Menggantikan tugasnya setiap pagi tanpa mengingatkan","E. Membiarkan karena itu urusan pribadinya"],"ans":2,"scores":[3,1,5,4,2],"trick":"Jaga layanan tepat waktu dengan pendekatan baik lalu eskalasi bila perlu.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), E (2), B (1). Jaga layanan tepat waktu dengan pendekatan baik lalu eskalasi bila perlu."},{"id":"SKD-TKP-0120","sub":"Pelayanan Publik","q":"Anda dipercaya menjadi petugas survei kepuasan masyarakat. Hasil sementara menunjukkan nilai rendah di aspek kecepatan layanan, dan atasan ingin laporan terlihat bagus. Tindakan Anda adalah...","options":["A. Menunda laporan sambil menunggu pimpinan merasa siap, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Melaporkan apa adanya tanpa usulan tindak lanjut, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Mengubah angka agar sesuai harapan atasan","D. Melaporkan hasil apa adanya, menganalisis penyebabnya, dan mengusulkan program perbaikan kecepatan layanan","E. Menambah sampel responden sampai nilai membaik"],"ans":3,"scores":[3,4,1,5,2],"trick":"Data layanan harus jujur dan dipakai untuk memperbaiki.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), A (3), E (2), C (1). Data layanan harus jujur dan dipakai untuk memperbaiki."},{"id":"SKD-TKP-0126","sub":"Pelayanan Publik","q":"Petugas piket malam di Dinas Pemadam Kebakaran menerima telepon warga yang panik melaporkan kebakaran, tetapi alamatnya tidak jelas karena penelepon terisak. Tindakan Anda adalah...","options":["A. Meminta penelepon menelepon ulang setelah tenang","B. Menutup telepon karena alamat tidak jelas","C. Mencatat nomor lalu menunggu laporan tambahan dari warga lain","D. Meneruskan telepon ke rekan tanpa penjelasan","E. Menenangkan penelepon, menanyakan patokan lokasi dan jalan sekitar, mengirim regu ke area terdekat, dan terus memandu lewat telepon"],"ans":4,"scores":[4,1,3,2,5],"trick":"Dalam keadaan darurat, kejar informasi dan bergerak cepat.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), C (3), D (2), B (1). Dalam keadaan darurat, kejar informasi dan bergerak cepat."},{"id":"SKD-TKP-0132","sub":"Pelayanan Publik","q":"Seorang ibu rumah tangga mengadu bahwa bantuan pangan dari pemerintah sering telat sampai ke warga. Anda ditugaskan di tim distribusi. Sikap Anda adalah...","options":["A. Menelusuri rantai distribusi, mengidentifikasi hambatan, berkoordinasi dengan pihak desa, dan melaporkan hasilnya kepada ibu tersebut","B. Menyampaikan keluhan ke pimpinan tim, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Meminta ibu bersabar tanpa penjelasan","D. Menyarankan ibu menanyakan ke aparat desa, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Menjelaskan bahwa keterlambatan hal biasa"],"ans":0,"scores":[5,4,1,3,2],"trick":"Telusuri akar masalah dan umpan balikkan hasilnya.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), E (2), C (1). Telusuri akar masalah dan umpan balikkan hasilnya."},{"id":"SKD-TKP-0138","sub":"Pelayanan Publik","q":"Anda ditugaskan memandu kunjungan studi tiru dari daerah lain tentang inovasi layanan. Saat presentasi, muncul pertanyaan kritis tentang kelemahan layanan Anda. Sikap Anda adalah...","options":["A. Mempersilakan peserta mencari tahu sendiri","B. Mengakui kelemahan secara jujur, menjelaskan upaya perbaikan yang sedang berjalan, dan terbuka terhadap masukan","C. Menyangkal adanya kelemahan","D. Menyerahkan pertanyaan ke atasan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Menjawab seperlunya lalu mengalihkan ke keunggulan layanan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":1,"scores":[1,5,2,3,4],"trick":"Keterbukaan terhadap kritik mendorong perbaikan layanan.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), C (2), A (1). Keterbukaan terhadap kritik mendorong perbaikan layanan."},{"id":"SKD-TKP-0144","sub":"Pelayanan Publik","q":"Anda petugas informasi di bandara daerah. Seorang penumpang lansia kehilangan arah dan hampir ketinggalan pesawat. Tindakan Anda adalah...","options":["A. Memanggilkan petugas keamanan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Mengabaikan karena sibuk melayani antrean","C. Mengantarnya ke gerbang keberangkatan, menghubungi maskapai bila perlu, dan memastikan ia dibantu hingga naik pesawat","D. Menyarankan bertanya ke petugas lain","E. Menunjukkan arah gerbang dan menyebut nomor penerbangan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":2,"scores":[3,1,5,2,4],"trick":"Layanan prima berarti memastikan pengguna sampai tujuan.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), A (3), D (2), B (1). Layanan prima berarti memastikan pengguna sampai tujuan."},{"id":"SKD-TKP-0150","sub":"Pelayanan Publik","q":"Anda mendapati seorang pemohon lanjut usia lupa membawa kartu identitas asli tetapi memiliki salinan dan data di sistem kependudukan. Persyaratan menyebut dokumen asli. Tindakan Anda adalah...","options":["A. Meminta pemohon kembali membawa dokumen asli, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Meminta pemohon membayar agar dokumen asli tidak diperlukan","C. Menolak tanpa menjelaskan alasan","D. Memeriksa data melalui sistem resmi, menanyakan kebijakan pengecualian kepada atasan, dan melayani jika diperbolehkan","E. Menerima salinan tanpa memeriksa lebih lanjut, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":3,"scores":[4,1,2,5,3],"trick":"Fleksibel dalam aturan: verifikasi dan minta persetujuan atasan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), E (3), C (2), B (1). Fleksibel dalam aturan: verifikasi dan minta persetujuan atasan."},{"id":"SKD-TKP-0156","sub":"Pelayanan Publik","q":"Anda diminta menyusun standar pelayanan unit, tetapi rekan senior menganggap standar baru hanya menambah beban kerja. Sikap Anda adalah...","options":["A. Menyusun standar sendiri lalu menyerahkannya kepada pimpinan, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Membatalkan penyusunan agar tidak berkonflik","C. Menunda penyusunan sampai rekan senior setuju, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menyalin standar dari instansi lain tanpa menyesuaikan","E. Menjelaskan manfaat standar bagi warga dan petugas, mengajak rekan memberi masukan, dan menyusun standar yang realistis untuk dijalankan"],"ans":4,"scores":[4,1,3,2,5],"trick":"Libatkan rekan dalam perubahan dan sesuaikan dengan kondisi unit.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), C (3), D (2), B (1). Libatkan rekan dalam perubahan dan sesuaikan dengan kondisi unit."},{"id":"SKD-TKP-0162","sub":"Pelayanan Publik","q":"Pada hari libur nasional, ada warga yang mendatangi kantor Anda untuk melapor kehilangan dokumen penting. Kantor tutup dan Anda kebetulan lewat. Tindakan Anda adalah...","options":["A. Menjelaskan kanal layanan darurat atau daring, membantu mencatat laporan awal jika memungkinkan, dan menginformasikan jadwal layanan berikutnya","B. Menyarankan warga ke kantor polisi tanpa penjelasan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Menolak karena sedang libur","D. Pura-pura tidak mengenal warga, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","E. Meminta warga datang pada hari kerja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":0,"scores":[5,3,1,2,4],"trick":"Tetap membantu dengan informasi layanan yang benar walau di luar jam kerja.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), D (2), C (1). Tetap membantu dengan informasi layanan yang benar walau di luar jam kerja."},{"id":"SKD-TKP-0168","sub":"Pelayanan Publik","q":"Anda petugas layanan kesehatan yang menemukan bahwa stok vaksin tinggal sedikit, sementara banyak warga datang untuk imunisasi anak. Tindakan Anda adalah...","options":["A. Memberikan vaksin sesuai urutan datang saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Memprioritaskan balita sesuai jadwal imunisasi, mencatat sisa antrean, dan mengajukan permintaan tambahan stok ke dinas kesehatan","C. Memberikan vaksin kepada kenalan terlebih dahulu, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","D. Menutup layanan imunisasi sampai stok baru datang","E. Memberi tahu warga stok sudah habis tanpa mencatat, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":1,"scores":[4,5,2,1,3],"trick":"Prioritaskan kebutuhan paling mendesak dan segera ajukan tambahan stok.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), E (3), C (2), D (1). Prioritaskan kebutuhan paling mendesak dan segera ajukan tambahan stok."},{"id":"SKD-TKP-0174","sub":"Pelayanan Publik","q":"Dinas Anda meluncurkan layanan baru berbasis aplikasi, tetapi banyak warga di pedesaan belum punya ponsel pintar. Usulan Anda adalah...","options":["A. Menyarankan warga yang tidak punya ponsel tidak perlu mengurus layanan","B. Memasang spanduk informasi tentang aplikasi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Tetap menyediakan layanan manual dan pendampingan di kantor desa sambil melakukan sosialisasi dan pelatihan penggunaan aplikasi","D. Menghentikan layanan manual agar warga terpaksa belajar, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Menunggu warga belajar sendiri, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":2,"scores":[1,3,5,4,2],"trick":"Transformasi digital harus menjangkau semua kelompok.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), E (2), A (1). Transformasi digital harus menjangkau semua kelompok."},{"id":"SKD-TKP-0180","sub":"Pelayanan Publik","q":"Anda perawat di puskesmas pembantu. Menjelang tutup, seorang ibu membawa anak demam tinggi, padahal antrean sudah ditutup dan dokter sudah pulang. Sikap Anda adalah...","options":["A. Menolak karena antrean sudah ditutup sesuai jadwal pelayanan","B. Memberi obat penurun panas lalu menyarankan ibu kembali esok hari jika demam belum turun, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Menelepon dokter dan meminta ibu menunggu sampai ada instruksi, tanpa memeriksa anak lebih dulu, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Memeriksa kondisi anak segera, memberi pertolongan awal sesuai kewenangan, lalu menghubungi dokter atau merujuk ke rumah sakit terdekat","E. Menyarankan ibu mencari klinik swasta karena puskesmas sudah tutup"],"ans":3,"scores":[1,4,3,5,2],"trick":"Kondisi darurat mengalahkan jam layanan: tangani dulu, rujuk bila perlu.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), E (2), A (1). Kondisi darurat mengalahkan jam layanan: tangani dulu, rujuk bila perlu."},{"id":"SKD-TKP-0186","sub":"Pelayanan Publik","q":"Pada hari pertama layanan terpadu satu atap, alur yang baru membuat petugas bingung dan antrean berantakan. Anda bagian koordinator lantai. Tindakan Anda adalah...","options":["A. Kembali menggunakan alur lama tanpa izin","B. Mengeluhkan sistem baru kepada rekan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Meninggalkan area karena bukan tugas Anda","D. Meminta warga menunggu sampai alur stabil, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Mengatur arus pengunjung, memberi penjelasan alur kepada warga dan petugas, lalu mencatat masalah untuk perbaikan sistem pada rapat evaluasi"],"ans":4,"scores":[2,3,1,4,5],"trick":"Kendali situasi dulu, lalu evaluasi sistem.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), A (2), C (1). Kendali situasi dulu, lalu evaluasi sistem."},{"id":"SKD-TKP-0192","sub":"Pelayanan Publik","q":"Anda petugas Dinas Kependudukan. Seorang ibu menangis karena akta kelahiran anaknya salah ketik nama, padahal akta itu dibutuhkan untuk pendaftaran sekolah minggu depan. Sikap Anda adalah...","options":["A. Menenangkan ibu, menjelaskan prosedur perbaikan, membantu menyiapkan berkas, dan mengupayakan proses secepat aturan memungkinkan","B. Menyarankan ibu menghubungi pihak sekolah untuk meminta kelonggaran, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Memberi tahu bahwa perbaikan butuh beberapa hari lalu memintanya mengurus sendiri, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Mengatakan kesalahan itu terjadi di pihak lain dan bukan urusan Anda","E. Meminta ibu membayar sejumlah uang agar perbaikan lebih cepat"],"ans":0,"scores":[5,3,4,2,1],"trick":"Bantu dengan solusi nyata dalam koridor aturan.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), D (2), E (1). Bantu dengan solusi nyata dalam koridor aturan."},{"id":"SKD-TKP-0198","sub":"Pelayanan Publik","q":"Anda petugas pendaftaran di rumah sakit daerah. Seorang bapak lanjut usia tidak bisa memakai mesin anjungan pendaftaran mandiri dan tampak bingung. Tindakan Anda adalah...","options":["A. Menyuruhnya mencari informasi sendiri di papan petunjuk","B. Mendampingi bapak itu mendaftar, menjelaskan langkahnya dengan sabar, lalu memastikan ia sampai ke poli yang tepat","C. Membiarkan karena anjungan mandiri memang bukan tugas petugas","D. Meminta keluarganya datang membantu mendaftar, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menunjukkan petunjuk di layar anjungan lalu melayani pengunjung berikutnya, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":1,"scores":[2,5,1,3,4],"trick":"Layanan harus inklusif: bantu pengguna yang kesulitan teknologi.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), A (2), C (1). Layanan harus inklusif: bantu pengguna yang kesulitan teknologi."},{"id":"SKD-TKP-0204","sub":"Pelayanan Publik","q":"Seorang warga memviralkan di media sosial keluhan tentang lambatnya layanan unit Anda. Unggahan itu dibagikan ratusan kali dan sebagian isinya memang benar. Sikap Anda adalah...","options":["A. Menunggu arahan humas tanpa berbuat apa pun, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Membalas unggahan dengan klarifikasi resmi tentang prosedur yang berlaku, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Melaporkan ke atasan, menghubungi warga untuk menyelesaikan masalahnya, dan mengevaluasi alur layanan agar tidak terulang","D. Meminta warga menghapus unggahan karena merusak citra instansi","E. Membuat akun anonim untuk membela instansi dan menyerang pengunggah"],"ans":2,"scores":[3,4,5,2,1],"trick":"Kritik publik adalah bahan perbaikan: selesaikan masalah dan benahi sistem.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), D (2), E (1). Kritik publik adalah bahan perbaikan: selesaikan masalah dan benahi sistem."},{"id":"SKD-TKP-0210","sub":"Pelayanan Publik","q":"Anda memegang akun resmi media sosial instansi. Banyak komentar warga bertanya syarat layanan yang sama. Sikap Anda adalah...","options":["A. Mematikan kolom komentar agar tidak merepotkan, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Membalas satu per satu tanpa membuat materi baru, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Membiarkan komentar tanpa jawaban","D. Membuat infografis syarat layanan, menyematkannya, dan membalas tiap pertanyaan dengan ramah serta mengarahkan ke kanal resmi","E. Meminta warga melihat situs web, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":3,"scores":[2,4,1,5,3],"trick":"Kebutuhan informasi berulang diatasi dengan materi edukasi yang mudah diakses.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), E (3), A (2), C (1). Kebutuhan informasi berulang diatasi dengan materi edukasi yang mudah diakses."},{"id":"SKD-TKP-0216","sub":"Pelayanan Publik","q":"Seorang warga mengajukan pengaduan di kanal LAPOR! tentang jalan rusak di wilayah yang bukan kewenangan instansi Anda. Tindakan Anda adalah...","options":["A. Membalas bahwa itu bukan kewenangan instansi Anda dan menyarankan melapor ke tempat lain, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Menghapus aduan agar tidak mengganggu capaian kinerja","C. Menutup aduan tanpa balasan karena tidak relevan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Meneruskan aduan tanpa memberi tahu warga, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Meneruskan aduan ke instansi yang berwenang, memberi tahu warga tindak lanjutnya, dan memantau perkembangan penanganan"],"ans":4,"scores":[4,1,2,3,5],"trick":"Aduan tetap dilayani: disposisi ke pihak berwenang dan kabari pelapor.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), D (3), C (2), B (1). Aduan tetap dilayani: disposisi ke pihak berwenang dan kabari pelapor."},{"id":"SKD-TKP-0222","sub":"Pelayanan Publik","q":"Seorang pengunjung terpeleset di lobi kantor pelayanan karena lantai licin sehabis dipel. Anda berada di dekatnya. Tindakan Anda adalah...","options":["A. Segera menolong, memberi pertolongan pertama, memasang tanda lantai licin, dan melaporkan kejadian untuk perbaikan prosedur kebersihan","B. Menolong lalu memberikan kursi dan air minum, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Meminta pengunjung berhati-hati lain kali","D. Memanggil petugas keamanan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Membiarkan karena itu kelalaian pengunjung"],"ans":0,"scores":[5,4,2,3,1],"trick":"Utamakan keselamatan, lalu perbaiki penyebabnya.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), C (2), E (1). Utamakan keselamatan, lalu perbaiki penyebabnya."},{"id":"SKD-TKP-0228","sub":"Pelayanan Publik","q":"Dalam program bantuan sosial, Anda menemukan warga yang jelas layak menerima tetapi namanya tidak tercantum di data. Penyaluran dilakukan besok pagi. Tindakan Anda adalah...","options":["A. Menyarankan warga mengurus sendiri usulan melalui kelurahan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Mendokumentasikan kondisi warga, melaporkan ke dinas sosial untuk verifikasi dan usulan pemutakhiran data sesuai mekanisme resmi","C. Menyampaikan lisan ke rekan tanpa mencatat apa pun, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Mengabaikan karena data resmi tidak memuat namanya","E. Mencantumkan nama warga secara manual agar bisa menerima bantuan hari itu, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":1,"scores":[4,5,3,1,2],"trick":"Perbaiki data lewat jalur resmi, jangan melanggar prosedur demi rasa iba.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), E (2), D (1). Perbaiki data lewat jalur resmi, jangan melanggar prosedur demi rasa iba."},{"id":"SKD-TKP-0234","sub":"Pelayanan Publik","q":"Di kantor kelurahan, mesin perekaman e-KTP rusak sejak pagi. Puluhan warga yang sudah membuat janji mulai mengeluh. Anda bertugas di meja informasi. Tindakan Anda adalah...","options":["A. Menyarankan warga datang ke kecamatan lain tanpa membantu menghubungi kantor tersebut, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Menempelkan pengumuman 'mesin rusak' lalu kembali ke pekerjaan lain, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","C. Menjelaskan kerusakan dengan sopan, mendata warga untuk dijadwalkan ulang prioritas, dan mengumumkan perkiraan perbaikan dari teknisi","D. Menghindar ke ruangan belakang sampai warga bubar","E. Meminta warga menunggu sampai mesin diperbaiki tanpa kepastian waktu, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":2,"scores":[3,2,5,1,4],"trick":"Kerusakan sarana tidak boleh membuat warga terlantar: informasikan dan beri kepastian.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), A (3), B (2), D (1). Kerusakan sarana tidak boleh membuat warga terlantar: informasikan dan beri kepastian."},{"id":"SKD-TKP-0240","sub":"Pelayanan Publik","q":"Seorang pemohon terus berbicara dengan nada tinggi dan menuduh Anda sengaja mempersulit padahal kekurangan berkasnya jelas. Sikap Anda adalah...","options":["A. Menolak melayani selama pemohon masih marah","B. Diam sampai pemohon selesai berbicara lalu memanggil petugas keamanan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menjelaskan sekali lalu menyerahkan pada atasan jika pemohon tidak puas, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Tetap tenang, mendengarkan, menunjukkan daftar persyaratan, lalu membantu langkah melengkapi berkas dengan bahasa yang santun","E. Membalas dengan nada serupa agar pemohon sadar"],"ans":3,"scores":[1,3,4,5,2],"trick":"Emosi dibalas ketenangan dan penjelasan yang jelas.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), B (3), E (2), A (1). Emosi dibalas ketenangan dan penjelasan yang jelas."},{"id":"SKD-TKP-0246","sub":"Pelayanan Publik","q":"Warga di wilayah kerja Anda mengeluh puskesmas keliling jarang datang dan jadwalnya tidak jelas. Anda bertugas di dinas kesehatan. Tindakan Anda adalah...","options":["A. Mengabaikan karena sudah sesuai anggaran","B. Menyampaikan keluhan warga kepada atasan tanpa tindak lanjut, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Meminta warga datang ke puskesmas induk, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Membantah bahwa jadwal sudah berjalan","E. Memeriksa jadwal dan kendala operasional, memperbaiki jadwal, lalu menyampaikan informasi jelas kepada warga melalui aparat desa"],"ans":4,"scores":[1,4,3,2,5],"trick":"Pelayanan harus dipantau dan dikomunikasikan jelas.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), C (3), D (2), A (1). Pelayanan harus dipantau dan dikomunikasikan jelas."},{"id":"SKD-TKP-0252","sub":"Pelayanan Publik","q":"Sebuah organisasi masyarakat meminta data layanan publik untuk kegiatan penelitian, tetapi sebagian data memuat identitas warga. Sikap Anda adalah...","options":["A. Menyampaikan permintaan ke atasan atau pejabat pengelola informasi, serta menyediakan data yang telah dianonimkan sesuai aturan","B. Memberikan data kepada kenalan di organisasi tersebut, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Memberikan seluruh data karena bersifat informasi publik, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Menjual data kepada pemohon","E. Menolak seluruh permintaan tanpa penjelasan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":0,"scores":[5,2,4,1,3],"trick":"Layani keterbukaan informasi sambil menjaga data pribadi.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), E (3), B (2), D (1). Layani keterbukaan informasi sambil menjaga data pribadi."},{"id":"SKD-TKP-0258","sub":"Pelayanan Publik","q":"Anda baru menyadari telah memberi informasi persyaratan yang keliru kepada seorang pemohon kemarin sehingga ia harus kembali hari ini. Sikap Anda adalah...","options":["A. Menyatakan pemohon yang salah memahami","B. Mengakui kesalahan, meminta maaf, membantu menyelesaikan permohonannya hari itu, dan memastikan informasi persyaratan benar di kemudian hari","C. Menyalahkan perubahan aturan yang mendadak, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Meminta maaf dan menyuruhnya melengkapi berkas, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Berharap pemohon tidak mengingatnya"],"ans":1,"scores":[1,5,3,4,2],"trick":"Akui kesalahan, perbaiki, dan cegah terulang.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), E (2), A (1). Akui kesalahan, perbaiki, dan cegah terulang."},{"id":"SKD-TKP-0264","sub":"Pelayanan Publik","q":"Seorang pemohon sedang buru-buru karena harus berangkat ke luar kota dan meminta layanan didahulukan. Pemohon lain sudah menunggu lebih lama. Tindakan Anda adalah...","options":["A. Mendahulukan pemohon karena dia memberi imbalan","B. Mendahulukan karena pemohon tampak sangat membutuhkan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Menjelaskan bahwa layanan berdasarkan urutan, namun menawarkan opsi penyelesaian daring atau pengurusan lewat perwakilan sesuai aturan","D. Menolak tanpa memberi alternatif","E. Meminta pemohon bernegosiasi dengan antrean lain, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":2,"scores":[1,4,5,2,3],"trick":"Adil dalam antrean sambil mencari opsi layanan alternatif.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Adil dalam antrean sambil mencari opsi layanan alternatif."},{"id":"SKD-TKP-0270","sub":"Pelayanan Publik","q":"Seorang warga dari suku berbeda berbicara dengan bahasa daerah dan sulit dipahami saat mengurus layanan di kantor Anda. Tindakan Anda adalah...","options":["A. Memberi formulir tanpa penjelasan","B. Mengabaikan karena sulit dipahami","C. Berbicara lebih keras dan lambat dalam bahasa Indonesia","D. Mencari rekan atau relawan yang menguasai bahasa tersebut atau memakai alat bantu, sambil melayani dengan sabar","E. Meminta warga mengajak penerjemah"],"ans":3,"scores":[2,1,4,5,3],"trick":"Pastikan komunikasi efektif agar warga terlayani.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), A (2), B (1). Pastikan komunikasi efektif agar warga terlayani."},{"id":"SKD-TKP-0276","sub":"Pelayanan Publik","q":"Warga mengeluh papan penunjuk arah di gedung pelayanan membingungkan sehingga sering salah ruangan. Anda sering melihatnya. Tindakan Anda adalah...","options":["A. Menganggap warga seharusnya lebih teliti","B. Menunggu instruksi untuk memperbaiki, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Membantu warga yang bertanya saja, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Tidak peduli karena bukan wewenang Anda","E. Mengusulkan perbaikan papan petunjuk dengan contoh usulan, sambil membantu mengarahkan warga langsung"],"ans":4,"scores":[2,3,4,1,5],"trick":"Hambatan layanan diperbaiki dengan usulan nyata.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), A (2), D (1). Hambatan layanan diperbaiki dengan usulan nyata."},{"id":"SKD-TKP-0282","sub":"Pelayanan Publik","q":"Seorang warga lanjut usia di desa terpencil kesulitan datang ke kantor kecamatan untuk memperbarui data bantuan. Anda mengetahui kondisinya. Tindakan Anda adalah...","options":["A. Mengatur kunjungan petugas atau pelayanan jemput bola ke rumahnya sesuai prosedur yang berlaku","B. Menyarankan menunjuk perwakilan tanpa melihat kondisi","C. Mengabaikan karena jaraknya jauh","D. Memberi tahu keluarga agar mengantar ke kantor, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Menunggu warga itu datang sendiri, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":0,"scores":[5,2,1,4,3],"trick":"Jemput bola bagi warga yang tidak mampu menjangkau layanan.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), B (2), C (1). Jemput bola bagi warga yang tidak mampu menjangkau layanan."},{"id":"SKD-TKP-0288","sub":"Pelayanan Publik","q":"Seorang pemohon anak muda ingin mengurus izin usaha rintisan dan banyak bertanya tentang hal teknis. Antrean di belakangnya mulai memanjang. Tindakan Anda adalah...","options":["A. Menolak menjawab pertanyaan selain syarat izin","B. Menjawab pertanyaan inti dengan singkat, menjadwalkan sesi konsultasi lanjutan, dan memberi materi panduan agar antrean tetap lancar","C. Meminta pemohon bertanya lewat surel, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menjawab semua pertanyaan hingga selesai, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Meminta pemohon cepat karena banyak yang menunggu"],"ans":1,"scores":[1,5,3,4,2],"trick":"Seimbangkan kebutuhan pemohon dengan kepentingan antrean.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), E (2), A (1). Seimbangkan kebutuhan pemohon dengan kepentingan antrean."},{"id":"SKD-TKP-0294","sub":"Pelayanan Publik","q":"Seorang warga datang ke puskesmas membawa surat rujukan yang masa berlakunya baru habis kemarin. Pasien tampak kesakitan. Sikap Anda adalah...","options":["A. Menolak karena surat tidak berlaku, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menyuruh pasien membayar agar tetap dilayani","C. Memeriksa kondisi pasien lebih dulu, menghubungi fasilitas rujukan untuk konfirmasi, dan membantu memperbarui surat sesuai prosedur","D. Meminta pasien mengurus surat baru lebih dulu sebelum dilayani, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menerima pasien tetapi tanpa penjelasan prosedur, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":2,"scores":[2,1,5,4,3],"trick":"Kondisi pasien didahulukan, administrasi diselesaikan bersamaan.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), A (2), B (1). Kondisi pasien didahulukan, administrasi diselesaikan bersamaan."},{"id":"SKD-TKP-0300","sub":"Pelayanan Publik","q":"Di ruang tunggu pelayanan, ibu hamil berdiri karena kursi penuh, sementara pemuda di dekatnya asyik bermain ponsel. Anda petugas yang melihatnya. Tindakan Anda adalah...","options":["A. Membiarkan karena bukan tugas Anda","B. Meminta ibu hamil menunggu sesuai urutan seperti pengunjung lain","C. Menegur semua pengunjung untuk saling menghargai, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Mempersilakan ibu hamil duduk di kursi prioritas atau menyiapkan kursi, dan memprioritaskan pelayanannya","E. Meminta pemuda memberikan tempat duduk, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[2,1,3,5,4],"trick":"Kelompok rentan mendapat prioritas layanan.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), A (2), B (1). Kelompok rentan mendapat prioritas layanan."},{"id":"SKD-TKP-0306","sub":"Pelayanan Publik","q":"Menjelang jam tutup layanan, antrean masih tersisa sepuluh orang. Rekan Anda mengajak pulang tepat waktu. Sikap Anda adalah...","options":["A. Menyuruh sisa antrean kembali besok, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Menutup loket lebih awal agar tidak lembur","C. Pulang tepat waktu sesuai jam kerja, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","D. Melayani lima orang lalu menutup layanan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Menyelesaikan seluruh antrean yang sudah terdaftar, lalu menutup layanan dan melaporkan kebutuhan penambahan petugas bila sering terjadi"],"ans":4,"scores":[3,1,2,4,5],"trick":"Warga yang sudah antre diselesaikan; evaluasi kapasitas.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), A (3), C (2), B (1). Warga yang sudah antre diselesaikan; evaluasi kapasitas."},{"id":"SKD-TKP-0312","sub":"Pelayanan Publik","q":"Seorang pedagang kecil mengeluh perizinan usahanya berbelit karena harus mengurus di beberapa kantor. Anda bertugas di unit perizinan. Sikap Anda adalah...","options":["A. Menjelaskan alur terpadu melalui sistem perizinan berusaha daring, membantu pendaftaran, dan mencatat keluhan untuk penyederhanaan prosedur","B. Memintanya membawa tambahan biaya agar prosesnya cepat","C. Mengatakan prosedur memang begitu","D. Menjelaskan persyaratan satu per satu lalu menyuruh pedagang mengurus sendiri","E. Menyarankan menyewa jasa pengurusan izin"],"ans":0,"scores":[5,1,2,4,3],"trick":"Permudah warga dan sampaikan masukan penyederhanaan prosedur.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), C (2), B (1). Permudah warga dan sampaikan masukan penyederhanaan prosedur."},{"id":"SKD-TKP-0318","sub":"Pelayanan Publik","q":"Seorang petani datang ke Dinas Pertanian meminta bantuan bibit, tetapi persyaratan keanggotaan kelompok tani belum terpenuhi. Tindakan Anda adalah...","options":["A. Memberi sedikit bibit dari stok pribadi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Menjelaskan persyaratan, membantu proses pembentukan atau pendaftaran kelompok tani, dan menginformasikan jadwal penyaluran berikutnya","C. Menyuruh petani mengurus kelompok sendiri lalu kembali, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menyuruh petani membeli bibit di toko","E. Menolak tanpa penjelasan"],"ans":1,"scores":[3,5,4,1,2],"trick":"Layani dengan edukasi dan pendampingan sesuai aturan.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), A (3), E (2), D (1). Layani dengan edukasi dan pendampingan sesuai aturan."},{"id":"SKD-TKP-0324","sub":"Pelayanan Publik","q":"Anda menemukan dompet berisi identitas warga yang tertinggal di meja layanan. Sikap Anda adalah...","options":["A. Menunggu pemilik datang sendiri","B. Menyimpan dompet untuk dipakai sementara","C. Menyimpan di tempat aman, mencatat temuan, menghubungi pemilik lewat kontak di identitas, dan menyerahkannya dengan bukti serah terima","D. Menaruh dompet di meja informasi tanpa pengamanan","E. Menitipkan ke satpam tanpa mencatat"],"ans":2,"scores":[3,1,5,2,4],"trick":"Barang temuan dijaga dan dikembalikan sesuai prosedur.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), A (3), D (2), B (1). Barang temuan dijaga dan dikembalikan sesuai prosedur."},{"id":"SKD-TKP-0330","sub":"Pelayanan Publik","q":"Anda menerima pertanyaan melalui telepon dari warga tentang prosedur layanan yang bukan bagian tugas unit Anda, tetapi Anda tahu jawabannya. Sikap Anda adalah...","options":["A. Menjawab asal-asalan agar cepat selesai","B. Menutup telepon karena bukan tugas Anda, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Mentransfer telepon ke unit lain tanpa penjelasan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Menjelaskan sebisanya dengan benar, lalu menyebutkan unit yang berwenang beserta nomor kontaknya agar warga terbantu","E. Memberitahu bahwa itu bukan unit Anda dan memberi nomor telepon umum, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[1,2,3,5,4],"trick":"Bantu tuntas walau di luar tugas pokok.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), B (2), A (1). Bantu tuntas walau di luar tugas pokok."},{"id":"SKD-TKP-0336","sub":"Pelayanan Publik","q":"Banjir melanda kampung dan Anda ditugaskan di posko pelayanan administrasi pengungsi. Banyak warga kehilangan dokumen. Tindakan Anda adalah...","options":["A. Meminta korban mengurus dokumen setelah banjir surut, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menyiapkan formulir lalu menunggu korban datang sendiri, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Menyarankan korban mengurus melalui calo agar cepat","D. Memberi tahu korban bahwa layanan dokumen ditutup selama bencana, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","E. Mendata korban, memberi layanan pengurusan dokumen pengganti secara jemput bola, dan berkoordinasi dengan instansi terkait"],"ans":4,"scores":[4,3,1,2,5],"trick":"Dalam bencana, layanan aktif dan jemput bola.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), B (3), D (2), C (1). Dalam bencana, layanan aktif dan jemput bola."},{"id":"SKD-TKP-0342","sub":"Pelayanan Publik","q":"Pada layanan keliling sekolah, seorang guru meminta layanan administrasi untuk siswa yang belum memiliki akta. Jumlah siswa lebih banyak dari kuota hari itu. Tindakan Anda adalah...","options":["A. Melayani sesuai kuota, mendata sisa siswa, lalu menjadwalkan layanan lanjutan secepatnya dan menyampaikannya ke pihak sekolah","B. Mengundi siswa yang dilayani, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Melayani sampai kuota habis lalu pulang, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menyuruh guru mengatur sendiri","E. Menolak seluruhnya karena melampaui kuota"],"ans":0,"scores":[5,3,4,1,2],"trick":"Keterbatasan kuota dijawab dengan pendataan dan jadwal tindak lanjut.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), E (2), D (1). Keterbatasan kuota dijawab dengan pendataan dan jadwal tindak lanjut."},{"id":"SKD-TKP-0348","sub":"Pelayanan Publik","q":"Seorang warga penyandang tuli datang ke kantor Anda untuk mengurus surat keterangan. Tidak ada juru bahasa isyarat di tempat. Tindakan Anda adalah...","options":["A. Memanggil rekan yang sedikit bisa bahasa isyarat saja, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Berkomunikasi lewat tulisan atau layar ponsel, melayani dengan sabar, dan mengusulkan penyediaan juru bahasa isyarat di unit layanan","C. Menyuruh warga kembali ketika ada juru bahasa","D. Meminta warga datang bersama keluarga yang bisa membantu, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Menolak melayani karena kesulitan berkomunikasi"],"ans":1,"scores":[4,5,2,3,1],"trick":"Cari cara komunikasi alternatif dan perbaiki sarana jangka panjang.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), C (2), E (1). Cari cara komunikasi alternatif dan perbaiki sarana jangka panjang."},{"id":"SKD-TKP-0354","sub":"Pelayanan Publik","q":"Anda petugas yang ditempatkan di kantor pos pelayanan publik terpadu. Petugas lain sering mengobrol pribadi sementara warga menunggu. Anda adalah petugas baru. Sikap Anda adalah...","options":["A. Ikut mengurangi interaksi dengan warga agar tidak berbeda, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Ikut mengobrol karena sudah menjadi kebiasaan","C. Tetap melayani dengan baik, menjadi teladan, dan menyampaikan masukan kepada atasan atau rekan secara santun pada waktu yang tepat","D. Diam karena Anda orang baru, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Menyindir rekan melalui media sosial, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":2,"scores":[4,1,5,2,3],"trick":"Jadi teladan layanan dan sampaikan masukan dengan baik.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), D (2), B (1). Jadi teladan layanan dan sampaikan masukan dengan baik."},{"id":"SKD-TKP-0360","sub":"Pelayanan Publik","q":"Anda petugas PDAM. Seorang pelanggan mengadu air tidak mengalir tiga hari. Setelah dicek, penyebabnya adalah pipa bocor di jalur yang menjadi tanggung jawab tim lain. Tindakan Anda adalah...","options":["A. Meneruskan laporan ke tim terkait lalu menutup tiket aduan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Mengatakan masalah itu bukan bidang Anda, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","C. Menyarankan pelanggan membeli air sendiri","D. Menerima laporan, meneruskan ke tim yang bertanggung jawab dengan data lengkap, menyampaikan perkiraan waktu perbaikan, dan menawarkan pasokan air darurat","E. Meminta pelanggan menghubungi tim lain langsung, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":3,"scores":[4,2,1,5,3],"trick":"Tanggung jawab layanan tidak berhenti pada batas tugas: pastikan masalah tertangani.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), E (3), B (2), C (1). Tanggung jawab layanan tidak berhenti pada batas tugas: pastikan masalah tertangani."},{"id":"SKD-TKP-0043","sub":"Jejaring Kerja","q":"Sebuah perguruan tinggi mengajak instansi Anda bekerja sama dalam penelitian kebijakan, tetapi pimpinan Anda ragu karena khawatir hasilnya mengkritik instansi. Sikap Anda adalah...","options":["A. Menyampaikan manfaat kerja sama bagi perbaikan kebijakan, mengusulkan kesepakatan etika penelitian yang jelas, dan menyerahkan keputusan kepada pimpinan","B. Menunggu pimpinan memutuskan sendiri, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","C. Menerima kerja sama tanpa persetujuan pimpinan","D. Membocorkan keraguan pimpinan kepada pihak kampus","E. Menolak ajakan perguruan tinggi tanpa membahasnya, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":0,"scores":[5,4,2,1,3],"trick":"Kritik dari mitra menjadi sumber perbaikan; tetap hormati hirarki keputusan.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), E (3), C (2), D (1). Kritik dari mitra menjadi sumber perbaikan; tetap hormati hirarki keputusan."},{"id":"SKD-TKP-0049","sub":"Jejaring Kerja","q":"Anda tergabung dalam tim lintas generasi. Anggota senior sering meremehkan ide dari anggota muda, sehingga suasana rapat kaku. Sikap Anda adalah...","options":["A. Menyindir anggota senior dalam rapat","B. Mendorong semua ide dibahas berdasarkan data, menghargai pengalaman senior dan gagasan baru, serta menjaga suasana tetap hangat","C. Mendukung ide anggota muda saja, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","D. Diam agar rapat cepat selesai, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Memilih berkelompok dengan sesama anggota muda"],"ans":1,"scores":[2,5,4,3,1],"trick":"Kolaborasi menyatukan pengalaman dan gagasan baru.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Kolaborasi menyatukan pengalaman dan gagasan baru."},{"id":"SKD-TKP-0055","sub":"Jejaring Kerja","q":"Saat kerja kelompok, Anda mendapati satu anggota tidak mengerjakan bagiannya karena merasa tidak mampu. Sikap Anda adalah...","options":["A. Membiarkan bagian itu kosong","B. Mengejek anggota tersebut di depan tim","C. Mengajak berbincang, mencari tahu kesulitannya, membantu atau mengarahkannya ke rekan yang bisa membimbing, serta menyesuaikan pembagian tugas","D. Melaporkan ke atasan agar anggota itu diganti, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Mengambil alih bagian tersebut tanpa bicara, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":2,"scores":[2,1,5,3,4],"trick":"Dukung anggota yang kesulitan dan bagi tugas secara bijak.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), D (3), A (2), B (1). Dukung anggota yang kesulitan dan bagi tugas secara bijak."},{"id":"SKD-TKP-0061","sub":"Jejaring Kerja","q":"Seorang rekan mengajak Anda berkomplot menolak program pimpinan karena merasa kurang adil. Sikap Anda adalah...","options":["A. Menyebarkan ajakan itu ke rekan lain","B. Mendengarkan tanpa menanggapi, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Ikut menolak program agar tidak mengecewakan rekan","D. Mendengarkan keluhannya, menyarankan menyampaikan keberatan secara resmi dan terbuka kepada pimpinan, serta tidak ikut berkomplot","E. Menyetujui secara lisan tetapi tidak bertindak, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":3,"scores":[1,4,2,5,3],"trick":"Keberatan disalurkan lewat jalur resmi, bukan komplotan.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), E (3), C (2), A (1). Keberatan disalurkan lewat jalur resmi, bukan komplotan."},{"id":"SKD-TKP-0067","sub":"Jejaring Kerja","q":"Dalam rapat koordinasi lintas OPD, perwakilan dinas lain menolak berbagi data yang Anda butuhkan dengan alasan data itu milik mereka. Tindakan Anda adalah...","options":["A. Menyalahkan dinas tersebut dalam rapat","B. Mengumpulkan data dari sumber lain yang kurang akurat, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Menunda program sampai data diberikan","D. Meminta atasan menegur dinas tersebut, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menjelaskan tujuan bersama dan manfaat data bagi program, menawarkan perjanjian penggunaan data yang jelas, dan melaporkan hasilnya kepada atasan"],"ans":4,"scores":[1,3,2,4,5],"trick":"Bangun kepercayaan dan kesepahaman lewat tujuan bersama.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Bangun kepercayaan dan kesepahaman lewat tujuan bersama."},{"id":"SKD-TKP-0073","sub":"Jejaring Kerja","q":"Perwakilan instansi lain mengkritik hasil kerja unit Anda dalam forum terbuka dengan nada kurang sopan. Sikap Anda adalah...","options":["A. Tetap tenang, mengucapkan terima kasih atas masukan, meminta rincian, dan menindaklanjuti kritik yang valid secara terpisah","B. Meninggalkan ruang rapat","C. Membalas dengan nada serupa, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","D. Meminta atasan menanggapi, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menjawab kritik dengan data seadanya, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":0,"scores":[5,1,2,3,4],"trick":"Tanggapi kritik secara tenang dan konstruktif.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), C (2), B (1). Tanggapi kritik secara tenang dan konstruktif."},{"id":"SKD-TKP-0079","sub":"Jejaring Kerja","q":"Seorang atasan dari unit lain memberi Anda tugas tambahan langsung tanpa melalui atasan Anda. Tindakan Anda adalah...","options":["A. Mengerjakan tugas itu diam-diam, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menyampaikan kesediaan membantu, memberi tahu atasan langsung agar disepakati bersama, lalu mengatur prioritas","C. Menunda tugas sampai ada perintah resmi, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Mengerjakan tugas itu dan mengabaikan tugas utama","E. Menolak mentah-mentah tugas tersebut, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":1,"scores":[4,5,2,1,3],"trick":"Koordinasikan tugas lintas unit lewat atasan langsung.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), E (3), C (2), D (1). Koordinasikan tugas lintas unit lewat atasan langsung."},{"id":"SKD-TKP-0085","sub":"Jejaring Kerja","q":"Dalam rapat, rekan dari bagian lain mengutip data yang tampak keliru. Menurut Anda, mengoreksinya akan memalukan rekan tersebut. Tindakan Anda adalah...","options":["A. Menggunakan kekeliruan itu untuk menjatuhkan rekan","B. Menyampaikan koreksi setelah rapat secara pribadi, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Mengonfirmasi data terlebih dahulu, lalu menyampaikan koreksi dengan sopan dan menawarkan membandingkan sumber data bersama","D. Mengoreksi dengan menyebut rekan itu salah","E. Membiarkan agar rapat tidak terganggu, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":2,"scores":[1,4,5,2,3],"trick":"Koreksi data demi kualitas keputusan, dengan etika yang baik.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Koreksi data demi kualitas keputusan, dengan etika yang baik."},{"id":"SKD-TKP-0091","sub":"Jejaring Kerja","q":"Anda ditugaskan mengoordinasikan acara bersama tiga instansi, tetapi tiap instansi mengusulkan tanggal berbeda. Sikap Anda adalah...","options":["A. Menetapkan tanggal berdasarkan mayoritas, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Menunggu sampai instansi menyepakati sendiri, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Menetapkan tanggal sepihak sesuai kenyamanan Anda, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","D. Mengumpulkan kendala masing-masing, memetakan tanggal yang paling memungkinkan, dan memfasilitasi kesepakatan bersama secara tertulis","E. Membatalkan acara bersama"],"ans":3,"scores":[4,3,2,5,1],"trick":"Fasilitasi kesepakatan dengan data kendala semua pihak.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), B (3), C (2), E (1). Fasilitasi kesepakatan dengan data kendala semua pihak."},{"id":"SKD-TKP-0097","sub":"Jejaring Kerja","q":"Anda diminta menyelesaikan laporan proyek bersama, tetapi rekan mitra tidak menanggapi pesan Anda selama tiga hari. Tindakan Anda adalah...","options":["A. Melaporkan mitra kepada atasan Anda saja","B. Mengirim pesan lagi dan menunggu, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","C. Menyelesaikan laporan tanpa melibatkan mitra, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menghentikan laporan sampai mitra membalas","E. Mencoba kanal komunikasi lain, menghubungi atasannya secara sopan jika perlu, dan menyiapkan rencana cadangan agar laporan tetap selesai"],"ans":4,"scores":[2,4,3,1,5],"trick":"Gunakan beberapa jalur komunikasi dan siapkan rencana cadangan.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), C (3), A (2), D (1). Gunakan beberapa jalur komunikasi dan siapkan rencana cadangan."},{"id":"SKD-TKP-0103","sub":"Jejaring Kerja","q":"Dalam tim Anda ada dua orang yang selalu berbeda pendapat dan membuat rapat berlarut-larut. Sebagai ketua tim, tindakan Anda adalah...","options":["A. Menetapkan agenda dan batas waktu diskusi, mengarahkan pada data, serta memutuskan secara adil bila tidak tercapai mufakat","B. Selalu memihak pendapat yang lebih cepat, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Memisahkan mereka ke dalam tugas berbeda, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Menunda keputusan sampai mereka sepakat, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Menghentikan rapat tim secara rutin"],"ans":0,"scores":[5,2,4,3,1],"trick":"Pemimpin memfasilitasi diskusi produktif dan mengambil keputusan adil.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), B (2), E (1). Pemimpin memfasilitasi diskusi produktif dan mengambil keputusan adil."},{"id":"SKD-TKP-0109","sub":"Jejaring Kerja","q":"Instansi Anda bekerja sama dengan beberapa komunitas untuk program lingkungan. Salah satu komunitas mengundurkan diri karena merasa kontribusinya tidak dihargai. Tindakan Anda adalah...","options":["A. Menjelekkan komunitas itu kepada mitra lain","B. Mendengarkan alasan komunitas itu, mengakui kekurangan komunikasi, dan mengajak kembali dengan peran yang lebih jelas","C. Mengirim ucapan terima kasih atas kontribusi sebelumnya, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menerima pengunduran diri tanpa tindak lanjut, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Menyalahkan komunitas tersebut, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":1,"scores":[1,5,4,3,2],"trick":"Pelihara hubungan dengan mitra lewat komunikasi yang jujur.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), E (2), A (1). Pelihara hubungan dengan mitra lewat komunikasi yang jujur."},{"id":"SKD-TKP-0115","sub":"Jejaring Kerja","q":"Dalam penyusunan dokumen bersama, rekan dari instansi mitra terlambat mengirim bagiannya sehingga seluruh jadwal terganggu. Tindakan Anda adalah...","options":["A. Melaporkan keterlambatan kepada atasan mitra tanpa komunikasi","B. Menyelesaikan bagian rekan itu sendiri tanpa memberi tahu, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menghubungi rekan itu untuk memahami kendalanya, menawarkan bantuan, menetapkan tenggat baru bersama, dan melaporkan perkembangan kepada atasan","D. Menghentikan penyusunan dokumen","E. Menegur melalui pesan singkat agar segera mengirim, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":2,"scores":[2,3,5,1,4],"trick":"Kolaborasi lintas instansi butuh komunikasi dan solusi bersama.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), B (3), A (2), D (1). Kolaborasi lintas instansi butuh komunikasi dan solusi bersama."},{"id":"SKD-TKP-0121","sub":"Jejaring Kerja","q":"Anda mengetahui rekan dari bagian lain memerlukan informasi penting yang ada pada Anda, tetapi ia tidak meminta karena sungkan. Sikap Anda adalah...","options":["A. Menyampaikan informasi kepada atasan saja","B. Menunggu sampai ia meminta","C. Menyembunyikan informasi agar unit lain tidak lebih unggul","D. Menawarkan dan membagikan informasi tersebut sesuai ketentuan, serta memastikan ia memahami penggunaannya","E. Menyimpan informasi untuk keuntungan unit sendiri"],"ans":3,"scores":[3,4,1,5,2],"trick":"Berbagi informasi memperkuat kerja bersama.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), A (3), E (2), C (1). Berbagi informasi memperkuat kerja bersama."},{"id":"SKD-TKP-0127","sub":"Jejaring Kerja","q":"Anda tergabung dalam satgas penanganan bencana lintas instansi. Dua instansi saling menunggu siapa yang memulai distribusi logistik. Tindakan Anda adalah...","options":["A. Menunggu sampai kedua instansi sepakat","B. Menghentikan distribusi sementara","C. Menunggu arahan komandan satgas","D. Menyalahkan salah satu instansi","E. Mengambil inisiatif berkoordinasi, mengusulkan pembagian peran sementara, dan memastikan distribusi logistik segera berjalan"],"ans":4,"scores":[2,1,4,3,5],"trick":"Dalam kondisi darurat, koordinasi cepat dan proaktif.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), A (2), B (1). Dalam kondisi darurat, koordinasi cepat dan proaktif."},{"id":"SKD-TKP-0133","sub":"Jejaring Kerja","q":"Pada rapat tim, usul Anda ditolak mayoritas anggota, padahal Anda yakin usul tersebut lebih baik. Sikap Anda adalah...","options":["A. Menerima keputusan tim, menanyakan alasan penolakan agar dapat belajar, dan mendukung pelaksanaan hasil rapat","B. Mengusulkan ulang di rapat berikutnya tanpa alasan baru, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Melaksanakan usul Anda sendiri secara diam-diam","D. Menolak bekerja sama dengan tim","E. Menerima keputusan tetapi tidak ikut terlibat, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":0,"scores":[5,3,2,1,4],"trick":"Keputusan bersama dihormati; belajar dari masukan.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), C (2), D (1). Keputusan bersama dihormati; belajar dari masukan."},{"id":"SKD-TKP-0139","sub":"Jejaring Kerja","q":"Atasan Anda mengambil keputusan yang menurut Anda kurang tepat tanpa meminta masukan tim. Sikap Anda adalah...","options":["A. Menjalankan keputusan tanpa memberi masukan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Menyampaikan pandangan dengan data kepada atasan secara pribadi dan sopan, lalu mendukung keputusan akhir yang ditetapkan","C. Menolak menjalankan keputusan tersebut, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menyebarkan ketidaksetujuan ke unit lain","E. Melaksanakan keputusan sambil mengeluh ke rekan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":1,"scores":[3,5,2,1,4],"trick":"Sampaikan masukan dengan cara tepat; hormati keputusan akhir.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), A (3), C (2), D (1). Sampaikan masukan dengan cara tepat; hormati keputusan akhir."},{"id":"SKD-TKP-0145","sub":"Jejaring Kerja","q":"Anda menyadari rekan satu tim sedang menghadapi masalah pribadi sehingga kinerjanya menurun. Tim mulai mengeluh. Sikap Anda adalah...","options":["A. Meminta tim memaklumi tanpa mencari solusi, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Memberi rekan waktu tanpa membicarakannya, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Mengajak rekan berbincang dengan empati, menawarkan bantuan yang wajar, dan menyampaikan kondisi tim kepada atasan agar beban dibagi secara adil","D. Menyebarkan masalah pribadi rekan kepada anggota lain","E. Menegur keras karena merugikan tim"],"ans":2,"scores":[3,4,5,1,2],"trick":"Empati dan pembagian beban kerja yang adil.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), E (2), D (1). Empati dan pembagian beban kerja yang adil."},{"id":"SKD-TKP-0151","sub":"Jejaring Kerja","q":"Anda menghadiri forum koordinasi daerah. Wakil dari satu instansi mendominasi pembicaraan sehingga masukan lain tidak terdengar. Tindakan Anda adalah...","options":["A. Diam karena ingin menghindari ketegangan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Menyampaikan masukan setelah forum berakhir kepada panitia, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Meninggalkan forum sebagai protes","D. Menyampaikan pandangan secara santun, mengusulkan pembagian waktu bicara yang adil, dan mengajak peserta lain memberi masukan","E. Memotong pembicaraan agar giliran Anda tiba, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":3,"scores":[3,4,1,5,2],"trick":"Dorong forum yang adil dan terbuka.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), A (3), E (2), C (1). Dorong forum yang adil dan terbuka."},{"id":"SKD-TKP-0157","sub":"Jejaring Kerja","q":"Anda menerima permintaan bantuan dari unit lain padahal pekerjaan Anda sendiri sedang padat dengan tenggat dekat. Sikap Anda adalah...","options":["A. Menunda jawaban tanpa kepastian, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Mengabaikan permintaan itu","C. Menerima lalu mengerjakannya sambil mengorbankan tugas sendiri, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Menolak karena pekerjaan sendiri belum selesai, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Memetakan prioritas, menjelaskan kondisi beban kerja, lalu menawarkan bantuan pada waktu yang realistis atau mencarikan rekan yang bisa membantu"],"ans":4,"scores":[2,1,3,4,5],"trick":"Bantu dengan prioritas jelas dan komunikasi terbuka.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), A (2), B (1). Bantu dengan prioritas jelas dan komunikasi terbuka."},{"id":"SKD-TKP-0163","sub":"Jejaring Kerja","q":"Anda memenangkan penghargaan inovasi dan rekan-rekan yang ikut berkontribusi merasa kurang dihargai. Tindakan Anda adalah...","options":["A. Mengakui kontribusi mereka secara terbuka, mengucapkan terima kasih, dan berbagi manfaat penghargaan seperti presentasi atau pelatihan bersama","B. Mengatakan penghargaan itu kebetulan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Meminta maaf secara pribadi, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Mengabaikan perasaan rekan","E. Menjelaskan bahwa kontribusi Anda yang terbesar, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan"],"ans":0,"scores":[5,3,4,1,2],"trick":"Penghargaan bersama memupuk kerja sama.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), E (2), D (1). Penghargaan bersama memupuk kerja sama."},{"id":"SKD-TKP-0169","sub":"Jejaring Kerja","q":"Atasan langsung Anda dan atasan unit lain memberi instruksi yang berbeda untuk satu pekerjaan yang sama. Tindakan Anda adalah...","options":["A. Menjalankan instruksi atasan langsung saja","B. Meminta kedua atasan membahas bersama, menyampaikan alasan perbedaan, lalu menjalankan keputusan yang disepakati","C. Mengerjakan keduanya sekaligus","D. Menunda pekerjaan sampai mereka berdamai sendiri","E. Menjalankan instruksi atasan yang lebih tinggi tanpa konfirmasi"],"ans":1,"scores":[4,5,3,1,2],"trick":"Klarifikasi perbedaan instruksi lewat komunikasi terbuka.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), E (2), D (1). Klarifikasi perbedaan instruksi lewat komunikasi terbuka."},{"id":"SKD-TKP-0175","sub":"Jejaring Kerja","q":"Anda baru saja menyelesaikan proyek besar bersama tim. Pimpinan meminta Anda berbagi pengalaman dalam forum internal. Sikap Anda adalah...","options":["A. Mempresentasikan keberhasilan saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Menyerahkan presentasi kepada rekan lain, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Menyiapkan paparan yang jujur tentang keberhasilan dan kendala, melibatkan rekan tim, dan membuka diskusi untuk pembelajaran bersama","D. Menolak karena merasa tidak punya waktu","E. Menyampaikan hanya bagian yang Anda kerjakan"],"ans":2,"scores":[4,3,5,2,1],"trick":"Berbagi pembelajaran menguatkan jejaring.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), D (2), E (1). Berbagi pembelajaran menguatkan jejaring."},{"id":"SKD-TKP-0181","sub":"Jejaring Kerja","q":"Pimpinan memberi pujian kepada Anda atas hasil kerja tim, padahal sebagian besar ide berasal dari rekan Anda. Sikap Anda adalah...","options":["A. Menerima pujian tanpa komentar, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Mengatakan pujian itu berlebihan lalu pergi","C. Menerima pujian dan membaginya ke rekan secara pribadi, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Berterima kasih, lalu menyebutkan kontribusi rekan satu per satu agar pimpinan mengetahui peran tiap anggota","E. Mengklaim hasil sebagai prestasi pribadi"],"ans":3,"scores":[3,2,4,5,1],"trick":"Berbagi penghargaan memperkuat kerja sama.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), A (3), B (2), E (1). Berbagi penghargaan memperkuat kerja sama."},{"id":"SKD-TKP-0187","sub":"Jejaring Kerja","q":"Anda menerima kabar dari rekan bahwa ada kesalahan dalam data bersama antar instansi, tetapi pembuat data adalah rekan dari unit lain yang Anda segani. Tindakan Anda adalah...","options":["A. Memperbaiki data sendiri tanpa memberi tahu, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menyebarkan kesalahan itu ke grup besar","C. Melaporkan kepada atasan tanpa memberi tahu pembuat data, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Membiarkan karena sungkan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Memverifikasi kesalahan, menyampaikannya kepada pembuat data secara sopan dengan bukti, dan membantu perbaikannya"],"ans":4,"scores":[4,1,3,2,5],"trick":"Koreksi kesalahan dengan cara santun dan berbasis bukti.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), C (3), D (2), B (1). Koreksi kesalahan dengan cara santun dan berbasis bukti."},{"id":"SKD-TKP-0193","sub":"Jejaring Kerja","q":"Dalam kegiatan bersama LSM lokal, Anda menemukan bahwa pendekatan mereka berbeda dengan prosedur instansi Anda. Tindakan Anda adalah...","options":["A. Mendiskusikan perbedaan pendekatan, mencari titik temu yang tetap sesuai aturan, dan mendokumentasikan kesepakatan","B. Mengikuti pendekatan LSM agar kegiatan berjalan cepat, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Mengkritik LSM di media sosial","D. Mengikuti prosedur instansi saja, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Menghentikan kerja sama tanpa diskusi, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":0,"scores":[5,3,1,4,2],"trick":"Cari titik temu tanpa melanggar aturan instansi.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Cari titik temu tanpa melanggar aturan instansi."},{"id":"SKD-TKP-0199","sub":"Jejaring Kerja","q":"Seorang rekan sering mengklaim hasil kerja tim sebagai hasil pribadi di hadapan pimpinan. Anda mengetahuinya. Sikap Anda adalah...","options":["A. Menjelek-jelekkan rekan tersebut di grup kantor","B. Berbicara baik-baik dengan rekan tersebut, lalu memastikan pembagian peran tim terdokumentasi dan diketahui pimpinan","C. Membalas dengan mengklaim hasil kerja rekan lain, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","D. Menyampaikan keberatan secara terbuka di depan pimpinan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Mendiamkan demi menjaga hubungan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":1,"scores":[1,5,2,4,3],"trick":"Selesaikan secara dewasa dan tuntaskan lewat dokumentasi peran.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), E (3), C (2), A (1). Selesaikan secara dewasa dan tuntaskan lewat dokumentasi peran."},{"id":"SKD-TKP-0205","sub":"Jejaring Kerja","q":"Anda ingin mengajak rekan dari berbagai unit membuat komunitas belajar internal, tetapi beberapa rekan menganggapnya menambah beban. Tindakan Anda adalah...","options":["A. Mengajak rekan yang antusias saja, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Memaksa seluruh rekan mengikuti kegiatan","C. Menjelaskan manfaat komunitas belajar, memulai dengan kegiatan ringan yang fleksibel, dan meminta dukungan pimpinan","D. Membatalkan rencana karena kurang dukungan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Menuduh rekan yang menolak tidak peduli perkembangan"],"ans":2,"scores":[4,2,5,3,1],"trick":"Ajak dengan manfaat nyata dan pendekatan fleksibel.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), B (2), E (1). Ajak dengan manfaat nyata dan pendekatan fleksibel."},{"id":"SKD-TKP-0211","sub":"Jejaring Kerja","q":"Anda diminta menjadi penghubung antara instansi Anda dan pemerintah desa dalam pelaksanaan program. Aparat desa sering telat memberi laporan. Sikap Anda adalah...","options":["A. Melaporkan keterlambatan kepada atasan tanpa membantu","B. Menghentikan bantuan program ke desa tersebut","C. Membuat laporan sendiri atas nama desa, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Membantu menyederhanakan format laporan, memberikan pendampingan, dan menyepakati jadwal pelaporan yang realistis","E. Mengingatkan setiap kali tenggat mendekat, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":3,"scores":[2,1,3,5,4],"trick":"Dampingi mitra agar mampu memenuhi kewajiban.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), A (2), B (1). Dampingi mitra agar mampu memenuhi kewajiban."},{"id":"SKD-TKP-0217","sub":"Jejaring Kerja","q":"Anda melihat rekan lain sedang kesulitan menyelesaikan aplikasi laporan, sementara Anda ahli di bidang tersebut tetapi bukan tugas Anda. Tindakan Anda adalah...","options":["A. Mengerjakan sendiri lalu meminta imbalan","B. Mengabaikan karena bukan tugas Anda, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Menyuruhnya membaca panduan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Membantu hanya jika ia meminta, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menawarkan bantuan, memandunya langkah demi langkah, dan berbagi panduan sederhana agar ia mandiri di lain waktu"],"ans":4,"scores":[1,2,3,4,5],"trick":"Berbagi pengetahuan memperkuat tim.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), B (2), A (1). Berbagi pengetahuan memperkuat tim."},{"id":"SKD-TKP-0223","sub":"Jejaring Kerja","q":"Anda menjadi koordinator kegiatan lintas bidang. Seorang anggota meminta kegiatan ditunda karena kesibukannya, padahal tim lain sudah siap. Tindakan Anda adalah...","options":["A. Membahas kemungkinan penyesuaian peran, mencari solusi pengganti sementara, dan memastikan jadwal kegiatan tetap terjaga","B. Meminta anggota itu mengundurkan diri","C. Menunda kegiatan sesuai permintaan, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Membatalkan kegiatan tanpa konsultasi","E. Menolak permintaan dan melanjutkan tanpa anggota itu, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh"],"ans":0,"scores":[5,2,4,1,3],"trick":"Koordinator mencari solusi tanpa mengorbankan target tim.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), E (3), B (2), D (1). Koordinator mencari solusi tanpa mengorbankan target tim."},{"id":"SKD-TKP-0229","sub":"Jejaring Kerja","q":"Pada pekerjaan tim, ada aturan baru dari pimpinan yang menurut sebagian rekan memberatkan. Mereka meminta Anda mewakili menyampaikan keberatan. Tindakan Anda adalah...","options":["A. Menyuruh rekan menyampaikan sendiri-sendiri, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","B. Mengumpulkan masukan rekan secara obyektif, menyusun usulan solusi, dan menyampaikan kepada pimpinan dengan sopan","C. Menyampaikan keberatan apa adanya tanpa usulan, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Memimpin penolakan terhadap aturan","E. Menolak mewakili karena takut dinilai buruk, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":1,"scores":[2,5,4,1,3],"trick":"Aspirasi disampaikan konstruktif dengan solusi.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), E (3), A (2), D (1). Aspirasi disampaikan konstruktif dengan solusi."},{"id":"SKD-TKP-0235","sub":"Jejaring Kerja","q":"Rekan satu tim Anda tiba-tiba sakit saat tenggat laporan tim tinggal dua hari, dan bagiannya belum dikerjakan. Sikap Anda adalah...","options":["A. Menyalahkan rekan atas keterlambatan tim","B. Melaporkan ke atasan agar bagian itu dibatalkan","C. Mengambil alih bagian yang mendesak, membagi sisa tugas dengan anggota lain, dan mengabari atasan serta rekan yang sakit tentang perkembangannya","D. Menyelesaikan seluruh bagiannya sendiri tanpa memberi tahu siapa pun, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menunggu rekan sembuh, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":2,"scores":[1,2,5,4,3],"trick":"Tim saling menopang demi target bersama.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), B (2), A (1). Tim saling menopang demi target bersama."},{"id":"SKD-TKP-0241","sub":"Jejaring Kerja","q":"Anda ingin meminta bantuan rekan unit lain untuk menyelesaikan tugas teknis, tetapi hubungan kedua unit sedang kurang baik. Tindakan Anda adalah...","options":["A. Menyalahkan unit tersebut atas keterlambatan","B. Mencari bantuan dari pihak luar, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Mengerjakan sendiri meski tidak mampu, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","D. Menyampaikan permintaan dengan sopan dan jelas, menjelaskan manfaatnya bagi kedua unit, serta menawarkan timbal balik bantuan","E. Meminta atasan menugaskan rekan tersebut, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[1,3,2,5,4],"trick":"Bangun hubungan lewat komunikasi positif dan timbal balik.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), C (2), A (1). Bangun hubungan lewat komunikasi positif dan timbal balik."},{"id":"SKD-TKP-0247","sub":"Jejaring Kerja","q":"Seorang rekan baru dari instansi lain bergabung dalam tim lintas fungsi dan belum memahami budaya kerja instansi Anda. Tindakan Anda adalah...","options":["A. Meminta rekan itu menyesuaikan diri sendiri, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menjelaskan hanya hal yang ia tanyakan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Membiarkan ia belajar dari kesalahan, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","D. Mengeluhkan perilakunya kepada rekan lain","E. Menjelaskan alur dan kebiasaan kerja dengan ramah, memperkenalkan ke tim, dan terbuka terhadap cara kerja yang ia bawa"],"ans":4,"scores":[4,3,2,1,5],"trick":"Sambut anggota baru dan bangun kerja sama.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), B (3), C (2), D (1). Sambut anggota baru dan bangun kerja sama."},{"id":"SKD-TKP-0253","sub":"Jejaring Kerja","q":"Mitra swasta dalam proyek bersama instansi Anda meminta perubahan jadwal sepihak yang berpotensi mengganggu target. Tindakan Anda adalah...","options":["A. Mengadakan pertemuan untuk membahas alasan, mencari jadwal alternatif bersama, dan memastikan kesepakatan dituangkan secara tertulis","B. Membatalkan proyek tanpa sepengetahuan atasan","C. Menolak perubahan karena sudah ada perjanjian, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Menyetujui perubahan agar hubungan baik, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Memutus kerja sama"],"ans":0,"scores":[5,1,4,3,2],"trick":"Selesaikan perbedaan lewat dialog dan kesepakatan tertulis.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Selesaikan perbedaan lewat dialog dan kesepakatan tertulis."},{"id":"SKD-TKP-0259","sub":"Jejaring Kerja","q":"Anda ditunjuk memimpin tim yang beranggotakan orang-orang dari beberapa instansi. Pada pertemuan pertama, tampak anggota enggan berbicara. Tindakan Anda adalah...","options":["A. Membatalkan pertemuan karena tidak produktif","B. Memperkenalkan tujuan, membangun suasana akrab, meminta masukan tiap anggota, dan menyepakati aturan kerja bersama","C. Langsung membagi tugas agar efisien, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Menunggu anggota membuka pembicaraan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Menugaskan satu anggota menjadi juru bicara"],"ans":1,"scores":[1,5,4,3,2],"trick":"Kepemimpinan kolaboratif dimulai dari membangun komunikasi.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), E (2), A (1). Kepemimpinan kolaboratif dimulai dari membangun komunikasi."},{"id":"SKD-TKP-0265","sub":"Jejaring Kerja","q":"Dua unit di instansi Anda berselisih mengenai siapa yang bertanggung jawab atas suatu kegiatan, sementara kegiatan harus berjalan minggu depan. Anda berada di unit yang netral. Tindakan Anda adalah...","options":["A. Menunggu mereka menyelesaikan sendiri, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","B. Meminta pimpinan memutuskan tanpa upaya mediasi, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Memfasilitasi pertemuan kedua unit, merujuk pada aturan tugas dan fungsi, serta membantu menyepakati pembagian peran","D. Mendukung unit yang lebih berpengaruh, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Membiarkan kegiatan tertunda"],"ans":2,"scores":[3,4,5,2,1],"trick":"Netral memfasilitasi penyelesaian berdasarkan aturan.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), D (2), E (1). Netral memfasilitasi penyelesaian berdasarkan aturan."},{"id":"SKD-TKP-0271","sub":"Jejaring Kerja","q":"Seorang rekan dari instansi mitra meminta Anda mengirim dokumen internal yang belum dipublikasikan agar pekerjaan mereka lebih cepat. Tindakan Anda adalah...","options":["A. Menolak sambil meminta rekan mengajukan surat resmi, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menjual dokumen kepada pihak lain","C. Mengirim dokumen secara diam-diam lewat pesan pribadi","D. Menanyakan kebutuhan dan alasannya, meminta izin atasan, dan mengirim dokumen melalui jalur resmi bila diizinkan","E. Mengirim sebagian isi dokumen, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":3,"scores":[4,1,2,5,3],"trick":"Berbagi dokumen internal harus melalui izin dan jalur resmi.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), E (3), C (2), B (1). Berbagi dokumen internal harus melalui izin dan jalur resmi."},{"id":"SKD-TKP-0277","sub":"Jejaring Kerja","q":"Rapat tim berlangsung tegang karena dua rekan saling menyalahkan atas keterlambatan proyek. Anda anggota tim. Tindakan Anda adalah...","options":["A. Ikut menyalahkan salah satu rekan","B. Diam hingga rapat selesai, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Meminta rapat dihentikan sementara, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Memihak rekan yang Anda anggap benar, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Mengajak fokus pada fakta dan solusi, mengusulkan penyusunan jadwal ulang bersama, dan tidak berpihak pada salah satu rekan"],"ans":4,"scores":[1,2,4,3,5],"trick":"Arahkan konflik menjadi pencarian solusi.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), B (2), A (1). Arahkan konflik menjadi pencarian solusi."},{"id":"SKD-TKP-0283","sub":"Jejaring Kerja","q":"Anda ditugaskan membuat jadwal piket bersama untuk tim yang beranggotakan beberapa karakter berbeda. Beberapa rekan meminta pengecualian tanpa alasan jelas. Tindakan Anda adalah...","options":["A. Menyusun jadwal berdasarkan prinsip keadilan, mendengarkan alasan yang valid, dan menjelaskan kriteria pengecualian kepada seluruh tim","B. Menolak semua permintaan pengecualian, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Mengatur jadwal sesuai kedekatan pribadi","D. Menuruti semua permintaan agar tidak ada keluhan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Menyerahkan penyusunan jadwal kepada atasan"],"ans":0,"scores":[5,3,1,4,2],"trick":"Keadilan dan transparansi dalam pembagian tugas.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Keadilan dan transparansi dalam pembagian tugas."},{"id":"SKD-TKP-0289","sub":"Jejaring Kerja","q":"Dalam grup kerja daring, dua rekan berdebat sengit dan saling menyerang pribadi sehingga anggota lain tidak nyaman. Tindakan Anda adalah...","options":["A. Mengingatkan aturan etika grup secara umum","B. Meredakan suasana di grup, mengajak fokus pada pokok masalah, lalu menawarkan mediasi pribadi untuk keduanya","C. Keluar dari grup sementara","D. Memihak salah satu rekan","E. Memanas-manasi perdebatan agar cepat selesai"],"ans":1,"scores":[4,5,3,2,1],"trick":"Redakan konflik dan arahkan pada solusi.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), D (2), E (1). Redakan konflik dan arahkan pada solusi."},{"id":"SKD-TKP-0295","sub":"Jejaring Kerja","q":"Ketika membangun jejaring dengan pihak swasta, seorang pengusaha menawarkan fasilitas pribadi sebagai ucapan terima kasih atas kerja sama. Sikap Anda adalah...","options":["A. Menerima tetapi tidak menggunakannya, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Menerima atas nama instansi tanpa pencatatan, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Menolak dengan sopan, menjelaskan aturan gratifikasi, dan melaporkannya sesuai ketentuan bila telah terlanjur diterima","D. Menolak halus tanpa menjelaskan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Menerima karena sudah menjadi kebiasaan"],"ans":2,"scores":[3,2,5,4,1],"trick":"Jejaring kerja tidak boleh mengorbankan integritas.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), B (2), E (1). Jejaring kerja tidak boleh mengorbankan integritas."},{"id":"SKD-TKP-0301","sub":"Jejaring Kerja","q":"Anda baru dipindahkan ke unit baru dan melihat rekan-rekan sudah punya kelompok pertemanan yang erat sehingga Anda merasa canggung. Tindakan Anda adalah...","options":["A. Menunggu rekan lain mengajak bicara, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Bergaul hanya dengan rekan dari unit lama, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Mengajukan permohonan kembali ke unit lama","D. Memperkenalkan diri, aktif membantu pekerjaan tim, dan mengikuti kegiatan bersama dengan sikap terbuka","E. Menghindari interaksi dan bekerja sendiri"],"ans":3,"scores":[4,3,2,5,1],"trick":"Adaptasi aktif dengan inisiatif membangun hubungan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), B (3), C (2), E (1). Adaptasi aktif dengan inisiatif membangun hubungan."},{"id":"SKD-TKP-0307","sub":"Jejaring Kerja","q":"Anda ditugaskan menghubungi pemangku kepentingan di desa untuk program baru, tetapi kepala desa tampak tidak antusias. Sikap Anda adalah...","options":["A. Melaksanakan program tanpa persetujuan desa","B. Mengirim surat resmi lalu menunggu tanggapan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","C. Memilih desa lain tanpa membicarakannya","D. Meminta camat menekan kepala desa, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Mendengarkan kekhawatiran kepala desa, menjelaskan manfaat program secara konkret, dan melibatkannya dalam perencanaan"],"ans":4,"scores":[2,4,1,3,5],"trick":"Libatkan pemangku kepentingan sejak awal.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), D (3), A (2), C (1). Libatkan pemangku kepentingan sejak awal."},{"id":"SKD-TKP-0313","sub":"Jejaring Kerja","q":"Anda ditunjuk menjadi juru bicara tim dalam pertemuan dengan masyarakat, tetapi beberapa warga menyampaikan kritik tajam atas kebijakan instansi. Sikap Anda adalah...","options":["A. Mendengarkan dengan terbuka, mencatat masukan, menjelaskan kebijakan secara jelas, dan menjanjikan tindak lanjut yang realistis","B. Menghentikan pertemuan","C. Menyerahkan kritik kepada atasan tanpa menanggapi, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Membela kebijakan secara emosional, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","E. Menjelaskan kebijakan dan mempersilakan warga menyampaikan tertulis, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":0,"scores":[5,1,3,2,4],"trick":"Dialog terbuka membangun kepercayaan publik.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), D (2), B (1). Dialog terbuka membangun kepercayaan publik."},{"id":"SKD-TKP-0319","sub":"Jejaring Kerja","q":"Anda baru mengetahui bahwa rekan yang dekat dengan Anda melakukan kesalahan prosedur yang berpotensi merugikan tim. Sikap Anda adalah...","options":["A. Melaporkan kepada atasan tanpa memberi tahu rekan","B. Mengingatkan rekan secara langsung, membantu memperbaiki, dan melaporkan kepada atasan jika kesalahan berpotensi merugikan tim atau instansi","C. Menyalahkan rekan di depan tim","D. Mengingatkan rekan lalu membiarkannya, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Memperbaiki kesalahan itu sendiri secara diam-diam agar tim tidak terkena dampak, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":1,"scores":[2,5,1,4,3],"trick":"Persahabatan tidak boleh menutupi pelanggaran.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), E (3), A (2), C (1). Persahabatan tidak boleh menutupi pelanggaran."},{"id":"SKD-TKP-0325","sub":"Jejaring Kerja","q":"Dalam kegiatan bakti sosial bersama, anggota tim dari agama berbeda mengusulkan jadwal yang bentrok dengan ibadah sebagian anggota. Tindakan Anda adalah...","options":["A. Menjalankan jadwal awal karena sudah diumumkan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Mengecualikan anggota yang tidak bisa hadir, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Meminta masukan seluruh anggota, menyesuaikan jadwal agar semua dapat hadir, dan menjaga kegiatan tetap inklusif","D. Mengikuti usulan mayoritas anggota, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Membatalkan kegiatan"],"ans":2,"scores":[3,2,5,4,1],"trick":"Jadwal kegiatan menghormati keragaman anggota tim.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), B (2), E (1). Jadwal kegiatan menghormati keragaman anggota tim."},{"id":"SKD-TKP-0331","sub":"Jejaring Kerja","q":"Anda diminta menjadi mentor bagi CPNS baru yang tampak pemalu dan sering membuat kesalahan administrasi. Sikap Anda adalah...","options":["A. Menegur keras setiap kesalahan","B. Mengambil alih seluruh tugasnya tanpa penjelasan","C. Memberi tugas dan memeriksa hasilnya di akhir","D. Menjelaskan standar kerja dengan sabar, memberi contoh, meminta ia bertanya kapan saja, dan memberi umpan balik secara berkala","E. Meminta rekan senior lain membimbingnya"],"ans":3,"scores":[2,1,4,5,3],"trick":"Mentoring yang suportif mempercepat pembelajaran.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), A (2), B (1). Mentoring yang suportif mempercepat pembelajaran."},{"id":"SKD-TKP-0337","sub":"Jejaring Kerja","q":"Anda mewakili instansi dalam pertemuan dengan mitra internasional. Saat berdiskusi, ada perbedaan kebiasaan komunikasi yang membuat pembicaraan kurang nyaman. Sikap Anda adalah...","options":["A. Meminta rekan lain menggantikan","B. Membatalkan pertemuan","C. Tetap memakai gaya komunikasi sendiri","D. Menegur mitra karena berbeda kebiasaan","E. Mempelajari etika komunikasi mitra, menyesuaikan gaya bicara dengan sopan, dan menjaga tujuan kerja sama tetap jelas"],"ans":4,"scores":[3,1,4,2,5],"trick":"Hargai perbedaan kebiasaan dalam jejaring internasional.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), A (3), D (2), B (1). Hargai perbedaan kebiasaan dalam jejaring internasional."},{"id":"SKD-TKP-0343","sub":"Jejaring Kerja","q":"Instansi Anda dan instansi lain memiliki program yang tumpang tindih di wilayah yang sama. Anda mengetahui hal itu dari data lapangan. Tindakan Anda adalah...","options":["A. Melaporkan temuan kepada atasan dan mengusulkan pertemuan koordinasi untuk menyinergikan program agar tidak tumpang tindih","B. Menyalahkan instansi lain di media","C. Menyampaikan temuan kepada rekan tanpa tindak lanjut, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Menghentikan program di wilayah tersebut","E. Menjalankan program sesuai rencana sambil mencatat temuan untuk dibahas pada evaluasi berikutnya, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":0,"scores":[5,1,3,2,4],"trick":"Sinergi program menghindari pemborosan sumber daya.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), D (2), B (1). Sinergi program menghindari pemborosan sumber daya."},{"id":"SKD-TKP-0349","sub":"Jejaring Kerja","q":"Di lingkungan kerja yang baru, atasan Anda meminta Anda berkolaborasi dengan rekan yang sebelumnya pernah berselisih dengan Anda. Sikap Anda adalah...","options":["A. Menolak bekerja sama","B. Bersikap profesional, membuka komunikasi dengan niat baik, dan memfokuskan kerja sama pada tujuan tim","C. Menghindari rekan tersebut selama bekerja","D. Meminta atasan mengganti rekan kerja, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menjalankan tugas seperlunya saja, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":1,"scores":[1,5,2,3,4],"trick":"Profesional memisahkan urusan pribadi dari tugas.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), C (2), A (1). Profesional memisahkan urusan pribadi dari tugas."},{"id":"SKD-TKP-0355","sub":"Jejaring Kerja","q":"Seorang relawan komunitas menawarkan bantuan untuk program instansi Anda, tetapi prosedur pelibatan relawan belum ada. Sikap Anda adalah...","options":["A. Menolak karena belum ada prosedur","B. Menggunakan relawan tanpa izin atasan","C. Menyambut tawaran, berkonsultasi dengan atasan untuk menentukan mekanisme pelibatan, dan mencatat peran relawan secara jelas","D. Menerima langsung tanpa aturan tertulis, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Meminta relawan menunggu sampai ada aturan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":2,"scores":[2,1,5,4,3],"trick":"Manfaatkan partisipasi masyarakat dengan tata kelola yang jelas.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), A (2), B (1). Manfaatkan partisipasi masyarakat dengan tata kelola yang jelas."},{"id":"SKD-TKP-0044","sub":"Sosial Budaya","q":"Anda tergabung dalam tim pembangunan jembatan desa. Warga meminta pekerjaan dihentikan saat acara adat besar berlangsung beberapa hari. Sikap Anda adalah...","options":["A. Berdiskusi dengan kontraktor dan tokoh adat, menyesuaikan jadwal kerja selama acara, dan memastikan target tetap terpantau","B. Menyalahkan warga atas keterlambatan","C. Meminta warga menunda acara","D. Melanjutkan pekerjaan dengan alasan target","E. Menghentikan pekerjaan tanpa koordinasi"],"ans":0,"scores":[5,1,2,3,4],"trick":"Selaraskan jadwal proyek dengan kearifan lokal.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), C (2), B (1). Selaraskan jadwal proyek dengan kearifan lokal."},{"id":"SKD-TKP-0050","sub":"Sosial Budaya","q":"Anda mengetahui ada kelompok warga tidak mampu yang tidak bisa mengikuti kegiatan karena biaya transportasi. Anda panitia kegiatan. Tindakan Anda adalah...","options":["A. Menyarankan warga patungan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Mengusulkan skema bantuan transportasi atau kegiatan jemput bola, dan memastikan seluruh kelompok dapat berpartisipasi","C. Mengabaikan karena bukan tanggung jawab panitia","D. Mengumumkan kegiatan terbuka untuk umum, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Menetapkan kegiatan hanya untuk yang mampu hadir"],"ans":1,"scores":[3,5,1,4,2],"trick":"Hilangkan hambatan partisipasi bagi kelompok rentan.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), A (3), E (2), C (1). Hilangkan hambatan partisipasi bagi kelompok rentan."},{"id":"SKD-TKP-0056","sub":"Sosial Budaya","q":"Anda ditempatkan di daerah dengan banyak penganut kepercayaan lokal. Seorang warga mengundang Anda ke upacara syukuran panen. Sikap Anda adalah...","options":["A. Hadir sebentar lalu pamit, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Mengejek upacara tersebut","C. Menghadiri dengan hormat, mengikuti tata krama yang sesuai, dan memanfaatkan kesempatan untuk mengenal warga lebih dekat","D. Mengirim ucapan terima kasih tanpa hadir, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menolak karena berbeda keyakinan tanpa penjelasan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":2,"scores":[4,1,5,3,2],"trick":"Hormati tradisi lokal dengan cara santun.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), E (2), B (1). Hormati tradisi lokal dengan cara santun."},{"id":"SKD-TKP-0062","sub":"Sosial Budaya","q":"Anda mengikuti diklat bersama peserta dari banyak daerah. Saat makan siang, kelompok peserta daerah tertentu duduk terpisah dan jarang bergaul. Tindakan Anda adalah...","options":["A. Membicarakan mereka di belakang","B. Ikut bergabung di kelompok daerah yang sama dengan Anda","C. Menganggap mereka kurang bergaul","D. Mengajak mereka bergabung dalam kegiatan kelompok, mencari kesamaan minat, dan menciptakan suasana nyaman bagi semua peserta","E. Menunggu mereka bergabung sendiri"],"ans":3,"scores":[1,3,2,5,4],"trick":"Inisiatif merangkul keberagaman peserta.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), C (2), A (1). Inisiatif merangkul keberagaman peserta."},{"id":"SKD-TKP-0068","sub":"Sosial Budaya","q":"Dalam program kesehatan, ibu-ibu desa menolak imunisasi karena kepercayaan turun-temurun. Anda adalah petugas yang mendampingi. Tindakan Anda adalah...","options":["A. Menyalahkan warga atas ketidaktahuan","B. Meninggalkan desa karena sulit","C. Meminta aparat desa memaksa warga, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Memberikan penyuluhan satu kali lalu menunggu keputusan warga, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Mendekati tokoh masyarakat, mendengarkan kekhawatiran, memberikan penyuluhan yang menghargai budaya, dan melakukan pendekatan berkelanjutan"],"ans":4,"scores":[1,2,3,4,5],"trick":"Pendekatan budaya dan edukasi berkelanjutan lebih efektif daripada paksaan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), B (2), A (1). Pendekatan budaya dan edukasi berkelanjutan lebih efektif daripada paksaan."},{"id":"SKD-TKP-0074","sub":"Sosial Budaya","q":"Warga dari dua kelompok etnis di desa binaan Anda berselisih karena masalah sepele yang mulai memanas. Anda berada di desa itu. Tindakan Anda adalah...","options":["A. Mendatangi tokoh dari kedua pihak, memfasilitasi dialog dengan netral, dan melibatkan aparat desa serta tokoh masyarakat untuk berdamai","B. Meminta aparat keamanan menangani","C. Menyampaikan kejadian itu kepada atasan saja","D. Memihak kelompok yang lebih dekat dengan Anda","E. Membiarkan konflik berkembang"],"ans":0,"scores":[5,4,3,2,1],"trick":"Mediasi netral oleh tokoh masyarakat meredam konflik dini.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), C (3), D (2), E (1). Mediasi netral oleh tokoh masyarakat meredam konflik dini."},{"id":"SKD-TKP-0080","sub":"Sosial Budaya","q":"Warga desa menggelar ritual adat yang menggunakan sebagian jalan utama sehingga lalu lintas terhambat. Anda petugas dinas perhubungan. Tindakan Anda adalah...","options":["A. Melarang ritual karena mengganggu lalu lintas","B. Berkoordinasi dengan panitia dan tokoh adat, mengatur pengalihan arus sementara, dan memberi informasi kepada pengguna jalan","C. Membiarkan kemacetan terjadi","D. Meminta ritual dipindah ke lokasi lain","E. Mengatur arus lalu lintas tanpa berbicara dengan panitia"],"ans":1,"scores":[2,5,1,3,4],"trick":"Hormati tradisi sambil mengatur kepentingan umum.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), A (2), C (1). Hormati tradisi sambil mengatur kepentingan umum."},{"id":"SKD-TKP-0086","sub":"Sosial Budaya","q":"Seorang rekan Anda berasal dari daerah dengan makanan khas yang baunya kuat, dan beberapa rekan mengeluh. Sikap Anda adalah...","options":["A. Meminta rekan makan di luar kantor, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Ikut mengeluh, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","C. Mengajak rekan lain memahami budaya makan rekan tersebut, serta bersama mencari kompromi tempat dan waktu makan yang nyaman","D. Mengejek makanan tersebut","E. Menyarankan rekan mengganti makanannya, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":2,"scores":[4,2,5,1,3],"trick":"Cari kompromi yang saling menghargai budaya.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), B (2), D (1). Cari kompromi yang saling menghargai budaya."},{"id":"SKD-TKP-0092","sub":"Sosial Budaya","q":"Anda menerima pesan berantai yang memuat stereotip negatif tentang suatu suku. Pengirimnya adalah rekan kantor. Sikap Anda adalah...","options":["A. Membiarkan pesan tanpa menanggapi, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","B. Menghapus pesan tanpa menanggapi, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Menambahkan komentar yang memperkuat stereotip","D. Tidak menyebarkan, menanggapi dengan sopan bahwa stereotip merugikan, dan mengingatkan agar tidak meneruskan pesan serupa","E. Meneruskan pesan ke teman terdekat"],"ans":3,"scores":[3,4,1,5,2],"trick":"Hentikan penyebaran stereotip dengan teguran santun.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), A (3), E (2), C (1). Hentikan penyebaran stereotip dengan teguran santun."},{"id":"SKD-TKP-0098","sub":"Sosial Budaya","q":"Di tempat kerja Anda ada rekan yang berasal dari keluarga kurang mampu dan sering dijauhi karena penampilannya sederhana. Sikap Anda adalah...","options":["A. Ikut mengucilkannya","B. Menjauhinya agar tidak ikut dikucilkan","C. Menyapanya jika bertemu","D. Menghindari konflik dengan tidak mencampuri","E. Mendekati dengan tulus, mengajak dalam kegiatan tim, dan mengingatkan rekan lain bahwa penilaian harus berdasarkan kinerja"],"ans":4,"scores":[1,2,4,3,5],"trick":"Kesetaraan tanpa memandang status sosial.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), B (2), A (1). Kesetaraan tanpa memandang status sosial."},{"id":"SKD-TKP-0104","sub":"Sosial Budaya","q":"Dalam rapat RT, warga menolak keberadaan rumah ibadah kelompok minoritas di lingkungan. Anda warga sekaligus ASN. Sikap Anda adalah...","options":["A. Mengingatkan hak kebebasan beribadah yang dijamin konstitusi, mengajak dialog dengan tokoh masyarakat, dan membantu mencari solusi sesuai aturan","B. Ikut memprovokasi penolakan","C. Menyarankan rumah ibadah dipindah ke tempat lain, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Mendengarkan tanpa berkomentar, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Mendukung penolakan agar tidak berkonflik"],"ans":0,"scores":[5,1,3,4,2],"trick":"Lindungi kebebasan beribadah lewat dialog dan aturan.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), C (3), E (2), B (1). Lindungi kebebasan beribadah lewat dialog dan aturan."},{"id":"SKD-TKP-0110","sub":"Sosial Budaya","q":"Anda ditempatkan di daerah dengan masyarakat adat yang menolak pembangunan fasilitas di tanah yang mereka anggap sakral. Sikap Anda adalah...","options":["A. Melaporkan penolakan itu kepada atasan dan menunggu keputusan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Mendengarkan tokoh adat, mempelajari nilai-nilai setempat, dan mencari alternatif lokasi bersama tanpa memaksakan rencana awal","C. Menganggap adat tersebut menghambat kemajuan","D. Menjelaskan manfaat pembangunan sampai mereka menerima, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Melanjutkan pembangunan dengan pengawalan petugas"],"ans":1,"scores":[3,5,1,4,2],"trick":"Hormati kearifan lokal dan cari solusi melalui dialog.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), A (3), E (2), C (1). Hormati kearifan lokal dan cari solusi melalui dialog."},{"id":"SKD-TKP-0116","sub":"Sosial Budaya","q":"Anda menjadi MC pada acara resmi instansi dan harus menyapa tamu dari berbagai agama dan budaya. Sikap Anda adalah...","options":["A. Menggunakan salam umum saja","B. Menggunakan salam dari agama mayoritas","C. Menyiapkan salam dan sapaan yang inklusif dan netral, mempelajari penyebutan yang benar, serta menghormati seluruh tamu","D. Menghindari menyapa agar tidak keliru","E. Menyindir kelompok tertentu sebagai candaan"],"ans":2,"scores":[4,3,5,2,1],"trick":"Sapaan inklusif menghormati semua tamu.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), D (2), E (1). Sapaan inklusif menghormati semua tamu."},{"id":"SKD-TKP-0122","sub":"Sosial Budaya","q":"Di kantor Anda, rekan beragama berbeda sedang berpuasa dan beribadah sesuai keyakinannya, sehingga jadwal rapat harus disesuaikan. Sikap Anda adalah...","options":["A. Mengeluh bahwa jadwal menjadi merepotkan, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Meminta rekan itu mengurangi ibadahnya demi rapat","C. Menyesuaikan jadwal hanya jika diminta, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","D. Mendukung penyesuaian jadwal agar semua dapat mengikuti rapat dan menghargai ibadah rekan","E. Tetap menjalankan jadwal rapat tanpa mengubah apa pun, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":3,"scores":[2,1,4,5,3],"trick":"Toleransi diwujudkan dengan penyesuaian yang adil.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), A (2), B (1). Toleransi diwujudkan dengan penyesuaian yang adil."},{"id":"SKD-TKP-0128","sub":"Sosial Budaya","q":"Seorang rekan perempuan diminta mengerjakan tugas lapangan berat dan diragukan sebagian rekan karena gender. Anda mengetahui kemampuannya. Sikap Anda adalah...","options":["A. Menyarankan agar tugas diberikan kepada laki-laki, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Menawarkan bantuan khusus karena ia perempuan, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Meremehkan kemampuannya","D. Menyerahkan keputusan kepada atasan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Menyatakan bahwa penugasan didasarkan pada kompetensi, bukan gender, dan mendukungnya dengan menyediakan sarana yang dibutuhkan"],"ans":4,"scores":[2,4,1,3,5],"trick":"Kompetensi menjadi dasar penugasan, bukan gender.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), D (3), A (2), C (1). Kompetensi menjadi dasar penugasan, bukan gender."},{"id":"SKD-TKP-0134","sub":"Sosial Budaya","q":"Anda mendapat penugasan di daerah perbatasan dengan fasilitas terbatas dan budaya yang jauh berbeda dari kota asal Anda. Sikap Anda adalah...","options":["A. Menerima dengan sikap positif, belajar budaya setempat, beradaptasi dengan keadaan, dan tetap melaksanakan tugas secara profesional","B. Mengajukan kepindahan sebelum masa tugas, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","C. Mengeluh kepada rekan sesama pendatang, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Menjalani tugas sambil menunggu masa penugasan selesai, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Menyalahkan kondisi daerah atas kurangnya hasil"],"ans":0,"scores":[5,2,3,4,1],"trick":"Adaptif dan profesional di mana pun ditempatkan.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), C (3), B (2), E (1). Adaptif dan profesional di mana pun ditempatkan."},{"id":"SKD-TKP-0140","sub":"Sosial Budaya","q":"Seorang siswa magang di kantor Anda mengenakan pakaian khas daerah dan diejek rekan lain sebagai 'kuno'. Tindakan Anda adalah...","options":["A. Meminta siswa magang berpakaian biasa, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Menegur ejekan dengan sopan, memuji pakaian khas sebagai kekayaan budaya, dan mengajak rekan lain mengenali budayanya","C. Membiarkan ejekan terus berlanjut","D. Meminta rekan berhenti mengejek, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Menertawakan bersama"],"ans":1,"scores":[3,5,1,4,2],"trick":"Budaya daerah adalah kekayaan bangsa.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), A (3), E (2), C (1). Budaya daerah adalah kekayaan bangsa."},{"id":"SKD-TKP-0146","sub":"Sosial Budaya","q":"Seorang tetangga Anda meninggal dunia dengan adat yang berbeda dari tradisi Anda. Keluarga mengundang Anda hadir. Sikap Anda adalah...","options":["A. Hadir sebentar lalu pulang","B. Menolak karena adat berbeda","C. Hadir untuk berbelasungkawa, mengikuti tata krama setempat, dan menghormati prosesi adat keluarga","D. Mengirim ucapan duka tanpa hadir","E. Mengkritik adat keluarga tersebut"],"ans":2,"scores":[4,2,5,3,1],"trick":"Hormat kepada tradisi duka warga.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), B (2), E (1). Hormat kepada tradisi duka warga."},{"id":"SKD-TKP-0152","sub":"Sosial Budaya","q":"Rekan Anda menolak mengikuti kegiatan keagamaan bersama yang diadakan kantor karena merasa tidak sesuai keyakinannya, lalu dicemooh oleh rekan lain. Sikap Anda adalah...","options":["A. Meminta rekan tetap hadir sebagai formalitas, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Ikut mencemooh, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","C. Mendiamkan cemoohan itu, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Membela hak rekan untuk tidak ikut, mengingatkan bahwa keyakinan harus dihormati, dan mengusulkan kegiatan yang bersifat umum","E. Melaporkan rekan tersebut sebagai tidak kooperatif"],"ans":3,"scores":[3,2,4,5,1],"trick":"Hak berkeyakinan harus dihormati di tempat kerja.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), A (3), B (2), E (1). Hak berkeyakinan harus dihormati di tempat kerja."},{"id":"SKD-TKP-0158","sub":"Sosial Budaya","q":"Anda baru bertugas di daerah yang memiliki tradisi menyambut tamu dengan makanan dan ritual tertentu yang asing bagi Anda. Sikap Anda adalah...","options":["A. Menolak menghadiri acara penyambutan","B. Hadir tetapi menolak mengikuti seluruhnya, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Mengikuti tradisi tanpa banyak bicara, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Mengejek tradisi tersebut","E. Mengikuti tradisi dengan hormat sesuai batas keyakinan, menjelaskan jika ada keterbatasan secara sopan, dan mengapresiasi budaya setempat"],"ans":4,"scores":[2,3,4,1,5],"trick":"Apresiasi budaya lokal sambil menjaga batas pribadi dengan sopan.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), A (2), D (1). Apresiasi budaya lokal sambil menjaga batas pribadi dengan sopan."},{"id":"SKD-TKP-0164","sub":"Sosial Budaya","q":"Anda bertugas sebagai penyuluh di daerah dengan banyak pengungsi akibat konflik sosial. Sebagian warga setempat menolak kehadiran pengungsi. Sikap Anda adalah...","options":["A. Memfasilitasi dialog antara warga dan pengungsi, mengedukasi nilai kemanusiaan, dan memastikan kebutuhan dasar pengungsi terpenuhi","B. Memindahkan pengungsi tanpa koordinasi","C. Mendukung penolakan warga","D. Meminta aparat mengamankan pengungsi, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menenangkan warga tanpa menyelesaikan masalah, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":0,"scores":[5,2,1,4,3],"trick":"Kemanusiaan dan dialog mengurangi konflik sosial.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), B (2), C (1). Kemanusiaan dan dialog mengurangi konflik sosial."},{"id":"SKD-TKP-0170","sub":"Sosial Budaya","q":"Di komunitas tempat tinggal Anda ada kerja bakti rutin, sementara Anda sering pulang larut karena tugas kantor. Tetangga mulai berprasangka. Sikap Anda adalah...","options":["A. Menyalahkan tetangga yang tidak mengerti","B. Menjelaskan kesibukan dengan baik, menyumbang tenaga atau dana sesuai kemampuan, dan berpartisipasi saat memungkinkan","C. Menyatakan kerja bakti bukan urusan ASN","D. Menitipkan uang tanpa menjelaskan apa pun","E. Mengabaikan prasangka tetangga"],"ans":1,"scores":[1,5,2,4,3],"trick":"Tetap menjaga hubungan sosial walau sibuk.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), E (3), C (2), A (1). Tetap menjaga hubungan sosial walau sibuk."},{"id":"SKD-TKP-0176","sub":"Sosial Budaya","q":"Seorang warga sepuh meminta Anda berbicara dengan bahasa daerah dalam layanan agar lebih nyaman, padahal Anda kurang lancar. Sikap Anda adalah...","options":["A. Menertawakan permintaan warga","B. Menjawab dengan bahasa Indonesia saja, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Berusaha memakai bahasa daerah sederhana, meminta maaf atas keterbatasan, dan mencari rekan yang lebih fasih bila diperlukan","D. Menolak permintaan tersebut, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","E. Meminta warga memakai bahasa Indonesia, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":2,"scores":[1,4,5,2,3],"trick":"Penghormatan terhadap bahasa daerah menumbuhkan kepercayaan.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Penghormatan terhadap bahasa daerah menumbuhkan kepercayaan."},{"id":"SKD-TKP-0182","sub":"Sosial Budaya","q":"Anda melihat spanduk acara komunitas di dekat kantor memuat ajakan yang diskriminatif terhadap kelompok tertentu. Tindakan Anda adalah...","options":["A. Merobek spanduk sendiri, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","B. Mendiamkan karena bukan urusan instansi, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Memotret spanduk dan menyimpannya, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Melaporkan kepada pihak berwenang atau atasan, meminta klarifikasi penyelenggara, dan menjelaskan pentingnya menjaga persatuan","E. Membagikan foto spanduk di media sosial dengan komentar kasar"],"ans":3,"scores":[2,3,4,5,1],"trick":"Tanggapi diskriminasi lewat jalur yang tepat.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), B (3), A (2), E (1). Tanggapi diskriminasi lewat jalur yang tepat."},{"id":"SKD-TKP-0188","sub":"Sosial Budaya","q":"Anda mengetahui ada warga yang tidak memiliki identitas kependudukan karena menikah secara adat dan sulit mengakses layanan. Tindakan Anda adalah...","options":["A. Menyarankan menikah ulang secara hukum, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Menganggap pernikahan adat tidak sah","C. Menolak melayani karena tidak ada dokumen, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menyuruh warga mengurus sendiri, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Mendata, menjelaskan prosedur pencatatan sipil atau layanan khusus, dan membantu mengurusnya secara bertahap dengan menghormati adat"],"ans":4,"scores":[3,1,2,4,5],"trick":"Layani warga adat dengan pendekatan yang menghormati tradisi.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), A (3), C (2), B (1). Layani warga adat dengan pendekatan yang menghormati tradisi."},{"id":"SKD-TKP-0194","sub":"Sosial Budaya","q":"Seorang rekan membuat lelucon bernuansa suku di ruang makan kantor. Beberapa rekan tampak tersinggung. Tindakan Anda adalah...","options":["A. Menegur dengan sopan di tempat yang tepat, menjelaskan lelucon itu menyinggung, dan mengajak menjaga keakraban tanpa merendahkan suku tertentu","B. Menertawakan korban lelucon","C. Tertawa agar tidak canggung","D. Mengalihkan pembicaraan ke topik lain","E. Membalas dengan lelucon tentang suku rekan itu"],"ans":0,"scores":[5,1,3,4,2],"trick":"Tegur ujaran yang merendahkan dengan cara santun.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), C (3), E (2), B (1). Tegur ujaran yang merendahkan dengan cara santun."},{"id":"SKD-TKP-0200","sub":"Sosial Budaya","q":"Dalam perayaan hari kemerdekaan di kantor, terdapat rekan yang tidak mau ikut lomba karena alasan keyakinan. Sikap Anda adalah...","options":["A. Menyebarkan isu bahwa rekan tidak cinta tanah air","B. Menghormati keputusan rekan, mencari peran lain yang tetap mendukung kegiatan, dan menjaga suasana tetap guyub","C. Menegur karena dianggap tidak nasionalis","D. Menghormati keputusan rekan untuk tidak ikut tanpa menawarkan peran lain","E. Menyindir rekan di depan banyak orang"],"ans":1,"scores":[1,5,3,4,2],"trick":"Nasionalisme dan toleransi berjalan beriringan.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), E (2), A (1). Nasionalisme dan toleransi berjalan beriringan."},{"id":"SKD-TKP-0206","sub":"Sosial Budaya","q":"Anda melihat sekelompok remaja menggunakan alat musik tradisional daerah dengan cara tidak semestinya sebagai olok-olok. Sikap Anda adalah...","options":["A. Menegur singkat lalu pergi, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Merekam dan mengolok mereka","C. Menegur dengan ramah, menjelaskan nilai alat tersebut, dan mengajak mereka belajar memainkannya dengan benar","D. Mengabaikan karena hanya remaja, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Ikut bercanda"],"ans":2,"scores":[4,2,5,3,1],"trick":"Edukasi budaya dengan pendekatan ramah.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), B (2), E (1). Edukasi budaya dengan pendekatan ramah."},{"id":"SKD-TKP-0212","sub":"Sosial Budaya","q":"Di lingkungan kerja ada rekan penyandang disabilitas fisik yang memerlukan penyesuaian ruang kerja. Sebagian rekan menganggap itu berlebihan. Sikap Anda adalah...","options":["A. Mengatakan sebaiknya ia dipindah ke unit lain, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","B. Mendukung penyesuaian jika tidak mengganggu pekerjaan lain, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Tidak ikut campur, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Mendukung penyesuaian sebagai hak kesetaraan, mengajak rekan memahami manfaatnya, dan membantu mengusulkan kepada pimpinan","E. Menertawakan keterbatasannya"],"ans":3,"scores":[2,4,3,5,1],"trick":"Inklusivitas adalah hak, bukan beban.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), A (2), E (1). Inklusivitas adalah hak, bukan beban."},{"id":"SKD-TKP-0218","sub":"Sosial Budaya","q":"Di tengah masyarakat yang masih menganggap tabu pembicaraan kesehatan reproduksi, Anda ditugaskan menjadi penyuluh. Sikap Anda adalah...","options":["A. Menyampaikan materi apa adanya","B. Menghindari topik yang sensitif","C. Meminta penyuluh lain menggantikan","D. Menertawakan pandangan warga","E. Menggunakan pendekatan santun dan edukatif, melibatkan tokoh agama dan masyarakat, serta menyesuaikan bahasa dengan nilai setempat"],"ans":4,"scores":[4,3,2,1,5],"trick":"Edukasi sensitif memerlukan pendekatan budaya yang tepat.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), B (3), C (2), D (1). Edukasi sensitif memerlukan pendekatan budaya yang tepat."},{"id":"SKD-TKP-0224","sub":"Sosial Budaya","q":"Anda melihat seorang rekan menolak bekerja sama dengan rekan lain karena latar belakang etnisnya. Sebagai ketua tim, tindakan Anda adalah...","options":["A. Menegur secara pribadi, menjelaskan nilai kesetaraan dan aturan ASN, serta menjalankan pembinaan jika sikap itu berlanjut","B. Membiarkan agar tidak ada konflik","C. Mengingatkan secara umum pada rapat, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Mendukung pandangan rekan tersebut","E. Memindahkan salah satu anggota ke tim lain, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun"],"ans":0,"scores":[5,2,3,1,4],"trick":"Diskriminasi tidak ditoleransi.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), B (2), D (1). Diskriminasi tidak ditoleransi."},{"id":"SKD-TKP-0230","sub":"Sosial Budaya","q":"Pemerintah daerah mengadakan festival budaya, dan Anda mengetahui sebagian warga menolak karena menganggap bertentangan dengan keyakinan mereka. Sikap Anda adalah...","options":["A. Menyampaikan keberatan warga kepada panitia saja","B. Memfasilitasi dialog dengan panitia dan tokoh agama, mencari bentuk acara yang menghormati nilai-nilai bersama","C. Menghina warga yang menolak","D. Mendukung festival tanpa memperhatikan keberatan","E. Menolak ikut festival"],"ans":1,"scores":[4,5,1,3,2],"trick":"Dialog mencegah polarisasi dalam kegiatan budaya.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), E (2), C (1). Dialog mencegah polarisasi dalam kegiatan budaya."},{"id":"SKD-TKP-0236","sub":"Sosial Budaya","q":"Dalam kegiatan gotong royong membersihkan sungai, Anda diajak warga bergabung padahal pakaian Anda tidak sesuai. Sikap Anda adalah...","options":["A. Membantu mengawasi saja, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menolak karena pakaian tidak sesuai, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Bergabung dengan antusias sesuai kemampuan, meminjam peralatan seadanya, dan membantu memberi semangat warga","D. Meninggalkan kegiatan","E. Menyumbang makanan tanpa ikut bekerja, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":2,"scores":[4,2,5,1,3],"trick":"Ikut serta dalam kegiatan sosial membangun kedekatan.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), B (2), D (1). Ikut serta dalam kegiatan sosial membangun kedekatan."},{"id":"SKD-TKP-0242","sub":"Sosial Budaya","q":"Anda mendapati rekan muslim menyendiri untuk salat saat jam kerja dan rekan lain mengeluh karena merasa pekerjaannya terbengkalai. Sikap Anda adalah...","options":["A. Menyetujui keluhan rekan","B. Mendengarkan keluhan rekan tanpa memberi penjelasan lebih lanjut, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Meminta rekan beribadah di luar jam kerja, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menjelaskan bahwa ibadah adalah hak yang dilindungi, membantu mengatur pembagian tugas agar tidak terganggu, dan mengajak rekan saling memahami","E. Melarang ibadah di jam kerja"],"ans":3,"scores":[2,4,3,5,1],"trick":"Hak beribadah dihormati dengan pengaturan kerja yang bijak.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), A (2), E (1). Hak beribadah dihormati dengan pengaturan kerja yang bijak."},{"id":"SKD-TKP-0248","sub":"Sosial Budaya","q":"Seorang anak jalanan datang ke kantor pelayanan untuk meminta air minum. Satpam hendak mengusirnya. Tindakan Anda adalah...","options":["A. Mengusirnya agar tidak mengganggu pelayanan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menuduhnya mencuri","C. Meminta satpam mengantarnya keluar baik-baik, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Memberi air lalu mempersilakannya pergi, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Memberinya air minum dengan ramah, bertanya kondisinya, dan menghubungkannya dengan dinas sosial untuk pendampingan lanjut"],"ans":4,"scores":[2,1,3,4,5],"trick":"Empati sosial dan koneksi ke layanan perlindungan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), A (2), B (1). Empati sosial dan koneksi ke layanan perlindungan."},{"id":"SKD-TKP-0254","sub":"Sosial Budaya","q":"Anda diminta membuat konten edukasi di media sosial tentang keberagaman dan menemukan bahwa banyak warganet menanggapi dengan ujaran kebencian. Tindakan Anda adalah...","options":["A. Memoderasi komentar sesuai kebijakan, menjawab dengan fakta santun, serta melaporkan akun yang menyebarkan ujaran kebencian","B. Membalas dengan emosi","C. Mematikan kolom komentar","D. Menghapus konten","E. Ikut berdebat sengit di kolom komentar"],"ans":0,"scores":[5,3,4,2,1],"trick":"Kelola ruang digital agar tetap sehat dan inklusif.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), D (2), E (1). Kelola ruang digital agar tetap sehat dan inklusif."},{"id":"SKD-TKP-0260","sub":"Sosial Budaya","q":"Anda mendapati anak-anak dari keluarga pendatang sering diejek teman sekolah di lingkungan tempat Anda bertugas. Tindakan Anda adalah...","options":["A. Membiarkan karena dianggap candaan anak-anak, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Berkoordinasi dengan sekolah dan tokoh masyarakat, mengadakan kegiatan bersama, dan mengedukasi pentingnya saling menghargai","C. Meminta orang tua anak pendatang menangani, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Ikut tertawa agar akrab dengan warga","E. Menegur anak-anak yang mengejek, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":1,"scores":[2,5,3,1,4],"trick":"Cegah perundungan lewat edukasi dan kegiatan bersama.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), C (3), A (2), D (1). Cegah perundungan lewat edukasi dan kegiatan bersama."},{"id":"SKD-TKP-0266","sub":"Sosial Budaya","q":"Dalam kegiatan kantor, rekan yang berpuasa tampak lemas dan sebagian rekan mengejeknya. Sikap Anda adalah...","options":["A. Mengabaikan ejekan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Ikut bercanda agar akrab, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Menegur ejekan secara santun, menawarkan bantuan meringankan tugas, dan mendukung rekan menjalankan ibadahnya","D. Meminta rekan beristirahat, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Meminta rekan membatalkan puasa"],"ans":2,"scores":[3,2,5,4,1],"trick":"Dukung ibadah rekan dan cegah ejekan.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), B (2), E (1). Dukung ibadah rekan dan cegah ejekan."},{"id":"SKD-TKP-0272","sub":"Sosial Budaya","q":"Dalam kegiatan survei di desa, ada warga yang menolak menjawab karena curiga pada petugas dari luar daerah. Sikap Anda adalah...","options":["A. Memaksa warga mengisi","B. Melewati rumah tersebut","C. Mencatat jawaban sendiri tanpa persetujuan","D. Menjelaskan tujuan survei dengan ramah, menggandeng tokoh setempat, dan menghormati keputusan warga","E. Meminta warga tetap menjawab karena penting"],"ans":3,"scores":[2,3,1,5,4],"trick":"Bangun kepercayaan melalui pendekatan budaya.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), A (2), C (1). Bangun kepercayaan melalui pendekatan budaya."},{"id":"SKD-TKP-0278","sub":"Sosial Budaya","q":"Rekan kerja Anda yang baru pulang dari ibadah haji atau perayaan keagamaan lain membawa oleh-oleh khusus dan mengajak berbagi cerita. Sebagian rekan tidak tertarik. Sikap Anda adalah...","options":["A. Mengejek cerita rekan","B. Menolak oleh-oleh dengan sopan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Meminta rekan lain ikut mendengarkan","D. Menerima oleh-oleh lalu pergi, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Mendengarkan dengan hormat, berbagi suasana kebersamaan, dan menghargai bahwa tidak semua rekan memiliki minat yang sama"],"ans":4,"scores":[1,3,2,4,5],"trick":"Saling menghargai pengalaman spiritual.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Saling menghargai pengalaman spiritual."},{"id":"SKD-TKP-0284","sub":"Sosial Budaya","q":"Di daerah penugasan, ada tradisi musyawarah yang memerlukan waktu panjang sebelum keputusan program disepakati, sementara Anda dikejar target. Sikap Anda adalah...","options":["A. Menghargai proses musyawarah, menjelaskan target secara terbuka, dan membantu menemukan titik temu yang tetap mengejar target","B. Menganggap musyawarah menghambat kerja","C. Mempercepat keputusan dengan cara Anda","D. Melaporkan keterlambatan kepada atasan","E. Mengambil keputusan tanpa musyawarah"],"ans":0,"scores":[5,1,4,3,2],"trick":"Menghargai musyawarah tanpa melupakan target.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Menghargai musyawarah tanpa melupakan target."},{"id":"SKD-TKP-0290","sub":"Sosial Budaya","q":"Kantor Anda mendapat kunjungan warga negara asing yang tidak bisa berbahasa Indonesia dengan lancar. Tidak ada penerjemah. Tindakan Anda adalah...","options":["A. Mengabaikan karena kendala bahasa","B. Berkomunikasi dengan bahasa sederhana atau alat penerjemah, bersikap ramah, dan meminta bantuan rekan yang menguasai bahasa tersebut","C. Menertawakan kesulitannya berbicara","D. Memberikan brosur layanan lalu menunggu, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Menyuruhnya kembali bersama penerjemah, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":1,"scores":[2,5,1,3,4],"trick":"Ramah dan berupaya mengatasi hambatan bahasa.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), A (2), C (1). Ramah dan berupaya mengatasi hambatan bahasa."},{"id":"SKD-TKP-0296","sub":"Sosial Budaya","q":"Seorang lansia di lingkungan Anda merasa kesepian dan jarang dikunjungi. Anda mengetahui kondisinya saat bertugas di kelurahan. Tindakan Anda adalah...","options":["A. Menyampaikan hal itu kepada atasan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","B. Memberi tahu keluarganya agar sering berkunjung, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","C. Mengunjungi, berkoordinasi dengan kader lansia dan tokoh setempat, serta menghubungkannya dengan program layanan sosial yang tersedia","D. Menganggap itu urusan keluarga, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","E. Mengabaikan keadaannya"],"ans":2,"scores":[3,4,5,2,1],"trick":"Peduli sosial dengan jejaring layanan.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), D (2), E (1). Peduli sosial dengan jejaring layanan."},{"id":"SKD-TKP-0302","sub":"Sosial Budaya","q":"Dalam kegiatan bersih desa, sebagian warga meminta pegawai kantor ikut menyumbang sapi untuk acara adat. Anda diminta menyampaikan sumbangan secara pribadi. Sikap Anda adalah...","options":["A. Meminjam uang agar bisa menyumbang besar, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","B. Menolak sumbangan sepenuhnya, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Meminta uang kantor untuk menyumbang","D. Berpartisipasi sesuai kemampuan secara wajar, menolak tekanan sumbangan berlebihan, dan menjelaskan baik-baik batas Anda","E. Menyumbang seadanya tanpa penjelasan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":3,"scores":[2,3,1,5,4],"trick":"Partisipasi sosial wajar tanpa melanggar etika.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), A (2), C (1). Partisipasi sosial wajar tanpa melanggar etika."},{"id":"SKD-TKP-0308","sub":"Sosial Budaya","q":"Seorang rekan Anda mengungkapkan pandangan politiknya secara agresif di ruang kerja dan membuat rekan lain tidak nyaman. Tindakan Anda adalah...","options":["A. Meminta rekan lain menegur","B. Membuat grup untuk membahas politik di jam kerja","C. Menghindari percakapan dengannya","D. Membalas dengan pandangan politik sendiri","E. Menegur dengan sopan bahwa ruang kerja harus netral, mengingatkan aturan netralitas ASN, dan mengalihkan pembicaraan ke tugas"],"ans":4,"scores":[2,1,4,3,5],"trick":"ASN menjaga netralitas di tempat kerja.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), A (2), B (1). ASN menjaga netralitas di tempat kerja."},{"id":"SKD-TKP-0314","sub":"Sosial Budaya","q":"Seorang rekan baru berasal dari daerah dengan logat bicara khas, dan beberapa rekan sering menirukannya sebagai candaan. Anda melihatnya. Sikap Anda adalah...","options":["A. Mengingatkan rekan agar tidak menirukan karena bisa menyinggung, dan menyambut rekan baru dengan hangat","B. Ikut menirukan agar akrab","C. Diam karena itu hanya candaan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menertawakan rekan baru","E. Memberi isyarat agar mereka berhenti, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun"],"ans":0,"scores":[5,2,3,1,4],"trick":"Hargai keberagaman bahasa dan logat.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), B (2), D (1). Hargai keberagaman bahasa dan logat."},{"id":"SKD-TKP-0320","sub":"Sosial Budaya","q":"Anda mengetahui ada warga kurang mampu yang sungkan datang ke acara desa karena merasa tidak punya pakaian layak. Anda panitia acara. Tindakan Anda adalah...","options":["A. Menyarankan tidak datang bila tidak siap","B. Menyampaikan bahwa acara terbuka bagi semua tanpa syarat pakaian dan mengundang warga tersebut secara personal dengan ramah","C. Mengumumkan bahwa pakaian bebas, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menunggu warga tersebut datang sendiri, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menjadikan pakaian rapi sebagai syarat masuk"],"ans":1,"scores":[2,5,4,3,1],"trick":"Inklusi sosial tanpa memandang kemampuan ekonomi.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Inklusi sosial tanpa memandang kemampuan ekonomi."},{"id":"SKD-TKP-0326","sub":"Sosial Budaya","q":"Anda mengajar pelatihan kepada peserta dewasa di desa yang sebagian besar belum lancar membaca. Materi Anda berbasis teks. Tindakan Anda adalah...","options":["A. Melanjutkan materi seperti biasa, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Meminta peserta yang bisa membaca membantu yang lain, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Mengubah metode menjadi lisan, gambar, dan praktik langsung agar mudah dipahami semua peserta","D. Membatalkan pelatihan","E. Membaca materi keras-keras, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":2,"scores":[2,3,5,1,4],"trick":"Sesuaikan metode dengan karakter peserta.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), B (3), A (2), D (1). Sesuaikan metode dengan karakter peserta."},{"id":"SKD-TKP-0332","sub":"Sosial Budaya","q":"Seorang teman lama mengajak Anda menghadiri acara komunitas berbasis ideologi tertentu dan meminta Anda ikut menyumbang. Anda belum mengenal acaranya. Sikap Anda adalah...","options":["A. Menolak karena tidak punya waktu, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Menyumbang tanpa mencari tahu","C. Hadir karena sungkan kepada teman, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Mencari tahu tujuan dan latar belakang acara terlebih dahulu, menghormati teman, dan menolak jika bertentangan dengan Pancasila atau netralitas ASN","E. Menyebarkan undangan ke rekan kantor"],"ans":3,"scores":[4,2,3,5,1],"trick":"Cari tahu dulu sebelum terlibat; jaga netralitas dan nilai kebangsaan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), C (3), B (2), E (1). Cari tahu dulu sebelum terlibat; jaga netralitas dan nilai kebangsaan."},{"id":"SKD-TKP-0338","sub":"Sosial Budaya","q":"Dalam pertemuan warga, seorang tokoh adat meminta acara dimulai dengan ritual doa menurut tradisinya, sementara beberapa peserta berbeda keyakinan. Anda moderator. Tindakan Anda adalah...","options":["A. Menyindir tradisi tersebut","B. Menyingkat acara pembuka agar tidak menimbulkan masalah, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menjalankan ritual tanpa membahas keberatan peserta, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Melarang ritual karena beragam peserta","E. Menghargai tradisi dengan membuka acara secara hormat, memberi kesempatan peserta berdoa menurut keyakinannya masing-masing, dan menjaga suasana inklusif"],"ans":4,"scores":[1,3,4,2,5],"trick":"Pembukaan acara menghormati tradisi dan keragaman peserta.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), D (2), A (1). Pembukaan acara menghormati tradisi dan keragaman peserta."},{"id":"SKD-TKP-0344","sub":"Sosial Budaya","q":"Anda diminta menyusun materi sosialisasi program untuk masyarakat pesisir yang punya kebiasaan melaut berdasarkan kepercayaan tertentu. Sikap Anda adalah...","options":["A. Mempelajari kebiasaan dan bahasa mereka, memasukkan unsur lokal dalam materi, dan menguji pemahaman materi bersama tokoh nelayan","B. Menyusun materi dalam bahasa formal agar terlihat profesional, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Menyampaikan materi tanpa menyesuaikan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menganggap kebiasaan mereka tidak ilmiah","E. Menggunakan materi standar dari pusat, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":0,"scores":[5,3,2,1,4],"trick":"Pesan efektif jika sesuai konteks budaya.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), C (2), D (1). Pesan efektif jika sesuai konteks budaya."},{"id":"SKD-TKP-0350","sub":"Sosial Budaya","q":"Anda menemukan bahwa bahan penyuluhan instansi menggunakan istilah yang dianggap merendahkan kelompok masyarakat tertentu. Tindakan Anda adalah...","options":["A. Mengabaikan karena bukan masalah besar, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menyampaikan temuan kepada atasan, mengusulkan revisi bahan dengan bahasa yang inklusif, dan menarik bahan tersebut dari peredaran sementara","C. Tetap menggunakan bahan karena sudah disetujui, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Menyebarkan bahan tanpa revisi","E. Mengganti istilah di bahan Anda sendiri, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":1,"scores":[2,5,4,1,3],"trick":"Bahasa publik harus inklusif dan tidak merendahkan.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), E (3), A (2), D (1). Bahasa publik harus inklusif dan tidak merendahkan."},{"id":"SKD-TKP-0356","sub":"Sosial Budaya","q":"Anda menjadi panitia peringatan hari besar keagamaan di kantor, dan sebagian rekan merasa kegiatan hanya melayani satu kelompok. Tindakan Anda adalah...","options":["A. Menjelaskan bahwa kegiatan ini sudah menjadi tradisi, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Membatalkan kegiatan agar tidak ada yang tersinggung, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Mengajak perwakilan seluruh kelompok menyusun kegiatan yang saling menghargai dan memastikan hari besar lain juga mendapat perhatian","D. Mengabaikan keluhan rekan","E. Menyerahkan kegiatan kepada kelompok mayoritas, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":2,"scores":[4,3,5,1,2],"trick":"Kegiatan kantor harus inklusif bagi semua.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), E (2), D (1). Kegiatan kantor harus inklusif bagi semua."},{"id":"SKD-TKP-0045","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Server aplikasi layanan publik instansi Anda tiba-tiba lambat saat jam sibuk. Anda bertugas di tim TI. Tindakan Anda adalah...","options":["A. Memeriksa penyebab dengan log dan monitoring, mengurangi beban sementara, menginformasikan pengguna, dan menyusun perbaikan permanen","B. Menyalahkan pengguna karena terlalu banyak akses","C. Mematikan aplikasi sampai selesai jam sibuk","D. Memulai ulang server tanpa menganalisis, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Menunggu laporan pengguna, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":0,"scores":[5,1,2,4,3],"trick":"Tangani gangguan secara sistematis dan komunikatif.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), C (2), B (1). Tangani gangguan secara sistematis dan komunikatif."},{"id":"SKD-TKP-0051","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Dalam rapat daring, rekan Anda menyalakan kamera dan tampak sedang melakukan hal lain yang mengganggu. Anda adalah moderator. Tindakan Anda adalah...","options":["A. Mengabaikan karena rapat tetap berjalan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Mengingatkan etika rapat daring secara umum dan sopan, lalu menyapa langsung rekan tersebut bila perlu","C. Mengirim pesan pribadi menegur rekan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","D. Menegur keras di depan peserta","E. Mengeluarkan rekan dari rapat tanpa penjelasan"],"ans":1,"scores":[3,5,4,2,1],"trick":"Etika rapat daring dijaga dengan teguran santun.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), A (3), D (2), E (1). Etika rapat daring dijaga dengan teguran santun."},{"id":"SKD-TKP-0057","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mendapat pesan dari nomor tak dikenal yang mengaku petugas bank dan meminta kode OTP Anda. Tindakan Anda adalah...","options":["A. Tidak membalas pesan tersebut, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Memberikan kode jika pesan tampak meyakinkan, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","C. Tidak memberikan kode, memblokir nomor, memeriksa ke bank melalui kanal resmi, dan membagikan informasi ancaman penipuan kepada rekan","D. Membalas untuk mencari tahu maksudnya, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Memberikan kode agar rekening aman"],"ans":2,"scores":[4,2,5,3,1],"trick":"Kode OTP tidak boleh dibagikan kepada siapa pun.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), B (2), E (1). Kode OTP tidak boleh dibagikan kepada siapa pun."},{"id":"SKD-TKP-0063","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menemukan rekan memakai satu kata sandi yang sama untuk semua aplikasi kantor dan menyimpannya di catatan terbuka. Sikap Anda adalah...","options":["A. Meminta rekan mengubah kata sandi","B. Memakai kata sandi rekan untuk keperluan kerja","C. Membiarkan karena hak pribadi","D. Menjelaskan risikonya, mengajarkan penggunaan pengelola kata sandi atau kata sandi unik, dan mengingatkan aturan keamanan instansi","E. Menyebarkan catatan kata sandi"],"ans":3,"scores":[4,2,3,5,1],"trick":"Edukasi praktik keamanan dasar.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), C (3), B (2), E (1). Edukasi praktik keamanan dasar."},{"id":"SKD-TKP-0069","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Laptop kantor Anda hilang di perjalanan dinas dan berisi data kerja. Tindakan Anda adalah...","options":["A. Mengganti laptop dengan perangkat pribadi tanpa melapor","B. Melapor ke atasan setelah kembali ke kantor","C. Menutupi kehilangan dan meminjam laptop rekan","D. Mencari laptop dulu selama beberapa hari","E. Segera melapor kepada atasan dan unit TI, meminta penguncian jarak jauh dan penggantian kata sandi, serta melapor ke pihak berwenang bila perlu"],"ans":4,"scores":[1,3,2,4,5],"trick":"Kehilangan perangkat segera dilaporkan agar risiko ditekan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Kehilangan perangkat segera dilaporkan agar risiko ditekan."},{"id":"SKD-TKP-0075","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menerima pesan WhatsApp berisi berita tentang kebijakan instansi yang belum Anda ketahui kebenarannya dan banyak dibagikan. Sikap Anda adalah...","options":["A. Memeriksa kebenaran pada sumber resmi, tidak meneruskan sebelum terverifikasi, dan mengedukasi rekan jika berita itu keliru","B. Tidak meneruskan pesan tanpa memeriksa, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Meneruskan karena banyak orang membagikannya, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menambah informasi karangan agar menarik","E. Meneruskan pesan dengan tambahan 'belum tentu benar', sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":0,"scores":[5,4,2,1,3],"trick":"Saring sebelum sharing; verifikasi pada sumber resmi.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), E (3), C (2), D (1). Saring sebelum sharing; verifikasi pada sumber resmi."},{"id":"SKD-TKP-0081","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Rekan Anda sering menyimpan dokumen kerja di akun penyimpanan awan pribadi karena lebih praktis. Sikap Anda adalah...","options":["A. Mengingatkan agar menghapus dokumen sensitif, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menjelaskan risiko keamanan, mengarahkan memakai penyimpanan resmi instansi, dan mengajukan kebutuhan kapasitas jika kurang","C. Membiarkan selama tidak ada masalah, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Membagikan akses akun itu kepada banyak orang","E. Ikut menyimpan dokumen di akun pribadi"],"ans":1,"scores":[4,5,3,1,2],"trick":"Gunakan sarana resmi untuk data kantor.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), E (2), D (1). Gunakan sarana resmi untuk data kantor."},{"id":"SKD-TKP-0087","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Atasan meminta Anda memakai aplikasi kecerdasan buatan untuk meringkas dokumen internal yang bersifat rahasia. Sikap Anda adalah...","options":["A. Mengerjakan peringkasan secara manual tanpa memberi tahu atasan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Mengunggah dokumen ke beberapa layanan untuk perbandingan","C. Memeriksa kebijakan penggunaan AI di instansi, tidak mengunggah dokumen rahasia ke layanan publik, dan mengusulkan alternatif yang aman","D. Mengunggah dokumen karena perintah atasan","E. Mengunggah sebagian dokumen saja, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":2,"scores":[3,1,5,2,4],"trick":"Gunakan teknologi baru dengan menjaga kerahasiaan data.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), A (3), D (2), B (1). Gunakan teknologi baru dengan menjaga kerahasiaan data."},{"id":"SKD-TKP-0093","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda ditunjuk sebagai admin akun media sosial resmi instansi dan tidak sengaja mengunggah konten dengan informasi keliru. Tindakan Anda adalah...","options":["A. Menghapus unggahan tanpa penjelasan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","B. Membiarkan unggahan agar tidak menimbulkan perhatian","C. Menunggu ada yang menegur, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Segera menghapus atau memperbaiki unggahan, mengunggah klarifikasi, melapor kepada atasan, dan menyusun langkah pencegahan","E. Menyalahkan sumber informasi"],"ans":3,"scores":[4,2,3,5,1],"trick":"Akui kesalahan, perbaiki cepat, dan transparan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), C (3), B (2), E (1). Akui kesalahan, perbaiki cepat, dan transparan."},{"id":"SKD-TKP-0099","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta memigrasi arsip kertas menjadi digital, tetapi sebagian dokumen rusak dan sulit dibaca. Tindakan Anda adalah...","options":["A. Mengisi bagian yang tidak terbaca berdasarkan perkiraan","B. Melewati dokumen rusak, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Membuang dokumen rusak","D. Memindai seluruh dokumen sebisanya, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Memisahkan dokumen rusak, mencoba restorasi dengan prosedur yang benar, mencatat dokumen yang tidak terbaca, dan melaporkan kepada atasan"],"ans":4,"scores":[1,3,2,4,5],"trick":"Arsip digital harus akurat dan terdokumentasi.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Arsip digital harus akurat dan terdokumentasi."},{"id":"SKD-TKP-0105","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda ditugaskan membuat infografis tentang kebijakan baru. Data yang diberikan atasan tampak berbeda dari data di sistem resmi. Tindakan Anda adalah...","options":["A. Menanyakan perbedaan tersebut kepada atasan dengan bukti, memverifikasi sumber, lalu menggunakan data yang valid","B. Menggunakan data dari atasan karena beliau penanggung jawab, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Mengubah data agar sama","D. Menyajikan kedua data tanpa penjelasan, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","E. Menggunakan data sistem resmi tanpa memberi tahu, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":0,"scores":[5,4,1,2,3],"trick":"Verifikasi data sebelum dipublikasikan.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), E (3), D (2), C (1). Verifikasi data sebelum dipublikasikan."},{"id":"SKD-TKP-0111","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Instansi Anda hendak merekam rapat dengan alat perekam daring, tetapi sebagian peserta keberatan karena privasi. Sikap Anda adalah...","options":["A. Merekam dan membagikan ke publik","B. Menjelaskan tujuan perekaman, meminta persetujuan, menjelaskan penyimpanan yang aman, dan menyediakan alternatif risalah tertulis bagi yang keberatan","C. Merekam hanya bagian penting, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Merekam tanpa memberi tahu, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menghentikan perekaman tanpa alternatif"],"ans":1,"scores":[1,5,4,3,2],"trick":"Perekaman harus persetujuan dan menjaga privasi.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), E (2), A (1). Perekaman harus persetujuan dan menjaga privasi."},{"id":"SKD-TKP-0117","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Seorang pengguna layanan mengeluh data pribadi yang ia berikan digunakan untuk iklan pihak ketiga. Anda mengetahui ada kebocoran. Sikap Anda adalah...","options":["A. Meminta maaf kepada pengguna tersebut, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Menyangkal bahwa ada kebocoran","C. Menghentikan penyebaran data, menelusuri sumber kebocoran, melapor kepada pimpinan dan pihak berwenang, serta memberi tahu pengguna terdampak","D. Menunda pengumuman kebocoran sampai penyelidikan internal selesai, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Menunggu penyelidikan pihak lain"],"ans":2,"scores":[4,1,5,3,2],"trick":"Transparansi dan tindakan cepat pada insiden data.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), E (2), B (1). Transparansi dan tindakan cepat pada insiden data."},{"id":"SKD-TKP-0123","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta bekerja dari rumah dan harus mengakses data kantor melalui jaringan Wi-Fi umum di kafe. Sikap Anda adalah...","options":["A. Menunda pekerjaan sampai di rumah","B. Menyimpan data kantor di flashdisk umum","C. Menggunakan Wi-Fi kafe dengan sandi yang tersedia","D. Menggunakan koneksi aman seperti VPN atau data seluler pribadi, memastikan perangkat terlindungi, dan menghindari mengakses data sensitif di jaringan publik","E. Mengakses data kantor di Wi-Fi umum tanpa pengamanan"],"ans":3,"scores":[3,1,4,5,2],"trick":"Lindungi data lewat koneksi yang aman.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), A (3), E (2), B (1). Lindungi data lewat koneksi yang aman."},{"id":"SKD-TKP-0129","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Aplikasi layanan baru instansi Anda mengharuskan warga mengunggah foto KTP, dan Anda merasa penyimpanan datanya kurang aman. Sikap Anda adalah...","options":["A. Meluncurkan aplikasi dan memperbaikinya nanti","B. Menyembunyikan kelemahan agar peluncuran tetap tepat waktu","C. Meminta tim TI memeriksa saat ada waktu, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menyampaikan kekhawatiran kepada rekan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Mengidentifikasi risiko, mengusulkan enkripsi dan pembatasan akses data kepada atasan dan tim TI, serta menunda peluncuran hingga aman"],"ans":4,"scores":[2,1,4,3,5],"trick":"Keamanan data warga prioritas sebelum peluncuran.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), A (2), B (1). Keamanan data warga prioritas sebelum peluncuran."},{"id":"SKD-TKP-0135","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mengetahui rekan memakai aplikasi pesan pribadi untuk mengirim data penduduk karena merasa lebih cepat. Tindakan Anda adalah...","options":["A. Mengingatkan rekan akan risiko, mengarahkan memakai kanal resmi yang aman, dan melaporkan ke atasan bila tetap dilakukan","B. Mengingatkan rekan sekali saja","C. Ikut mengirim data lewat aplikasi pesan","D. Membiarkan agar pekerjaan cepat selesai","E. Menyimpan data kiriman rekan untuk keperluan pribadi"],"ans":0,"scores":[5,4,2,3,1],"trick":"Data penduduk hanya melalui sistem yang aman.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), C (2), E (1). Data penduduk hanya melalui sistem yang aman."},{"id":"SKD-TKP-0141","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Tim Anda memakai grup percakapan untuk koordinasi kerja, tetapi banyak pesan penting tenggelam di antara obrolan lain. Sikap Anda adalah...","options":["A. Menyampaikan ulang informasi penting secara pribadi, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Mengusulkan aturan penggunaan grup, membuat kanal khusus untuk informasi penting, dan memakai penanda atau rangkuman rutin","C. Meminta rekan membaca pesan lebih teliti, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Menonaktifkan grup","E. Menyalahkan rekan yang melewatkan informasi"],"ans":1,"scores":[4,5,3,2,1],"trick":"Perbaiki tata kelola komunikasi digital tim.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), D (2), E (1). Perbaiki tata kelola komunikasi digital tim."},{"id":"SKD-TKP-0147","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mengetahui akun resmi instansi tidak diamankan dengan verifikasi dua langkah. Tindakan Anda adalah...","options":["A. Mengabaikan karena belum ada masalah, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menunggu kejadian peretasan terjadi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Mengusulkan penerapan verifikasi dua langkah kepada pengelola dan atasan, serta membantu menyiapkan panduan pengaktifannya","D. Memberi tahu pengelola secara lisan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Meminta kata sandi akun untuk dicek sendiri"],"ans":2,"scores":[2,3,5,4,1],"trick":"Terapkan prinsip keamanan berlapis.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), A (2), E (1). Terapkan prinsip keamanan berlapis."},{"id":"SKD-TKP-0153","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda baru mengetahui bahwa foto-foto kegiatan instansi diunggah di galeri publik dan menampilkan wajah anak-anak tanpa izin orang tua. Tindakan Anda adalah...","options":["A. Membiarkan karena kegiatan bersifat positif","B. Menunggu orang tua mengeluh, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Mengaburkan wajah anak-anak pada foto, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Segera menurunkan foto yang menampilkan anak, meminta maaf kepada pihak terkait, dan menetapkan aturan izin sebelum publikasi","E. Menambah foto anak-anak untuk publikasi"],"ans":3,"scores":[2,3,4,5,1],"trick":"Perlindungan privasi anak adalah prioritas.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), B (3), A (2), E (1). Perlindungan privasi anak adalah prioritas."},{"id":"SKD-TKP-0159","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menerima notifikasi kendala keamanan bahwa akun Anda masuk dari perangkat lain di luar kota. Tindakan Anda adalah...","options":["A. Membiarkan akun karena tidak ada data penting","B. Mengabaikan karena mungkin kesalahan sistem","C. Menunggu apakah ada masalah lanjutan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Mengganti kata sandi saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Segera mengganti kata sandi, mengeluarkan semua sesi aktif, mengaktifkan verifikasi dua langkah, dan melapor ke unit TI"],"ans":4,"scores":[1,2,3,4,5],"trick":"Tindak cepat saat ada akses mencurigakan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), B (2), A (1). Tindak cepat saat ada akses mencurigakan."},{"id":"SKD-TKP-0165","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta mengoperasikan aplikasi pelayanan yang baru dan menemukan kesalahan perhitungan yang merugikan warga. Pengembang meminta Anda menunggu perbaikan bulan depan. Tindakan Anda adalah...","options":["A. Mendokumentasikan kasus, memberi solusi manual sementara kepada warga terdampak, dan terus mendorong perbaikan segera melalui atasan","B. Memberi tahu warga untuk bersabar, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menunggu perbaikan sesuai jadwal, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Membiarkan kesalahan dengan alasan sistem","E. Menghentikan penggunaan aplikasi tanpa solusi"],"ans":0,"scores":[5,3,4,1,2],"trick":"Kesalahan sistem yang merugikan warga harus segera ditangani.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), E (2), D (1). Kesalahan sistem yang merugikan warga harus segera ditangani."},{"id":"SKD-TKP-0171","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Rekan Anda meminta kata sandi akun aplikasi persuratan karena akunnya terkunci dan ia harus mengirim surat penting hari ini. Sikap Anda adalah...","options":["A. Memberikan kata sandi karena rekan terpercaya","B. Menolak membagikan kata sandi, membantunya menghubungi admin untuk pemulihan akun, dan menawarkan membantu pengiriman surat melalui akun resmi yang berwenang","C. Memberikan kata sandi lalu mengganti setelah selesai","D. Mengirim surat atas nama akun Anda","E. Menyebarkan kata sandi ke tim"],"ans":1,"scores":[2,5,4,3,1],"trick":"Kata sandi bersifat pribadi dan tidak dibagikan.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Kata sandi bersifat pribadi dan tidak dibagikan."},{"id":"SKD-TKP-0177","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta membuat laporan menggunakan data yang berasal dari berbagai sumber daring yang belum terverifikasi. Sikap Anda adalah...","options":["A. Menyajikan data tanpa mencantumkan sumber, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Menggunakan sumber daring yang paling populer, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","C. Mengutamakan sumber resmi, membandingkan beberapa sumber, memberi catatan keterbatasan, dan meminta konfirmasi unit terkait","D. Menyalin laporan instansi lain, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Mengarang data agar laporan tampak lengkap"],"ans":2,"scores":[3,4,5,2,1],"trick":"Laporan harus berbasis data tervalidasi.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), D (2), E (1). Laporan harus berbasis data tervalidasi."},{"id":"SKD-TKP-0183","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Dalam pelatihan, narasumber memperkenalkan aplikasi baru yang menurut Anda bisa membantu pekerjaan, tetapi beberapa rekan menolak karena takut digantikan teknologi. Sikap Anda adalah...","options":["A. Menolak aplikasi agar tidak berkonflik","B. Menyerahkan keputusan kepada rekan","C. Menertawakan rekan yang takut","D. Menjelaskan bahwa teknologi mendukung produktivitas, mengajak rekan mencoba bersama, dan memberi contoh manfaat nyata","E. Menggunakan aplikasi untuk diri sendiri"],"ans":3,"scores":[1,3,2,5,4],"trick":"Dorong adopsi teknologi dengan pendekatan edukatif.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), C (2), A (1). Dorong adopsi teknologi dengan pendekatan edukatif."},{"id":"SKD-TKP-0189","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menerima undangan rapat daring dari tautan yang tidak dikenal dengan nama instansi mitra. Sikap Anda adalah...","options":["A. Bergabung dengan kamera mati, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Memberikan akses akun kepada penyelenggara","C. Bergabung dan mengikuti arahan peserta, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Meneruskan tautan kepada rekan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Memverifikasi undangan kepada mitra melalui kanal resmi sebelum bergabung, serta tidak membagikan data sensitif"],"ans":4,"scores":[4,1,2,3,5],"trick":"Verifikasi undangan untuk menghindari penyusupan.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), D (3), C (2), B (1). Verifikasi undangan untuk menghindari penyusupan."},{"id":"SKD-TKP-0195","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mendapat tugas membuat konten kanal resmi instansi, tetapi gambar yang cocok hanya ada di situs lain yang berhak cipta. Tindakan Anda adalah...","options":["A. Mencari sumber gambar berlisensi terbuka atau meminta izin pemilik, serta mencantumkan kredit dengan benar","B. Mengambil gambar dengan menyebut sumber, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Mengklaim gambar sebagai karya sendiri","D. Mengubah sedikit gambar agar tidak dikenali, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Memakai gambar tanpa mencantumkan sumber, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":0,"scores":[5,4,1,3,2],"trick":"Hargai hak cipta dalam konten digital.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), E (2), C (1). Hargai hak cipta dalam konten digital."},{"id":"SKD-TKP-0201","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta mengelola basis data penduduk, dan seorang kenalan meminta Anda mencarikan informasi alamat seseorang dengan alasan penting. Sikap Anda adalah...","options":["A. Memberikan informasi umum yang tidak sensitif, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Menolak mengakses data di luar kewenangan, menjelaskan prosedur permintaan resmi, dan menjaga kerahasiaan data pribadi","C. Memberikan data karena kenal baik","D. Memberikan data dengan syarat dirahasiakan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Menjual data kepada kenalan"],"ans":1,"scores":[4,5,2,3,1],"trick":"Data pribadi dilindungi; akses hanya sesuai kewenangan.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), C (2), E (1). Data pribadi dilindungi; akses hanya sesuai kewenangan."},{"id":"SKD-TKP-0207","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menemukan akun media sosial palsu mengatasnamakan instansi dan menawarkan layanan berbayar. Tindakan Anda adalah...","options":["A. Menunggu warga melapor, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Mengabaikan karena tidak merugikan instansi, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Mendokumentasikan akun, melaporkannya ke platform dan humas, serta mengumumkan kanal resmi kepada masyarakat","D. Melaporkan akun itu ke platform saja, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Membalas akun itu untuk memancing pelaku"],"ans":2,"scores":[3,2,5,4,1],"trick":"Lindungi masyarakat dari penipuan atas nama instansi.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), B (2), E (1). Lindungi masyarakat dari penipuan atas nama instansi."},{"id":"SKD-TKP-0213","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menerima surel yang mengaku dari bagian kepegawaian dan meminta Anda memperbarui kata sandi melalui tautan tertentu. Alamat pengirimnya sedikit janggal. Tindakan Anda adalah...","options":["A. Memasukkan kata sandi agar akun tidak diblokir","B. Meneruskan surel kepada rekan untuk dimintai pendapat","C. Membuka tautan hanya untuk melihat tampilannya, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Tidak membuka tautan, memeriksa keaslian pengirim melalui kanal resmi, melaporkannya ke tim keamanan informasi, dan mengingatkan rekan","E. Menghapus surel itu tanpa melaporkan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":3,"scores":[1,2,3,5,4],"trick":"Waspadai phishing: verifikasi, laporkan, dan jangan klik.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), B (2), A (1). Waspadai phishing: verifikasi, laporkan, dan jangan klik."},{"id":"SKD-TKP-0219","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menemukan bahwa data cadangan sistem tidak diperbarui selama beberapa bulan. Sikap Anda adalah...","options":["A. Menutupi temuan agar tidak dianggap lalai","B. Menunda karena belum terjadi masalah, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Mengatur jadwal pencadangan ke depan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","D. Mengingatkan rekan agar lebih disiplin, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Segera melakukan pencadangan, menetapkan jadwal otomatis, menguji pemulihan, dan melaporkan temuan kepada atasan"],"ans":4,"scores":[1,2,4,3,5],"trick":"Backup rutin dan diuji adalah bagian mitigasi risiko.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), B (2), A (1). Backup rutin dan diuji adalah bagian mitigasi risiko."},{"id":"SKD-TKP-0225","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda bertugas menyusun kebijakan penggunaan media sosial pegawai dan menemukan banyak pegawai mengunggah hal bernuansa politik. Sikap Anda adalah...","options":["A. Menyusun pedoman berdasarkan aturan netralitas ASN, mensosialisasikannya, dan membuka ruang tanya jawab","B. Melarang semua pegawai memakai media sosial","C. Mengirim edaran larangan secara tertulis, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Menegur pegawai yang paling vokal, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Membiarkan karena hak pribadi"],"ans":0,"scores":[5,1,4,3,2],"trick":"Edukasi dan pedoman jelas lebih efektif.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Edukasi dan pedoman jelas lebih efektif."},{"id":"SKD-TKP-0231","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Instansi Anda mengadakan rapat daring dan peserta mengeluh suara terputus karena sinyal buruk di daerah tertentu. Anda menjadi panitia teknis. Tindakan Anda adalah...","options":["A. Mengulang penjelasan sampai semua mengerti, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Menyediakan alternatif seperti rekaman, materi tertulis, dan opsi hadir di titik dengan sinyal baik, serta mencatat kendala untuk perbaikan","C. Membatalkan rapat","D. Melanjutkan rapat tanpa memperhatikan peserta bersinyal buruk, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Meminta peserta pindah lokasi sendiri, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda"],"ans":1,"scores":[4,5,1,3,2],"trick":"Pastikan aksesibilitas teknologi bagi semua peserta.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), E (2), C (1). Pastikan aksesibilitas teknologi bagi semua peserta."},{"id":"SKD-TKP-0237","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Instansi Anda hendak menerapkan tanda tangan elektronik, tetapi beberapa pejabat ragu keabsahannya. Sikap Anda adalah...","options":["A. Meminta pejabat tetap memakai tanda tangan basah","B. Memaksa pejabat memakai sistem tanpa penjelasan","C. Menjelaskan dasar hukum dan keamanan tanda tangan elektronik, mengadakan simulasi, dan mendampingi penggunaannya","D. Membagikan panduan tertulis","E. Menunggu keputusan pimpinan"],"ans":2,"scores":[2,1,5,4,3],"trick":"Edukasi dan pendampingan mempercepat adopsi teknologi.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), A (2), B (1). Edukasi dan pendampingan mempercepat adopsi teknologi."},{"id":"SKD-TKP-0243","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta membuat dasbor data untuk pimpinan, tetapi data dari berbagai unit tidak seragam formatnya. Sikap Anda adalah...","options":["A. Menghapus data yang sulit diolah","B. Menggabungkan data apa adanya, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Menunda pembuatan dasbor, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menyusun standar format, berkoordinasi dengan unit terkait untuk pembersihan data, dan memberi catatan keterbatasan pada dasbor","E. Mengubah angka agar terlihat seragam"],"ans":3,"scores":[2,4,3,5,1],"trick":"Kualitas data adalah dasar keputusan.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), A (2), E (1). Kualitas data adalah dasar keputusan."},{"id":"SKD-TKP-0249","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Dalam rapat, pimpinan ingin menerapkan sistem baru dalam waktu singkat padahal infrastruktur belum siap. Anda ahli TI. Sikap Anda adalah...","options":["A. Menolak rencana pimpinan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Menyetujui tanpa menyampaikan risiko","C. Menyetujui rencana lalu menyiapkan sebisanya, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Membiarkan kegagalan terjadi agar pimpinan belajar","E. Memaparkan kesiapan dan risiko dengan data, mengusulkan tahapan implementasi bertahap, dan tetap mendukung target pimpinan"],"ans":4,"scores":[3,2,4,1,5],"trick":"Sampaikan risiko berbasis data dan tawarkan solusi bertahap.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), A (3), B (2), D (1). Sampaikan risiko berbasis data dan tawarkan solusi bertahap."},{"id":"SKD-TKP-0255","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Rekan Anda mengunggah foto dokumen rapat internal di media sosial pribadi karena bangga dengan pekerjaannya. Dokumen itu belum dipublikasikan. Tindakan Anda adalah...","options":["A. Meminta rekan segera menghapusnya, menjelaskan risiko kebocoran informasi, dan melaporkan kepada atasan bila sudah menyebar luas","B. Menyukai unggahan tersebut","C. Menyebarkan ulang unggahan itu","D. Melaporkan langsung kepada atasan tanpa menegur, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Meminta rekan lebih berhati-hati lain kali, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":0,"scores":[5,2,1,3,4],"trick":"Informasi internal tidak boleh dipublikasikan sembarangan.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), B (2), C (1). Informasi internal tidak boleh dipublikasikan sembarangan."},{"id":"SKD-TKP-0261","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mengelola situs resmi instansi dan menemukan tampilan situs berubah karena diserang peretas. Tindakan Anda adalah...","options":["A. Memulihkan situs tanpa melapor, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Mengisolasi situs, mengamankan bukti serangan, memulihkan dari cadangan, melapor kepada tim keamanan, dan mengumumkan kepada publik secara transparan","C. Menyalahkan pihak lain tanpa penyelidikan","D. Membiarkan situs sementara, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Menutupi kejadian dari publik"],"ans":1,"scores":[4,5,1,3,2],"trick":"Tangani insiden siber secara terukur dan transparan.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), E (2), C (1). Tangani insiden siber secara terukur dan transparan."},{"id":"SKD-TKP-0267","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta membuat tampilan formulir daring layanan publik. Sebagian pengguna adalah penyandang tunanetra. Sikap Anda adalah...","options":["A. Membuat tampilan standar lalu menunggu keluhan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Menambahkan petunjuk suara sederhana, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Mengikuti prinsip aksesibilitas seperti teks alternatif, kontras jelas, dan dukungan pembaca layar, serta mengujinya bersama pengguna","D. Mengabaikan karena pengguna sedikit","E. Menganggap pengguna tunanetra bisa dibantu keluarga, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":2,"scores":[3,4,5,1,2],"trick":"Teknologi publik harus inklusif.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), E (2), D (1). Teknologi publik harus inklusif."},{"id":"SKD-TKP-0273","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda melihat banyak warga lansia kesulitan memakai aplikasi layanan online instansi dan sering salah memasukkan data. Usulan Anda adalah...","options":["A. Menyatakan aplikasi sudah sesuai standar","B. Menghentikan layanan bagi lansia","C. Mengimbau warga meminta bantuan anak-anak mereka, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Menyederhanakan tampilan aplikasi, menyediakan petunjuk bergambar, dan membuka pendampingan di kantor atau kelurahan","E. Membuat video panduan penggunaan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":3,"scores":[2,1,3,5,4],"trick":"Desain layanan digital harus ramah pengguna.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), A (2), B (1). Desain layanan digital harus ramah pengguna."},{"id":"SKD-TKP-0279","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Instansi Anda memakai aplikasi baru untuk absensi dan kinerja, tetapi banyak rekan senior kesulitan memakainya. Sikap Anda adalah...","options":["A. Menertawakan kesulitan mereka","B. Membantu hanya jika diminta, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Meminta rekan membaca buku panduan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Mengisikan absensi rekan agar cepat","E. Membantu rekan senior dengan panduan sederhana dan pendampingan, serta menyampaikan kebutuhan pelatihan kepada atasan"],"ans":4,"scores":[2,4,3,1,5],"trick":"Pendampingan literasi digital dengan sabar.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), C (3), A (2), D (1). Pendampingan literasi digital dengan sabar."},{"id":"SKD-TKP-0285","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mengetahui rekan menggunakan perangkat lunak bajakan di komputer kantor. Sikap Anda adalah...","options":["A. Mengingatkan rekan akan risiko hukum dan keamanan, mengusulkan memakai perangkat lunak berlisensi atau sumber terbuka, serta melapor ke unit TI jika berlanjut","B. Membiarkan karena tidak berdampak langsung, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Menyebarkan perangkat lunak bajakan ke rekan lain","D. Mengingatkan rekan dan tidak melapor, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Ikut memakai perangkat lunak bajakan, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":0,"scores":[5,3,1,4,2],"trick":"Hormati lisensi dan hak kekayaan intelektual.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Hormati lisensi dan hak kekayaan intelektual."},{"id":"SKD-TKP-0291","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda mendapati sistem informasi kantor menampilkan data pegawai lain saat Anda masuk dengan akun sendiri. Tindakan Anda adalah...","options":["A. Menyalin data untuk bukti pribadi","B. Menghentikan penggunaan data tersebut, mendokumentasikan kejadian, dan segera melapor ke administrator sistem dan atasan","C. Menginformasikan rekan lain tentang celah itu, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menutup halaman dan melanjutkan pekerjaan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Memanfaatkan celah untuk melihat data lain"],"ans":1,"scores":[2,5,3,4,1],"trick":"Temuan celah keamanan dilaporkan, bukan dimanfaatkan.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), A (2), E (1). Temuan celah keamanan dilaporkan, bukan dimanfaatkan."},{"id":"SKD-TKP-0297","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menerima permintaan dari media daring untuk mengonfirmasi sebuah video viral yang diklaim menunjukkan pegawai instansi Anda berbuat curang. Sikap Anda adalah...","options":["A. Menjawab bahwa Anda belum tahu apa-apa","B. Menolak berkomentar","C. Memverifikasi kebenaran video dengan unit terkait, menyampaikan ke humas dan pimpinan, dan memberi klarifikasi resmi setelah fakta jelas","D. Membantah video tanpa memeriksa","E. Membenarkan video agar media puas"],"ans":2,"scores":[4,3,5,1,2],"trick":"Klarifikasi berbasis fakta lewat jalur resmi.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), E (2), D (1). Klarifikasi berbasis fakta lewat jalur resmi."},{"id":"SKD-TKP-0303","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Pimpinan meminta Anda mengirim data penting melalui email pribadi karena email kantor sedang bermasalah. Sikap Anda adalah...","options":["A. Mengirim data karena perintah pimpinan","B. Menyalin data ke beberapa email pribadi","C. Mengirim sebagian data, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Menyampaikan risiko, mengusulkan alternatif aman seperti berbagi berkas melalui sistem resmi atau menunggu perbaikan, dan meminta persetujuan tertulis bila terpaksa","E. Mengirim data setelah dienkripsi sederhana, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[2,1,3,5,4],"trick":"Sampaikan risiko dan cari jalur aman.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), A (2), B (1). Sampaikan risiko dan cari jalur aman."},{"id":"SKD-TKP-0309","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menemukan aplikasi internal sering dipakai tetapi tidak pernah diperbarui sehingga banyak celah keamanan. Anda bukan pengelola aplikasi. Tindakan Anda adalah...","options":["A. Mengeksploitasi celah untuk menguji kemampuan","B. Menunggu pengelola menyadarinya","C. Mengabaikan karena bukan wewenang Anda","D. Memberi tahu rekan terdekat saja","E. Mendokumentasikan temuan, menyampaikan ke pengelola dan atasan, serta menawarkan bantuan mengidentifikasi perbaikan"],"ans":4,"scores":[1,3,2,4,5],"trick":"Laporkan temuan keamanan kepada pihak berwenang.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Laporkan temuan keamanan kepada pihak berwenang."},{"id":"SKD-TKP-0315","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Seorang rekan berbagi tangkapan layar percakapan resmi pimpinan ke grup santai yang berisi banyak anggota di luar kantor. Sikap Anda adalah...","options":["A. Meminta rekan menghapusnya, menjelaskan risiko kerahasiaan, dan melaporkan kepada atasan jika sudah menyebar","B. Menyebarkan tangkapan layar ke media sosial","C. Membiarkan karena isinya tidak penting","D. Ikut meneruskan tangkapan layar","E. Meminta rekan lebih berhati-hati"],"ans":0,"scores":[5,1,3,2,4],"trick":"Percakapan resmi bersifat rahasia.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), D (2), B (1). Percakapan resmi bersifat rahasia."},{"id":"SKD-TKP-0321","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Seorang warga meminta bantuan menghapus data pribadinya dari basis data instansi karena merasa privasinya terganggu. Sikap Anda adalah...","options":["A. Meminta warga mengirim surat resmi, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Menjelaskan prosedur permintaan sesuai aturan perlindungan data, memverifikasi identitas, dan meneruskan ke pihak berwenang untuk diproses","C. Mengabaikan permintaan tersebut","D. Menghapus data tanpa prosedur, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Menolak karena data milik instansi"],"ans":1,"scores":[4,5,1,3,2],"trick":"Hak warga atas data pribadi dihormati melalui prosedur.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), E (2), C (1). Hak warga atas data pribadi dihormati melalui prosedur."},{"id":"SKD-TKP-0327","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda menemukan flashdisk tanpa label di ruang rapat kantor. Tindakan Anda adalah...","options":["A. Membawa pulang untuk dipakai","B. Menyimpannya hingga pemiliknya mencari, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Tidak mencolokkannya ke komputer kantor, menyerahkannya ke unit TI atau keamanan, dan mencatat lokasi penemuan","D. Mencolokkan di komputer kantor untuk mencari pemilik, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","E. Memeriksanya di komputer pribadi, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":2,"scores":[1,4,5,2,3],"trick":"Media tak dikenal berisiko membawa malware.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Media tak dikenal berisiko membawa malware."},{"id":"SKD-TKP-0333","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda ditugaskan membuat video sosialisasi dan perlu merekam warga. Beberapa warga tidak bersedia wajahnya ditampilkan. Sikap Anda adalah...","options":["A. Mengunggah video tanpa persetujuan","B. Merekam secara diam-diam","C. Merekam tanpa menampilkan wajah warga yang menolak","D. Menghormati keberatan warga, meminta persetujuan tertulis untuk yang bersedia, dan menyamarkan wajah yang tidak bersedia","E. Meminta warga menandatangani persetujuan sekaligus"],"ans":3,"scores":[1,2,4,5,3],"trick":"Hak citra warga dihormati.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), B (2), A (1). Hak citra warga dihormati."},{"id":"SKD-TKP-0339","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Seorang penyedia layanan aplikasi menawarkan Anda fasilitas perjalanan jika mau memilih produknya untuk instansi. Sikap Anda adalah...","options":["A. Menerima asalkan produk memang bagus","B. Menerima dan memilih produk tersebut","C. Menolak tawaran dengan sopan, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","D. Menerima setelah memberi tahu rekan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Menolak tawaran, melaporkan upaya tersebut sesuai ketentuan gratifikasi, dan memilih produk berdasarkan kebutuhan serta kajian objektif"],"ans":4,"scores":[2,1,4,3,5],"trick":"Pengadaan teknologi bebas konflik kepentingan.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), A (2), B (1). Pengadaan teknologi bebas konflik kepentingan."},{"id":"SKD-TKP-0345","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Jaringan internet kantor sering lambat karena banyak pegawai mengunduh video hiburan. Anda tim TI. Tindakan Anda adalah...","options":["A. Memantau penggunaan bandwidth, menetapkan kebijakan penggunaan, mensosialisasikan aturan, dan mengatur prioritas layanan penting","B. Mematikan jaringan pada jam tertentu","C. Menunggu pegawai menyadari sendiri","D. Menambah kapasitas tanpa kebijakan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Memblokir semua situs video, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun"],"ans":0,"scores":[5,1,2,3,4],"trick":"Kelola sumber daya jaringan dengan kebijakan dan edukasi.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), C (2), B (1). Kelola sumber daya jaringan dengan kebijakan dan edukasi."},{"id":"SKD-TKP-0351","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Anda diminta mengunggah data statistik ke portal data terbuka, tetapi sebagian tabel memuat data yang dapat mengidentifikasi individu. Tindakan Anda adalah...","options":["A. Mengunggah data setelah menghapus kolom nama, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Menganonimkan atau mengagregasi data, memeriksa dengan unit hukum, dan baru mengunggah setelah aman","C. Menunda tanpa menjelaskan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menjual data kepada peneliti","E. Mengunggah seluruh data apa adanya, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":1,"scores":[4,5,2,1,3],"trick":"Keterbukaan data tidak boleh mengorbankan privasi.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), E (3), C (2), D (1). Keterbukaan data tidak boleh mengorbankan privasi."},{"id":"SKD-TKP-0357","sub":"Teknologi Informasi dan Komunikasi (TIK)","q":"Seorang rekan yang gagap teknologi sering meminta bantuan memasang aplikasi pribadinya di komputer kantor. Sikap Anda adalah...","options":["A. Menyuruh rekan memasang sendiri tanpa panduan","B. Memasang semua aplikasi permintaannya","C. Menjelaskan kebijakan penggunaan perangkat kantor, menawarkan membantu mengaktifkan layanan resmi, dan mengajarkan cara sederhana untuk kebutuhan kerja","D. Menolak membantu, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Membantu satu kali dengan syarat tidak diulang, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan"],"ans":2,"scores":[1,2,5,3,4],"trick":"Patuhi kebijakan perangkat dan edukasi pengguna.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), D (3), B (2), A (1). Patuhi kebijakan perangkat dan edukasi pengguna."},{"id":"SKD-TKP-0046","sub":"Profesionalisme","q":"Anda mendapat hadiah dari warga yang telah dibantu, berupa bingkisan makanan dalam jumlah kecil. Sikap Anda adalah...","options":["A. Menolak dengan sopan, menjelaskan bahwa layanan tidak memerlukan imbalan, dan melaporkan sesuai ketentuan bila telanjur diterima","B. Meminta hadiah yang lebih besar","C. Menerima lalu membagikan ke rekan kantor, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Menerima karena nilainya kecil","E. Menerima dan menyimpan diam-diam, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":0,"scores":[5,1,4,2,3],"trick":"Gratifikasi, sekecil apa pun, mengikuti ketentuan.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), E (3), D (2), B (1). Gratifikasi, sekecil apa pun, mengikuti ketentuan."},{"id":"SKD-TKP-0052","sub":"Profesionalisme","q":"Pada hari ulang tahun instansi, pimpinan meminta setiap pegawai ikut menyumbang uang dalam jumlah yang cukup besar bagi Anda. Sikap Anda adalah...","options":["A. Menolak tanpa penjelasan","B. Menyampaikan keberatan secara sopan, menawarkan kontribusi sesuai kemampuan, dan mengingatkan agar iuran bersifat sukarela","C. Menyebarkan keluhan kepada rekan-rekan","D. Menyumbang dengan berhutang, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menyumbang sesuai permintaan agar tidak masalah, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":1,"scores":[2,5,1,3,4],"trick":"Iuran harus sukarela dan wajar.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), A (2), C (1). Iuran harus sukarela dan wajar."},{"id":"SKD-TKP-0058","sub":"Profesionalisme","q":"Pada akhir tahun, Anda diminta membuat evaluasi kinerja pribadi, tetapi sebagian target belum tercapai. Sikap Anda adalah...","options":["A. Menaikkan angka capaian agar terlihat baik","B. Menyalahkan faktor eksternal","C. Melaporkan capaian apa adanya, menjelaskan kendala, dan menyusun rencana perbaikan yang terukur","D. Melaporkan capaian dengan penekanan pada keberhasilan","E. Meminta rekan membuatkan laporan yang menguntungkan"],"ans":2,"scores":[2,3,5,4,1],"trick":"Evaluasi kinerja harus jujur.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), A (2), E (1). Evaluasi kinerja harus jujur."},{"id":"SKD-TKP-0064","sub":"Profesionalisme","q":"Anda ditempatkan di bagian baru dan merasa kurang percaya diri karena kemampuan Anda belum sebanding dengan rekan senior. Sikap Anda adalah...","options":["A. Menyalahkan kemampuan sendiri","B. Bekerja sesuai instruksi saja","C. Menunggu bimbingan dari rekan","D. Menyusun rencana belajar, meminta bimbingan, dan berlatih konsisten sambil menunjukkan kontribusi bertahap","E. Meminta kembali ke bagian lama"],"ans":3,"scores":[2,4,3,5,1],"trick":"Belajar berkelanjutan membangun kompetensi.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), C (3), A (2), E (1). Belajar berkelanjutan membangun kompetensi."},{"id":"SKD-TKP-0070","sub":"Profesionalisme","q":"Anda memegang dokumen rahasia jabatan, dan seorang kawan dekat di instansi lain meminta bocoran. Sikap Anda adalah...","options":["A. Menjual informasi kepada kawan","B. Memberikan informasi karena percaya","C. Menolak halus tanpa menjelaskan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Memberikan petunjuk umum, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menolak tegas, menjelaskan kewajiban menjaga rahasia jabatan, dan mengarahkan ke prosedur permintaan informasi resmi"],"ans":4,"scores":[1,2,4,3,5],"trick":"Rahasia jabatan wajib dijaga.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), D (3), B (2), A (1). Rahasia jabatan wajib dijaga."},{"id":"SKD-TKP-0076","sub":"Profesionalisme","q":"Anda mengetahui bahwa pelaksanaan tugas Anda berpotensi menimbulkan kerugian bagi masyarakat karena aturan yang berubah. Atasan Anda belum mengetahuinya. Sikap Anda adalah...","options":["A. Segera melaporkan perubahan aturan kepada atasan, menyesuaikan pelaksanaan tugas, dan menginformasikan pihak terkait","B. Menunggu atasan mengetahui, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Melanjutkan pekerjaan sesuai instruksi lama, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Menyalahkan pembuat aturan","E. Memanfaatkan perubahan aturan untuk keuntungan pribadi"],"ans":0,"scores":[5,4,3,2,1],"trick":"Proaktif menyesuaikan dengan regulasi baru.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), C (3), D (2), E (1). Proaktif menyesuaikan dengan regulasi baru."},{"id":"SKD-TKP-0082","sub":"Profesionalisme","q":"Anda diminta membantu pegawai yang akan pensiun menyiapkan berkas, tetapi pekerjaan Anda sendiri sedang menumpuk. Sikap Anda adalah...","options":["A. Membantu seperlunya","B. Menetapkan prioritas, menjadwalkan waktu khusus untuk membantu, dan memastikan berkas pensiun lengkap tepat waktu","C. Meminta rekan lain membantu","D. Menunda sampai pekerjaan selesai","E. Menolak membantu"],"ans":1,"scores":[4,5,3,2,1],"trick":"Peduli dan bertanggung jawab pada rekan.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), D (2), E (1). Peduli dan bertanggung jawab pada rekan."},{"id":"SKD-TKP-0088","sub":"Profesionalisme","q":"Rekan Anda menyontek laporan kerja dari instansi lain dan mengklaim sebagai hasil sendiri. Anda mengetahuinya. Tindakan Anda adalah...","options":["A. Menegur rekan saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Ikut menyalin untuk laporan Anda, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","C. Menegur rekan, menjelaskan konsekuensi plagiarisme, dan menyampaikan kepada atasan bila tetap dilakukan","D. Memeras rekan agar tutup mulut","E. Membiarkan karena bukan urusan Anda, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":2,"scores":[4,2,5,1,3],"trick":"Orisinalitas dan kejujuran dalam bekerja.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), B (2), D (1). Orisinalitas dan kejujuran dalam bekerja."},{"id":"SKD-TKP-0094","sub":"Profesionalisme","q":"Atasan meminta Anda menyusun sambutan untuk acara resmi dengan batas waktu satu jam. Anda belum pernah membuatnya. Sikap Anda adalah...","options":["A. Menolak karena belum berpengalaman, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Meminta rekan membuatkan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Menyusun sambutan seadanya, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Mengumpulkan informasi utama, menggunakan contoh sambutan sebelumnya sebagai pola, dan meminta masukan singkat dari rekan sebelum diserahkan","E. Menyalin sambutan lama tanpa menyesuaikan"],"ans":3,"scores":[2,3,4,5,1],"trick":"Siap menghadapi tugas baru dengan pendekatan terstruktur.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), B (3), A (2), E (1). Siap menghadapi tugas baru dengan pendekatan terstruktur."},{"id":"SKD-TKP-0100","sub":"Profesionalisme","q":"Anda mengetahui pimpinan memberi nilai kinerja lebih tinggi kepada pegawai yang dekat dengannya. Anda salah satu yang merasa dirugikan. Sikap Anda adalah...","options":["A. Menerima hasil dan memendam kekecewaan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Menurunkan kinerja sebagai protes","C. Mengajukan keberatan secara lisan kepada rekan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Menyebarkan isu tentang pimpinan","E. Meminta klarifikasi kriteria penilaian secara sopan, menyiapkan bukti capaian, dan menggunakan mekanisme keberatan resmi bila perlu"],"ans":4,"scores":[3,2,4,1,5],"trick":"Gunakan mekanisme resmi untuk keberatan.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), A (3), B (2), D (1). Gunakan mekanisme resmi untuk keberatan."},{"id":"SKD-TKP-0106","sub":"Profesionalisme","q":"Anda dipercaya menjadi bendahara kegiatan dan menemukan selisih kecil pada kas yang belum jelas penyebabnya. Sikap Anda adalah...","options":["A. Menelusuri catatan, melaporkan selisih kepada atasan secara terbuka, dan memperbaiki pencatatan agar tidak terulang","B. Menutup selisih dengan uang pribadi","C. Mencatat selisih sebagai biaya lain-lain","D. Menggunakan selisih untuk keperluan pribadi","E. Menyembunyikan selisih karena kecil"],"ans":0,"scores":[5,4,3,1,2],"trick":"Transparansi pengelolaan keuangan.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), C (3), E (2), D (1). Transparansi pengelolaan keuangan."},{"id":"SKD-TKP-0112","sub":"Profesionalisme","q":"Anda menemukan bahwa anggaran kegiatan unit Anda sebagian digunakan untuk keperluan pribadi atasan. Tindakan Anda adalah...","options":["A. Menanyakan langsung kepada atasan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Mengumpulkan bukti dengan hati-hati, melaporkan kepada unit pengawasan internal, dan menjaga kerahasiaan pelapor","C. Menyampaikan kepada rekan saja, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Membiarkan karena Anda bawahan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Ikut memanfaatkan anggaran tersebut"],"ans":1,"scores":[4,5,3,2,1],"trick":"Laporkan penyalahgunaan anggaran lewat saluran resmi.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), D (2), E (1). Laporkan penyalahgunaan anggaran lewat saluran resmi."},{"id":"SKD-TKP-0118","sub":"Profesionalisme","q":"Anda diminta menyusun jawaban atas pertanyaan DPRD mengenai kinerja instansi, tetapi sebagian data kurang menguntungkan. Sikap Anda adalah...","options":["A. Meminta pihak lain menjawab","B. Menyajikan data dengan penekanan pada capaian positif, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Menyajikan data apa adanya, menjelaskan konteks dan rencana perbaikan, serta berkoordinasi dengan pimpinan sebelum jawaban disampaikan","D. Menghilangkan data yang kurang menguntungkan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Mengubah data agar tampak baik"],"ans":2,"scores":[2,4,5,3,1],"trick":"Transparansi dengan konteks dan rencana perbaikan.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), D (3), A (2), E (1). Transparansi dengan konteks dan rencana perbaikan."},{"id":"SKD-TKP-0124","sub":"Profesionalisme","q":"Anda diminta tampil sebagai pembicara di televisi untuk menjelaskan program instansi, tetapi Anda merasa gugup. Sikap Anda adalah...","options":["A. Meminta pimpinan menggantikan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Berbicara tanpa persiapan","C. Menyiapkan catatan dan tampil seadanya, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Mempersiapkan materi dan latihan, meminta masukan humas, dan menyampaikan informasi yang akurat dengan tenang","E. Membatalkan penampilan, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":3,"scores":[3,1,4,5,2],"trick":"Persiapan matang untuk komunikasi publik.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), A (3), E (2), B (1). Persiapan matang untuk komunikasi publik."},{"id":"SKD-TKP-0130","sub":"Profesionalisme","q":"Seorang rekan menitipkan absensi kepada Anda karena datang terlambat. Sikap Anda adalah...","options":["A. Mengisi absensi sekali ini saja","B. Menolak tanpa menjelaskan","C. Mengisi absensi dan meminta imbalan","D. Mengisi absensi karena rekan dekat","E. Menolak dengan sopan, menjelaskan bahwa absensi harus dilakukan sendiri, dan mengingatkan konsekuensinya"],"ans":4,"scores":[3,4,1,2,5],"trick":"Disiplin dan jujur dalam kehadiran.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), A (3), D (2), C (1). Disiplin dan jujur dalam kehadiran."},{"id":"SKD-TKP-0136","sub":"Profesionalisme","q":"Anda ditunjuk menjadi pejabat pembuat komitmen dan seorang kerabat dekat ikut dalam tender yang Anda kelola. Sikap Anda adalah...","options":["A. Menyatakan konflik kepentingan secara tertulis kepada atasan, mengundurkan diri dari proses terkait, dan memastikan penilaian oleh pihak lain","B. Memenangkan kerabat tersebut","C. Diam-diam membantu kerabat","D. Tetap mengelola tender tetapi tidak memihak, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Menyampaikan hal itu secara lisan kepada rekan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":0,"scores":[5,1,2,4,3],"trick":"Konflik kepentingan wajib dinyatakan dan dihindari.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), C (2), B (1). Konflik kepentingan wajib dinyatakan dan dihindari."},{"id":"SKD-TKP-0142","sub":"Profesionalisme","q":"Dalam proyek riset instansi, Anda diminta menyimpulkan hasil analisis, tetapi hasilnya berbeda dengan harapan pimpinan. Sikap Anda adalah...","options":["A. Memanipulasi data agar sesuai harapan","B. Menyajikan hasil sesuai data, menjelaskan metode secara transparan, dan bersedia mendiskusikan kemungkinan tinjauan lanjutan","C. Menunda laporan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Menyesuaikan kesimpulan agar sesuai harapan","E. Menyajikan hasil dan menyerahkan kesimpulan kepada pimpinan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":1,"scores":[1,5,3,2,4],"trick":"Integritas ilmiah dan profesional.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), C (3), D (2), A (1). Integritas ilmiah dan profesional."},{"id":"SKD-TKP-0148","sub":"Profesionalisme","q":"Anda mendapat undangan makan malam dari rekanan yang sedang mengikuti pengadaan di instansi Anda. Sikap Anda adalah...","options":["A. Hadir tetapi membayar sendiri, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Hadir dan menerima fasilitas","C. Menolak undangan, mengingatkan etika pengadaan, dan memastikan proses pengadaan berjalan transparan","D. Menolak dengan alasan sibuk, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","E. Hadir asalkan tidak membahas pengadaan, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan"],"ans":2,"scores":[3,1,5,4,2],"trick":"Jaga independensi dalam pengadaan.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), E (2), B (1). Jaga independensi dalam pengadaan."},{"id":"SKD-TKP-0154","sub":"Profesionalisme","q":"Dalam rapat, atasan menyampaikan target baru yang sangat tinggi dan tampak mustahil bagi tim Anda. Sikap Anda adalah...","options":["A. Menyetujui target tanpa membahas kendala, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","B. Menolak target di forum, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Menyetujui lalu menurunkan kualitas kerja, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","D. Menyampaikan analisis kemampuan tim dengan data, mengusulkan strategi pencapaian bertahap, dan tetap menunjukkan komitmen","E. Membicarakan atasan kepada rekan lain"],"ans":3,"scores":[4,3,2,5,1],"trick":"Komitmen disertai analisis realistis.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), B (3), C (2), E (1). Komitmen disertai analisis realistis."},{"id":"SKD-TKP-0160","sub":"Profesionalisme","q":"Seorang rekan mengajak Anda memakai kendaraan dinas untuk keperluan liburan keluarga di akhir pekan. Sikap Anda adalah...","options":["A. Meminjamkan kendaraan karena sungkan","B. Memakai kendaraan dinas karena sudah biasa","C. Setuju asalkan bahan bakar diganti sendiri, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menolak tanpa komentar, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Menolak dengan sopan, mengingatkan bahwa kendaraan dinas hanya untuk tugas kedinasan, dan menawarkan alternatif kendaraan pribadi atau sewa"],"ans":4,"scores":[2,1,3,4,5],"trick":"Aset negara dipakai hanya untuk tugas dinas.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), C (3), A (2), B (1). Aset negara dipakai hanya untuk tugas dinas."},{"id":"SKD-TKP-0166","sub":"Profesionalisme","q":"Anda mengetahui sebuah kegiatan fiktif dicatat dalam laporan pertanggungjawaban, dan pelakunya adalah atasan Anda. Tindakan Anda adalah...","options":["A. Mengamankan bukti, melapor melalui saluran pengaduan atau unit pengawasan, serta menggunakan perlindungan bagi pelapor","B. Meminta bagian dari kegiatan fiktif","C. Mengingatkan atasan secara tertutup, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Mendiskusikan dengan rekan, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Diam demi keselamatan karier"],"ans":0,"scores":[5,1,4,3,2],"trick":"Berani melaporkan penyimpangan.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Berani melaporkan penyimpangan."},{"id":"SKD-TKP-0172","sub":"Profesionalisme","q":"Seorang rekan baru bertanya kepada Anda tentang cara cepat menyelesaikan pekerjaan dengan melewati beberapa prosedur. Sikap Anda adalah...","options":["A. Menyuruh melewati prosedur tanpa laporan","B. Menjelaskan alasan prosedur, membantu mencari cara efisien yang tetap sesuai aturan, dan mengajaknya berdiskusi dengan atasan","C. Menjelaskan prosedur dan menyuruhnya mengikuti, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menyarankan bertanya kepada orang lain, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Memberi cara pintas yang berisiko"],"ans":1,"scores":[1,5,4,3,2],"trick":"Efisiensi tanpa melanggar prosedur.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), E (2), A (1). Efisiensi tanpa melanggar prosedur."},{"id":"SKD-TKP-0178","sub":"Profesionalisme","q":"Anda adalah ASN yang menerima ajakan investasi dengan imbal hasil sangat tinggi dari rekan kerja dan diminta ikut mengajak yang lain. Sikap Anda adalah...","options":["A. Mengajak banyak rekan agar mendapat bonus","B. Menolak ikut tanpa memberi masukan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","C. Menolak ikut, memeriksa legalitas melalui lembaga resmi, dan mengingatkan rekan akan risiko penipuan investasi","D. Ikut berinvestasi lalu mengajak sedikit rekan","E. Mencoba investasi kecil dulu, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":2,"scores":[1,4,5,2,3],"trick":"Waspada penipuan dan jaga integritas.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Waspada penipuan dan jaga integritas."},{"id":"SKD-TKP-0184","sub":"Profesionalisme","q":"Anda mendapat tugas tambahan dari atasan di luar jam kerja melalui pesan malam hari. Sikap Anda adalah...","options":["A. Mengabaikan pesan sampai pagi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Menonaktifkan ponsel selama beberapa hari","C. Membalas dengan nada kesal","D. Menilai urgensinya, merespons seperlunya bila mendesak, dan membicarakan batas waktu komunikasi kerja dengan atasan secara baik","E. Membalas semua pesan secepat mungkin, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":3,"scores":[3,1,2,5,4],"trick":"Responsif namun menjaga batas kerja dengan komunikasi baik.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), A (3), C (2), B (1). Responsif namun menjaga batas kerja dengan komunikasi baik."},{"id":"SKD-TKP-0190","sub":"Profesionalisme","q":"Anda mengerjakan tugas bersama dan mendapati beberapa data tidak sesuai dengan hasil lapangan, tetapi jika dikoreksi laporan akan terlambat. Tindakan Anda adalah...","options":["A. Mengubah hasil lapangan agar sesuai","B. Melaporkan data apa adanya lalu menandai kemungkinan kesalahan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Menyembunyikan data yang tidak sesuai, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","D. Menyerahkan laporan tepat waktu dan mengoreksi nanti, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Mengoreksi data, menyampaikan alasan keterlambatan kepada atasan dengan jadwal baru, dan memastikan laporan akurat"],"ans":4,"scores":[1,4,2,3,5],"trick":"Akurasi lebih penting daripada kecepatan semata.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), D (3), C (2), A (1). Akurasi lebih penting daripada kecepatan semata."},{"id":"SKD-TKP-0196","sub":"Profesionalisme","q":"Anda diminta menandatangani dokumen pertanggungjawaban kegiatan yang belum Anda periksa kebenarannya. Tindakan Anda adalah...","options":["A. Memeriksa kelengkapan dan kebenaran dokumen terlebih dahulu, menanyakan hal yang janggal, lalu menandatangani setelah yakin","B. Menandatangani tanpa membaca","C. Menandatangani karena sudah diperiksa bagian lain, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menandatangani sebagian dokumen, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menandatangani dengan alasan kejar waktu, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":0,"scores":[5,1,4,3,2],"trick":"Tanggung jawab tanda tangan menuntut verifikasi.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Tanggung jawab tanda tangan menuntut verifikasi."},{"id":"SKD-TKP-0202","sub":"Profesionalisme","q":"Menjelang batas akhir pengumpulan dokumen kenaikan pangkat, Anda mendapati sertifikat pelatihan Anda hilang. Tindakan Anda adalah...","options":["A. Menunda pengajuan sampai periode berikutnya, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Menghubungi penyelenggara untuk meminta salinan atau surat keterangan, mengabari bagian kepegawaian, dan memohon kelonggaran sesuai aturan","C. Membuat sertifikat pengganti sendiri","D. Meminta rekan meminjamkan sertifikat mereka, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Memalsukan tanda tangan penyelenggara"],"ans":1,"scores":[4,5,2,3,1],"trick":"Selesaikan masalah dengan cara jujur dan prosedural.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), D (3), C (2), E (1). Selesaikan masalah dengan cara jujur dan prosedural."},{"id":"SKD-TKP-0208","sub":"Profesionalisme","q":"Atasan meminta Anda menyelesaikan laporan keuangan kegiatan malam ini juga, padahal beberapa bukti pengeluaran belum lengkap. Sikap Anda adalah...","options":["A. Menolak mengerjakan sampai semua bukti lengkap, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Menyerahkan laporan kosong dan menyalahkan atasan","C. Menyusun laporan dengan data yang valid, mencatat bukti yang belum lengkap, menyampaikan kendala kepada atasan, dan melengkapi segera setelah bukti tersedia","D. Menyelesaikan laporan dengan perkiraan angka agar tepat waktu, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Melengkapi bukti dengan nota yang dibuat sendiri"],"ans":2,"scores":[3,1,5,4,2],"trick":"Akuntabel: selesai tepat waktu tanpa memalsukan data.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), A (3), E (2), B (1). Akuntabel: selesai tepat waktu tanpa memalsukan data."},{"id":"SKD-TKP-0214","sub":"Profesionalisme","q":"Atasan Anda memerintahkan memperbesar nilai pengeluaran kegiatan agar anggaran terserap penuh. Tindakan Anda adalah...","options":["A. Mengerjakan dan meminta bagian dari selisih","B. Mengerjakan perintah agar atasan senang","C. Menolak dan menyarankan atasan menanyakan ke bagian keuangan","D. Menolak dengan sopan, menjelaskan konsekuensi hukumnya, mengusulkan realisasi sesuai kebutuhan, dan melapor ke jalur pengawasan bila perintah tetap dipaksakan","E. Mengerjakan sebagian perintah"],"ans":3,"scores":[1,2,4,5,3],"trick":"Integritas: tolak perintah yang melanggar hukum.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), B (2), A (1). Integritas: tolak perintah yang melanggar hukum."},{"id":"SKD-TKP-0220","sub":"Profesionalisme","q":"Anda diminta pindah tugas ke unit yang lebih berat dan kurang diminati oleh rekan lain. Sikap Anda adalah...","options":["A. Melaksanakan tugas dengan kesal dan mengeluhkan unit baru","B. Meminta pertimbangan atasan untuk diganti","C. Menerima dan menjalankan seperlunya","D. Menolak dengan berbagai alasan","E. Menerima dengan terbuka, mempelajari kebutuhan unit, dan berusaha memberi kontribusi terbaik"],"ans":4,"scores":[1,3,4,2,5],"trick":"Siap ditempatkan di mana pun.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), D (2), A (1). Siap ditempatkan di mana pun."},{"id":"SKD-TKP-0226","sub":"Profesionalisme","q":"Anda diberi tugas mewakili pimpinan menghadiri rapat penting dan baru mengetahui bahwa materinya belum Anda pahami. Sikap Anda adalah...","options":["A. Mempelajari materi secara cepat, berkonsultasi dengan atasan dan rekan, dan menyiapkan catatan untuk disampaikan kembali","B. Menghadiri rapat tanpa persiapan dan memberi pendapat sekenanya","C. Meminta rekan menggantikan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Menghadiri rapat dan mendengarkan saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Tidak menghadiri rapat"],"ans":0,"scores":[5,1,3,4,2],"trick":"Persiapan menunjukkan profesionalisme.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), C (3), E (2), B (1). Persiapan menunjukkan profesionalisme."},{"id":"SKD-TKP-0232","sub":"Profesionalisme","q":"Pimpinan menugaskan Anda memimpin satgas sementara dengan anggota yang lebih senior. Sikap Anda adalah...","options":["A. Meminta pimpinan mengganti anggota","B. Menghargai pengalaman anggota, menetapkan tujuan jelas, membagi peran, dan membuka ruang diskusi sambil tetap tegas","C. Mengikuti saran anggota senior","D. Mengambil keputusan sendiri","E. Menolak memimpin"],"ans":1,"scores":[2,5,4,3,1],"trick":"Kepemimpinan dengan rendah hati dan tegas.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Kepemimpinan dengan rendah hati dan tegas."},{"id":"SKD-TKP-0238","sub":"Profesionalisme","q":"Anda baru saja lulus dalam seleksi CPNS dan mendapatkan penempatan di daerah yang jauh dari keluarga. Sikap Anda adalah...","options":["A. Menolak penempatan, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","B. Menerima sambil berharap segera dipindahkan, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Menerima dengan rasa syukur, mempersiapkan diri beradaptasi, dan berkomitmen melayani masyarakat di tempat tugas","D. Meminta pertimbangan penempatan ulang, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menggunakan koneksi agar ditempatkan di tempat yang diinginkan"],"ans":2,"scores":[2,4,5,3,1],"trick":"Siap ditempatkan di seluruh wilayah NKRI.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), D (3), A (2), E (1). Siap ditempatkan di seluruh wilayah NKRI."},{"id":"SKD-TKP-0244","sub":"Profesionalisme","q":"Anda menemukan peluang menghemat anggaran kegiatan tanpa menurunkan kualitas, tetapi hal itu mengubah cara kerja lama yang sudah dijalankan bertahun-tahun. Sikap Anda adalah...","options":["A. Menyampaikan usulan secara lisan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","B. Mengabaikan karena sudah menjadi kebiasaan","C. Menunggu momen yang tepat, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","D. Menyusun analisis dan usulan perbaikan, mengomunikasikan manfaatnya kepada atasan dan tim, serta melakukan uji coba terbatas","E. Mengubah cara kerja sendiri tanpa izin, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan"],"ans":3,"scores":[4,1,3,5,2],"trick":"Inovasi disampaikan secara terukur dan komunikatif.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), C (3), E (2), B (1). Inovasi disampaikan secara terukur dan komunikatif."},{"id":"SKD-TKP-0250","sub":"Profesionalisme","q":"Anda mengetahui rekan Anda menggunakan jam kerja untuk usaha pribadi. Sikap Anda adalah...","options":["A. Mengingatkan sekali saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Mengikuti rekan melakukan usaha pribadi","C. Memeras rekan agar diam","D. Membiarkan karena tidak merugikan Anda, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Mengingatkan rekan secara langsung tentang aturan jam kerja, dan melaporkan kepada atasan bila tidak berubah"],"ans":4,"scores":[4,2,1,3,5],"trick":"Jam kerja digunakan untuk tugas negara.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), D (3), B (2), C (1). Jam kerja digunakan untuk tugas negara."},{"id":"SKD-TKP-0256","sub":"Profesionalisme","q":"Seorang pengusaha menawarkan Anda uang agar menunda pemeriksaan izin usahanya yang bermasalah. Sikap Anda adalah...","options":["A. Menolak tegas, mencatat kejadian, melapor kepada atasan atau KPK sesuai prosedur, dan melanjutkan pemeriksaan sesuai aturan","B. Menerima uang tetapi tetap memeriksa","C. Menolak halus dan menunda pemeriksaan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menerima uang dan menunda pemeriksaan","E. Menolak tegas lalu melanjutkan pemeriksaan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":0,"scores":[5,2,3,1,4],"trick":"Suap ditolak dan dilaporkan.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), B (2), D (1). Suap ditolak dan dilaporkan."},{"id":"SKD-TKP-0262","sub":"Profesionalisme","q":"Anda menyadari bahwa cara kerja baru yang ditetapkan pimpinan lebih rumit dibandingkan cara lama. Sikap Anda adalah...","options":["A. Kembali ke cara lama diam-diam, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Menjalankan cara baru sambil mencatat kendala, lalu menyampaikan masukan perbaikan dengan data kepada pimpinan","C. Mengeluhkan cara baru kepada rekan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menolak menggunakan cara baru, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Membuat cara sendiri tanpa izin"],"ans":1,"scores":[4,5,3,2,1],"trick":"Patuhi kebijakan sambil memberi masukan konstruktif.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), C (3), D (2), E (1). Patuhi kebijakan sambil memberi masukan konstruktif."},{"id":"SKD-TKP-0268","sub":"Profesionalisme","q":"Anda mengajar sebagai ASN guru dan menyadari metode mengajar Anda kurang efektif berdasarkan hasil belajar siswa. Sikap Anda adalah...","options":["A. Menunggu instruksi kepala sekolah","B. Menyalahkan siswa","C. Menganalisis hasil belajar, meminta masukan rekan dan siswa, mengikuti pelatihan, lalu memperbaiki metode secara bertahap","D. Menggunakan metode yang sudah dikuasai","E. Mengabaikan hasil belajar"],"ans":2,"scores":[2,3,5,4,1],"trick":"Refleksi diri dan perbaikan berkelanjutan.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), A (2), E (1). Refleksi diri dan perbaikan berkelanjutan."},{"id":"SKD-TKP-0274","sub":"Profesionalisme","q":"Atasan menegur Anda di depan rekan karena kesalahan kecil dalam dokumen. Sikap Anda adalah...","options":["A. Membalas teguran dengan alasan","B. Membicarakan atasan kepada rekan lain","C. Memperbaiki dokumen dan diam","D. Menerima teguran dengan tenang, memperbaiki dokumen, lalu berbicara empat mata untuk meminta masukan agar tidak terulang","E. Menunjukkan wajah kecewa sepanjang hari"],"ans":3,"scores":[2,1,4,5,3],"trick":"Terima kritik sebagai bahan perbaikan.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), A (2), B (1). Terima kritik sebagai bahan perbaikan."},{"id":"SKD-TKP-0280","sub":"Profesionalisme","q":"Anda diminta menyampaikan hasil pekerjaan kepada tim, tetapi Anda baru menyadari ada kesalahan di salah satu hasil. Sikap Anda adalah...","options":["A. Menunda penyampaian hasil","B. Menyampaikan hasil dan berharap tidak ada yang sadar","C. Menyalahkan data awal","D. Memperbaiki diam-diam sebelum disampaikan","E. Menyampaikan kesalahan secara jujur, menjelaskan perbaikannya, dan memastikan hasil akhir benar sebelum digunakan tim"],"ans":4,"scores":[2,3,1,4,5],"trick":"Jujur dan bertanggung jawab atas kesalahan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), A (2), C (1). Jujur dan bertanggung jawab atas kesalahan."},{"id":"SKD-TKP-0286","sub":"Profesionalisme","q":"Anda ditunjuk sebagai panitia pengadaan barang dan menemukan penawaran paling murah ternyata tidak memenuhi spesifikasi, sedangkan atasan menyukai penyedia tersebut. Tindakan Anda adalah...","options":["A. Mengevaluasi sesuai spesifikasi dan aturan, mendokumentasikan hasil objektif, dan menyampaikan keputusan kepada atasan dengan dasar yang jelas","B. Menerima imbalan dari penyedia","C. Menyetujui penyedia pilihan atasan","D. Menyampaikan hasil evaluasi tanpa rekomendasi, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Menyesuaikan spesifikasi agar penyedia tersebut lolos, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":0,"scores":[5,1,2,4,3],"trick":"Pengadaan objektif dan akuntabel.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), C (2), B (1). Pengadaan objektif dan akuntabel."},{"id":"SKD-TKP-0292","sub":"Profesionalisme","q":"Anda menyadari bahwa dokumen yang Anda susun berpotensi menimbulkan multitafsir sehingga merugikan warga. Sikap Anda adalah...","options":["A. Memanfaatkan multitafsir untuk keuntungan sendiri","B. Merevisi redaksi agar jelas, berkonsultasi dengan unit hukum atau atasan, dan mensosialisasikan perubahan kepada pihak terkait","C. Menunggu keluhan warga, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","D. Menyalahkan pembaca dokumen, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","E. Membiarkan karena sudah disetujui, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut"],"ans":1,"scores":[1,5,4,2,3],"trick":"Dokumen publik harus jelas dan adil.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), E (3), D (2), A (1). Dokumen publik harus jelas dan adil."},{"id":"SKD-TKP-0298","sub":"Profesionalisme","q":"Anda memperoleh informasi tentang rencana mutasi pegawai yang belum diumumkan, dan rekan dekat menanyakannya. Sikap Anda adalah...","options":["A. Menyebarkan informasi tersebut ke seluruh kantor","B. Mengatakan tidak tahu apa pun, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Menjaga kerahasiaan, menjelaskan bahwa informasi hanya diumumkan secara resmi, dan mengarahkan rekan menunggu pengumuman","D. Membocorkan informasi karena kasihan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Memberi petunjuk samar, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya"],"ans":2,"scores":[1,4,5,2,3],"trick":"Rahasia jabatan dijaga.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Rahasia jabatan dijaga."},{"id":"SKD-TKP-0304","sub":"Profesionalisme","q":"Anda mendapati rekan sering menunda tugas yang berkaitan dengan pekerjaan Anda sehingga Anda ikut terlambat. Sikap Anda adalah...","options":["A. Mengerjakan tugasnya sendiri, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Menyalahkan rekan di rapat","C. Ikut menunda tugas","D. Mengomunikasikan dampak keterlambatan secara baik, menyepakati tenggat bersama, dan meminta bantuan atasan jika tetap terlambat","E. Mengingatkan rekan berulang kali, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[3,2,1,5,4],"trick":"Koordinasi dan kesepakatan tenggat bersama.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), A (3), B (2), C (1). Koordinasi dan kesepakatan tenggat bersama."},{"id":"SKD-TKP-0310","sub":"Profesionalisme","q":"Anda salah menginput data penerima bantuan dan kesalahan itu baru diketahui setelah penyaluran. Tindakan Anda adalah...","options":["A. Memperbaiki data diam-diam sebelum ada yang tahu, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Menunggu ada pihak yang menemukan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Menyalahkan sistem input, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","D. Menghapus jejak input","E. Segera mengakui kesalahan kepada atasan, menelusuri dampak, memperbaiki data, dan mengikuti prosedur pemulihan bagi pihak terdampak"],"ans":4,"scores":[4,3,2,1,5],"trick":"Berani mengakui kesalahan dan memperbaikinya.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), B (3), C (2), D (1). Berani mengakui kesalahan dan memperbaikinya."},{"id":"SKD-TKP-0316","sub":"Profesionalisme","q":"Kantor mengadakan pelatihan yang bertepatan dengan tugas Anda yang menumpuk. Sikap Anda adalah...","options":["A. Mengatur prioritas dan delegasi tugas, mengikuti pelatihan dengan sungguh-sungguh, dan memastikan pekerjaan penting tetap terpantau","B. Mengikuti pelatihan tetapi tidak memperhatikan","C. Tidak mengikuti pelatihan karena sibuk","D. Mengikuti pelatihan sebagian, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Mengikuti pelatihan sambil mengerjakan tugas, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":0,"scores":[5,1,2,3,4],"trick":"Pengembangan kompetensi sama pentingnya dengan tugas harian.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), C (2), B (1). Pengembangan kompetensi sama pentingnya dengan tugas harian."},{"id":"SKD-TKP-0322","sub":"Profesionalisme","q":"Pimpinan baru meminta Anda mengubah format laporan yang sudah dipakai bertahun-tahun, padahal Anda merasa format lama lebih baik. Sikap Anda adalah...","options":["A. Menggunakan dua format sekaligus, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Mengikuti format baru, mencatat kekurangan dan kelebihan, serta menyampaikan masukan berbasis data kepada pimpinan pada waktu yang tepat","C. Menjalankan format baru dengan terpaksa, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Mengeluhkan pimpinan baru kepada rekan","E. Menolak format baru, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":1,"scores":[3,5,4,1,2],"trick":"Adaptif terhadap perubahan sambil memberi masukan.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), A (3), E (2), D (1). Adaptif terhadap perubahan sambil memberi masukan."},{"id":"SKD-TKP-0328","sub":"Profesionalisme","q":"Anda mendapat tawaran pekerjaan sampingan sebagai konsultan dari perusahaan yang berurusan dengan instansi Anda. Sikap Anda adalah...","options":["A. Menerima dengan syarat dirahasiakan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","B. Menerima setelah jam kerja","C. Menolak karena berpotensi konflik kepentingan dan memeriksa ketentuan ASN tentang pekerjaan di luar tugas","D. Menerima dan membantu perusahaan itu memenangkan proyek","E. Menunda jawaban sambil mempertimbangkan, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":2,"scores":[3,2,5,1,4],"trick":"Hindari konflik kepentingan.","explanation":"Urutan skor tertinggi ke terendah: C (5), E (4), A (3), B (2), D (1). Hindari konflik kepentingan."},{"id":"SKD-TKP-0334","sub":"Profesionalisme","q":"Anda berada dalam kondisi lelah karena beban kerja tinggi dan mulai membuat kesalahan kecil. Sikap Anda adalah...","options":["A. Mengerjakan tugas seadanya","B. Terus bekerja sampai tugas selesai, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Menunda tugas tanpa kabar","D. Menata prioritas, berkomunikasi dengan atasan tentang beban kerja, meminta dukungan tim, dan menjaga kesehatan agar kualitas kerja terjaga","E. Mengeluh kepada rekan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":3,"scores":[1,4,2,5,3],"trick":"Kelola beban kerja secara sehat dan komunikatif.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), E (3), C (2), A (1). Kelola beban kerja secara sehat dan komunikatif."},{"id":"SKD-TKP-0340","sub":"Profesionalisme","q":"Anda diundang menjadi narasumber di acara pihak swasta dan diberi honor. Acara itu terkait bidang tugas Anda. Sikap Anda adalah...","options":["A. Hadir dan menerima honor tanpa melapor, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Hadir pada akhir pekan agar tidak bentrok, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Hadir sebagai narasumber tanpa honor, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Menjadikan acara itu bisnis pribadi","E. Meminta izin atasan, memeriksa ketentuan honorarium dan gratifikasi, serta menjadi narasumber sesuai aturan"],"ans":4,"scores":[2,3,4,1,5],"trick":"Patuhi aturan izin dan honorarium.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), A (2), D (1). Patuhi aturan izin dan honorarium."},{"id":"SKD-TKP-0346","sub":"Profesionalisme","q":"Anda menyadari rekan senior melakukan kesalahan prosedur kecil yang tidak merugikan siapa pun namun melanggar aturan. Sikap Anda adalah...","options":["A. Mengingatkan secara santun dengan menjelaskan aturan yang benar, dan melapor bila kesalahan berulang","B. Melaporkan dengan nada menyalahkan","C. Menggunakan kesalahan itu untuk menekan rekan","D. Mencatat kejadian untuk dibahas bila kesalahan serupa terulang, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Menyindir rekan tersebut, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh"],"ans":0,"scores":[5,2,1,4,3],"trick":"Menegakkan aturan dengan cara santun.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), E (3), B (2), C (1). Menegakkan aturan dengan cara santun."},{"id":"SKD-TKP-0352","sub":"Profesionalisme","q":"Anda diminta bekerja pada akhir pekan untuk menyelesaikan tugas mendesak, padahal sudah memiliki rencana keluarga. Sikap Anda adalah...","options":["A. Menerima tetapi tidak mengerjakan dengan baik","B. Memahami urgensi tugas, mengatur waktu agar tugas selesai secepatnya, dan menyampaikan kendala pribadi kepada atasan agar dicarikan solusi","C. Menerima dan mengerjakan sambil mengeluh","D. Menolak tanpa menjelaskan","E. Memberi alasan sakit agar tidak bekerja"],"ans":1,"scores":[2,5,4,3,1],"trick":"Tanggung jawab dan keseimbangan dikomunikasikan dengan baik.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Tanggung jawab dan keseimbangan dikomunikasikan dengan baik."},{"id":"SKD-TKP-0358","sub":"Profesionalisme","q":"Anda bertugas di lapangan dan menemukan kondisi berbeda dari rencana yang disusun di kantor. Sikap Anda adalah...","options":["A. Mengubah rencana tanpa persetujuan","B. Melaksanakan rencana awal dan melaporkan nanti, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","C. Mendokumentasikan kondisi aktual, segera melaporkan kepada atasan, dan menyesuaikan rencana dengan persetujuan","D. Menunda pekerjaan sampai ada instruksi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","E. Meninggalkan lokasi"],"ans":2,"scores":[2,4,5,3,1],"trick":"Responsif terhadap kondisi lapangan dengan koordinasi.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), D (3), A (2), E (1). Responsif terhadap kondisi lapangan dengan koordinasi."},{"id":"SKD-TKP-0047","sub":"Anti Radikalisme","q":"Dalam rapat kantor, seorang rekan mengusulkan agar pegawai non-muslim tidak ditempatkan pada jabatan strategis. Sikap Anda adalah...","options":["A. Menolak usulan secara tegas dengan menjelaskan prinsip kesetaraan dan aturan kepegawaian, serta mengajak rapat membahas berdasarkan kompetensi","B. Mendukung usulan tersebut","C. Menyampaikan keberatan setelah rapat, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Diam agar rapat tidak panas, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menyetujui agar diskusi cepat selesai"],"ans":0,"scores":[5,1,4,3,2],"trick":"Diskriminasi SARA tidak boleh dalam kebijakan kepegawaian.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), D (3), E (2), B (1). Diskriminasi SARA tidak boleh dalam kebijakan kepegawaian."},{"id":"SKD-TKP-0053","sub":"Anti Radikalisme","q":"Anda menjadi pengelola perpustakaan desa dan menemukan buku sumbangan yang berisi ajakan kebencian terhadap kelompok tertentu. Tindakan Anda adalah...","options":["A. Membiarkan buku itu terpajang, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menarik buku dari rak, menyimpannya, dan melaporkan kepada pihak berwenang atau dinas terkait sesuai prosedur","C. Memberi label peringatan pada buku, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Menyimpan buku di gudang, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Membacakan isi buku kepada pengunjung"],"ans":1,"scores":[2,5,3,4,1],"trick":"Cegah penyebaran bacaan yang memicu kebencian.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), A (2), E (1). Cegah penyebaran bacaan yang memicu kebencian."},{"id":"SKD-TKP-0059","sub":"Anti Radikalisme","q":"Anda menerima poster dari rekan yang berisi ajakan memboikot perayaan nasional karena dianggap tidak sesuai keyakinan. Sikap Anda adalah...","options":["A. Tidak menanggapi poster tersebut dan tidak menyebarkannya, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","B. Ikut menyebarkan poster","C. Menjelaskan bahwa perayaan nasional adalah momentum persatuan, mengajak berdiskusi, dan melaporkan jika ajakan disertai provokasi","D. Menghapus poster dari grup, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Membalas dengan nada kasar, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":2,"scores":[4,1,5,3,2],"trick":"Jaga semangat kebangsaan dengan dialog.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), D (3), E (2), B (1). Jaga semangat kebangsaan dengan dialog."},{"id":"SKD-TKP-0065","sub":"Anti Radikalisme","q":"Anda mendampingi remaja dalam kegiatan pramuka, dan seorang remaja berkata ingin berhenti ikut upacara karena menganggapnya berhala. Sikap Anda adalah...","options":["A. Mengizinkan ia tidak ikut, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Menertawakan pendapatnya, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","C. Menghukum di depan teman-temannya","D. Mendengarkan alasannya, menjelaskan makna upacara sebagai penghormatan kebangsaan, dan melibatkan tokoh agama atau pembina untuk berdialog","E. Menyuruhnya mematuhi aturan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":3,"scores":[3,2,1,5,4],"trick":"Pendekatan dialog dan edukasi bagi remaja.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), A (3), B (2), C (1). Pendekatan dialog dan edukasi bagi remaja."},{"id":"SKD-TKP-0071","sub":"Anti Radikalisme","q":"Anda bertugas di lembaga pemasyarakatan dan mengetahui narapidana kasus terorisme mulai mempengaruhi narapidana lain. Tindakan Anda adalah...","options":["A. Menjadi pendukung narapidana tersebut","B. Menegur narapidana tersebut secara pribadi, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","C. Membiarkan pengaruh itu terjadi, sebab Anda merasa persoalan ini bukan bagian dari tugas pokok yang menjadi tanggung jawab Anda","D. Mengawasi lebih ketat tanpa melapor, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","E. Melaporkan kepada atasan, memisahkan pengaruh sesuai prosedur, dan ikut mendukung program deradikalisasi yang melibatkan konselor serta tokoh agama"],"ans":4,"scores":[1,3,2,4,5],"trick":"Deradikalisasi membutuhkan prosedur dan pendampingan.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), C (2), A (1). Deradikalisasi membutuhkan prosedur dan pendampingan."},{"id":"SKD-TKP-0077","sub":"Anti Radikalisme","q":"Dalam sebuah diskusi daring, seorang peserta menyatakan bahwa bentuk negara kesatuan harus diganti karena dianggap gagal. Anda moderator. Sikap Anda adalah...","options":["A. Menjaga diskusi tetap tertib, menanggapi berdasarkan dasar hukum dan sejarah, serta menolak ajakan yang melanggar konstitusi","B. Mengajak peserta lain mendukung penggantian bentuk negara","C. Membiarkan peserta berbicara tanpa tanggapan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menyetujui kritik tanpa menjelaskan","E. Menghentikan diskusi, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun"],"ans":0,"scores":[5,1,3,2,4],"trick":"Kritik boleh, tetapi tidak melanggar konstitusi.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), C (3), D (2), B (1). Kritik boleh, tetapi tidak melanggar konstitusi."},{"id":"SKD-TKP-0083","sub":"Anti Radikalisme","q":"Anda menerima pesan berisi hoaks yang memprovokasi kemarahan terhadap kelompok tertentu menjelang pemilihan. Sikap Anda adalah...","options":["A. Meneruskan agar orang lain waspada","B. Memeriksa kebenaran pesan, tidak meneruskan, mengedukasi pengirim dengan sopan, dan melaporkan hoaks kepada kanal resmi","C. Meneruskan dengan catatan 'belum tentu benar', walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Tidak meneruskan pesan, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menambahkan narasi yang memperkeruh"],"ans":1,"scores":[2,5,3,4,1],"trick":"Hoaks provokatif harus dihentikan.","explanation":"Urutan skor tertinggi ke terendah: B (5), D (4), C (3), A (2), E (1). Hoaks provokatif harus dihentikan."},{"id":"SKD-TKP-0089","sub":"Anti Radikalisme","q":"Tokoh masyarakat di daerah penugasan Anda menolak program pemerintah dengan alasan bertentangan dengan keyakinan kelompoknya dan mengajak warga menolak aparat. Sikap Anda adalah...","options":["A. Melanjutkan program tanpa melibatkan tokoh, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan","B. Menunda pelaksanaan program, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Mengajak tokoh berdialog, menjelaskan manfaat program dengan melibatkan tokoh agama, dan menyesuaikan pendekatan tanpa melanggar aturan","D. Melaporkan tokoh kepada aparat, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","E. Menuduh tokoh sebagai radikal"],"ans":2,"scores":[2,3,5,4,1],"trick":"Dialog mengatasi penolakan, bukan stigma.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), A (2), E (1). Dialog mengatasi penolakan, bukan stigma."},{"id":"SKD-TKP-0095","sub":"Anti Radikalisme","q":"Instansi Anda memperingati hari besar nasional dan seorang rekan menyampaikan bahwa ia keberatan mengikuti kegiatan karena kepercayaannya. Atasan meminta pendapat Anda. Sikap Anda adalah...","options":["A. Menyarankan rekan tetap hadir demi kekompakan","B. Menyarankan rekan dikenai sanksi","C. Menyerahkan keputusan kepada atasan sepenuhnya","D. Memberi masukan agar kegiatan tetap mengutamakan semangat kebangsaan sambil mencari bentuk partisipasi yang menghormati keyakinan rekan","E. Menyebut rekan tidak nasionalis"],"ans":3,"scores":[4,2,3,5,1],"trick":"Seimbangkan semangat kebangsaan dan penghormatan keyakinan.","explanation":"Urutan skor tertinggi ke terendah: D (5), A (4), C (3), B (2), E (1). Seimbangkan semangat kebangsaan dan penghormatan keyakinan."},{"id":"SKD-TKP-0101","sub":"Anti Radikalisme","q":"Anda menyaksikan sekelompok orang menurunkan bendera merah putih dan menggantinya dengan bendera lain di sebuah desa. Tindakan Anda adalah...","options":["A. Mengabaikan karena bukan urusan Anda, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","B. Membiarkan agar tidak terjadi keributan","C. Mengambil bendera merah putih kembali, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","D. Ikut memasang bendera lain","E. Segera melapor ke aparat setempat, mendokumentasikan dari jarak aman, dan tidak melakukan tindakan yang membahayakan diri"],"ans":4,"scores":[3,2,4,1,5],"trick":"Laporkan penghinaan simbol negara secara aman.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), A (3), B (2), D (1). Laporkan penghinaan simbol negara secara aman."},{"id":"SKD-TKP-0107","sub":"Anti Radikalisme","q":"Anda menemukan karya mural di dinding fasilitas umum yang berisi ajakan membenci kelompok tertentu. Tindakan Anda adalah...","options":["A. Mendokumentasikan, melaporkan kepada pihak berwenang agar ditangani sesuai prosedur, dan mengajak warga membuat karya yang mempersatukan","B. Menghapus mural sendiri, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Mengabaikan karena hanya seni jalanan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Menambah coretan sebagai balasan","E. Mempublikasikan mural itu agar viral"],"ans":0,"scores":[5,4,3,2,1],"trick":"Tangani lewat prosedur dan tawarkan alternatif positif.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), C (3), D (2), E (1). Tangani lewat prosedur dan tawarkan alternatif positif."},{"id":"SKD-TKP-0113","sub":"Anti Radikalisme","q":"Seorang rekan ASN mengajak Anda ikut aksi demonstrasi yang berpotensi anarkis pada jam kerja. Sikap Anda adalah...","options":["A. Ikut hanya sebentar","B. Menolak ajakan dengan sopan, mengingatkan aturan netralitas dan disiplin ASN, serta menyampaikan aspirasi melalui jalur yang sah","C. Menolak tanpa menjelaskan","D. Ikut agar solid dengan rekan","E. Ikut dan terlibat tindakan anarkis"],"ans":1,"scores":[3,5,4,2,1],"trick":"Aspirasi disalurkan lewat jalur yang sah.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), A (3), D (2), E (1). Aspirasi disalurkan lewat jalur yang sah."},{"id":"SKD-TKP-0119","sub":"Anti Radikalisme","q":"Anda menerima undangan untuk bergabung dalam grup daring yang memuat ajakan kekerasan terhadap kelompok minoritas. Sikap Anda adalah...","options":["A. Bergabung tetapi tidak aktif","B. Bergabung untuk melihat isinya","C. Tidak bergabung, melaporkan grup tersebut kepada platform dan pihak berwenang, serta tidak menyebarkan undangan","D. Menolak undangan tanpa melapor","E. Bergabung dan menyebarkan konten"],"ans":2,"scores":[2,3,5,4,1],"trick":"Laporkan konten kekerasan di ruang digital.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), B (3), A (2), E (1). Laporkan konten kekerasan di ruang digital."},{"id":"SKD-TKP-0125","sub":"Anti Radikalisme","q":"Anda mendapati selebaran di tempat umum yang mengajak mengganti dasar negara dengan ideologi tertentu. Tindakan Anda adalah...","options":["A. Membiarkan karena tidak mengenal pembuatnya","B. Membagikan selebaran itu kepada orang lain","C. Membaca seluruhnya untuk memahami","D. Mendokumentasikan, melaporkan kepada aparat atau pihak berwenang, dan tidak menyebarkan isinya","E. Menyingkirkan selebaran tersebut"],"ans":3,"scores":[3,1,2,5,4],"trick":"Laporkan propaganda anti-Pancasila kepada yang berwenang.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), A (3), C (2), B (1). Laporkan propaganda anti-Pancasila kepada yang berwenang."},{"id":"SKD-TKP-0131","sub":"Anti Radikalisme","q":"Dalam kegiatan bakti sosial, seseorang meminta Anda menyisipkan ajakan bergabung ke kelompok tertentu yang berpaham eksklusif. Sikap Anda adalah...","options":["A. Menyisipkan ajakan sesuai permintaan","B. Menolak tanpa menjelaskan, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Menyampaikan ajakan secara pribadi, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","D. Menyisipkan ajakan agar tidak menyinggung, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Menolak menyisipkan ajakan, menjaga kegiatan tetap netral dan inklusif, serta menjelaskan alasan kepada panitia"],"ans":4,"scores":[1,4,3,2,5],"trick":"Kegiatan sosial harus netral dan inklusif.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), C (3), D (2), A (1). Kegiatan sosial harus netral dan inklusif."},{"id":"SKD-TKP-0137","sub":"Anti Radikalisme","q":"Dalam kunjungan ke daerah, Anda mendapati warga memperlakukan kelompok minoritas dengan diskriminatif dalam pembagian bantuan. Tindakan Anda adalah...","options":["A. Menegaskan prinsip keadilan, memastikan pembagian sesuai data dan kebutuhan, serta melaporkan praktik diskriminasi kepada atasan","B. Membiarkan karena sudah kebiasaan","C. Ikut mengurangi bagian kelompok minoritas","D. Menyampaikan masalah kepada kepala desa saja, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menegur warga secara umum, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":0,"scores":[5,2,1,3,4],"trick":"Bantuan adil tanpa diskriminasi.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), D (3), B (2), C (1). Bantuan adil tanpa diskriminasi."},{"id":"SKD-TKP-0143","sub":"Anti Radikalisme","q":"Anda menjadi panitia peringatan Hari Lahir Pancasila di kantor, tetapi beberapa rekan merasa acara itu tidak penting. Sikap Anda adalah...","options":["A. Mewajibkan semua pegawai hadir, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","B. Menjelaskan makna kegiatan, membuat acara yang menarik dan bermakna, serta mengajak rekan berpartisipasi dalam bentuk yang beragam","C. Menyebut rekan yang menolak tidak nasionalis","D. Membatalkan acara","E. Menyelenggarakan acara sederhana saja, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga"],"ans":1,"scores":[4,5,1,2,3],"trick":"Tumbuhkan kebangsaan dengan kegiatan bermakna.","explanation":"Urutan skor tertinggi ke terendah: B (5), A (4), E (3), D (2), C (1). Tumbuhkan kebangsaan dengan kegiatan bermakna."},{"id":"SKD-TKP-0149","sub":"Anti Radikalisme","q":"Anda mendengar rencana sekelompok orang mengganggu kegiatan ibadah agama tertentu di lingkungan Anda. Tindakan Anda adalah...","options":["A. Memberi tahu pengurus rumah ibadah saja, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Menunggu sampai kejadian terjadi, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Segera memberi tahu aparat keamanan dan tokoh masyarakat, mengajak warga menjaga kondusivitas, serta tidak menyebarkan informasi yang belum pasti","D. Ikut mengamati dari jauh","E. Memprovokasi kelompok tersebut"],"ans":2,"scores":[4,3,5,2,1],"trick":"Cegah gangguan ibadah melalui deteksi dini.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), D (2), E (1). Cegah gangguan ibadah melalui deteksi dini."},{"id":"SKD-TKP-0155","sub":"Anti Radikalisme","q":"Seorang siswa magang di kantor Anda menyampaikan keraguan terhadap sistem demokrasi dan menganggap musyawarah tidak relevan. Sikap Anda adalah...","options":["A. Menertawakan pendapat siswa","B. Menyarankan siswa membaca buku","C. Menyetujui keraguan siswa","D. Mendengarkan, menjelaskan nilai musyawarah dan demokrasi Pancasila dengan contoh nyata, serta mengajak siswa mengamati proses pengambilan keputusan di kantor","E. Menegur siswa secara keras"],"ans":3,"scores":[1,4,2,5,3],"trick":"Edukasi demokrasi dengan contoh nyata.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), E (3), C (2), A (1). Edukasi demokrasi dengan contoh nyata."},{"id":"SKD-TKP-0161","sub":"Anti Radikalisme","q":"Anda melihat sebuah akun yang menyebarkan narasi bahwa Pancasila adalah produk kafir dan harus ditinggalkan. Ribuan orang membagikannya. Tindakan Anda adalah...","options":["A. Mengabaikan karena sudah banyak orang tahu","B. Membalas akun itu dengan argumen panjang, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","C. Memblokir akun tersebut, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","D. Ikut berkomentar dengan nada menghina","E. Melaporkan akun tersebut, tidak ikut menyebarkan, dan membuat atau membagikan penjelasan akurat tentang Pancasila dari sumber terpercaya"],"ans":4,"scores":[2,4,3,1,5],"trick":"Lawan narasi dengan fakta dan pelaporan.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), C (3), A (2), D (1). Lawan narasi dengan fakta dan pelaporan."},{"id":"SKD-TKP-0167","sub":"Anti Radikalisme","q":"Anda menerima kiriman buku dari kenalan baru yang berisi ajaran menyalahkan semua orang yang berbeda paham dan meminta Anda menyebarkannya di kantor. Sikap Anda adalah...","options":["A. Menolak menyebarkan, mengembalikan buku dengan sopan, dan melapor kepada pihak berwenang bila ada tekanan atau indikasi perekrutan","B. Membaca dahulu sebelum memutuskan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Menyimpan buku tanpa membaca, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","D. Menyebarkan sebagian isi buku","E. Menyebarkan buku kepada rekan"],"ans":0,"scores":[5,3,4,2,1],"trick":"Tolak penyebaran ajaran intoleran.","explanation":"Urutan skor tertinggi ke terendah: A (5), C (4), B (3), D (2), E (1). Tolak penyebaran ajaran intoleran."},{"id":"SKD-TKP-0173","sub":"Anti Radikalisme","q":"Seorang penceramah di kegiatan umum menyampaikan pernyataan yang mengecam kelompok lain dan memicu emosi jamaah. Anda hadir. Tindakan Anda adalah...","options":["A. Membantah di tengah acara, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","B. Tetap tenang, mendokumentasikan kejadian, dan melaporkan kepada tokoh masyarakat atau aparat agar ditangani secara tepat","C. Meninggalkan acara dengan diam, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Membiarkan karena itu ceramah, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Ikut menyoraki ucapan penceramah"],"ans":1,"scores":[3,5,4,2,1],"trick":"Hindari konfrontasi langsung; tangani lewat jalur tepat.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), A (3), D (2), E (1). Hindari konfrontasi langsung; tangani lewat jalur tepat."},{"id":"SKD-TKP-0179","sub":"Anti Radikalisme","q":"Anda diminta menjadi pembina kegiatan ekstrakurikuler di sebuah sekolah, dan mengetahui beberapa siswa sedang tertarik pada kelompok yang menolak upacara bendera dan menyebut negara sebagai musuh. Tindakan Anda adalah...","options":["A. Menegur siswa secara umum, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Membiarkan karena mereka masih remaja, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Mengajak siswa berdiskusi, menanamkan wawasan kebangsaan melalui kegiatan positif, serta berkoordinasi dengan guru dan orang tua","D. Mengeluarkan siswa dari kegiatan tanpa pembinaan","E. Melaporkan kepada kepala sekolah saja, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak"],"ans":2,"scores":[4,2,5,1,3],"trick":"Pembinaan wawasan kebangsaan sejak dini.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), B (2), D (1). Pembinaan wawasan kebangsaan sejak dini."},{"id":"SKD-TKP-0185","sub":"Anti Radikalisme","q":"Dalam upacara bendera kantor, seorang rekan menolak memberi hormat dengan alasan keyakinan dan mengajak yang lain mengikutinya. Sikap Anda adalah...","options":["A. Menertawakan keyakinan rekan","B. Mengikuti rekan agar tidak dikucilkan","C. Membiarkan agar tidak ada keributan, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","D. Mengajak berdialog secara santun, menjelaskan bahwa hormat bendera adalah wujud penghormatan negara dan bukan ibadah, serta melaporkan kepada atasan jika ajakan penolakan berlanjut","E. Menyampaikan pandangan tegas lalu meninggalkan rekan, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":3,"scores":[1,2,3,5,4],"trick":"Sikap kebangsaan dijaga melalui dialog dan penegakan aturan.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), B (2), A (1). Sikap kebangsaan dijaga melalui dialog dan penegakan aturan."},{"id":"SKD-TKP-0191","sub":"Anti Radikalisme","q":"Seorang kerabat dekat Anda mulai mengkafirkan keluarga sendiri dan menjauhi acara keluarga yang berbeda keyakinan. Sikap Anda adalah...","options":["A. Menyampaikan keberatan secara tegas, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","B. Mengucilkan kerabat dari keluarga","C. Menjauhi kerabat tersebut, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","D. Membiarkannya karena urusan pribadi, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","E. Mendengarkan dengan tenang, mengajaknya berdiskusi dengan tokoh yang dihormati, menjaga hubungan baik, dan mencari bantuan profesional bila perlu"],"ans":4,"scores":[4,1,3,2,5],"trick":"Dekati dengan dialog dan jaga hubungan.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), C (3), D (2), B (1). Dekati dengan dialog dan jaga hubungan."},{"id":"SKD-TKP-0197","sub":"Anti Radikalisme","q":"Anda melihat seorang anak muda di lingkungan Anda mulai menutup diri dan sering membagikan konten bernada ekstrem. Keluarganya khawatir. Tindakan Anda adalah...","options":["A. Mendekati dengan empati, mendengarkan, melibatkannya dalam kegiatan positif, dan mengajak tokoh masyarakat atau pihak berwenang membantu pendampingan","B. Menyarankan keluarga mengawasinya, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Mengucilkannya dari lingkungan","D. Menegurnya dengan keras, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","E. Membiarkannya karena itu pilihan pribadi, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai"],"ans":0,"scores":[5,3,1,4,2],"trick":"Pendekatan pencegahan dini dengan empati dan pendampingan.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Pendekatan pencegahan dini dengan empati dan pendampingan."},{"id":"SKD-TKP-0203","sub":"Anti Radikalisme","q":"Anda menemukan grup media sosial yang berisi orang-orang membagikan video kekerasan sebagai bentuk pembenaran perjuangan. Anda tidak mengenal mereka. Sikap Anda adalah...","options":["A. Membiarkan grup itu","B. Tidak bergabung dan tidak menyebarkan, melaporkan grup tersebut ke platform dan aparat, serta mengingatkan keluarga tentang bahaya konten itu","C. Menonton video untuk mengetahui isinya","D. Membagikan video kepada teman","E. Keluar dari grup"],"ans":1,"scores":[2,5,3,1,4],"trick":"Laporkan konten kekerasan dan lindungi orang sekitar.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), C (3), A (2), D (1). Laporkan konten kekerasan dan lindungi orang sekitar."},{"id":"SKD-TKP-0209","sub":"Anti Radikalisme","q":"Seorang tokoh masyarakat meminta dukungan Anda untuk kegiatan yang disebutnya 'perjuangan' tetapi tampak mengarah pada kekerasan. Sikap Anda adalah...","options":["A. Ikut mendukung kegiatan tersebut","B. Menolak terlibat dan menghindar, dan menganggap tanggung jawab Anda sudah selesai begitu langkah tersebut dilakukan","C. Menolak terlibat, menjelaskan alasan dengan tenang, dan melapor kepada pihak berwenang jika ada indikasi ancaman","D. Menyumbang sedikit agar tidak dimusuhi","E. Menunda jawaban sambil mencari informasi, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":2,"scores":[1,4,5,2,3],"trick":"Tolak kekerasan atas nama apa pun.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), E (3), D (2), A (1). Tolak kekerasan atas nama apa pun."},{"id":"SKD-TKP-0215","sub":"Anti Radikalisme","q":"Anda menyadari seorang bawahan terus membagikan konten politik yang provokatif pada jam kerja dan membuat suasana tim memanas. Sebagai atasan, tindakan Anda adalah...","options":["A. Membiarkan agar suasana tidak canggung","B. Ikut membahas konten tersebut","C. Menegur di depan tim","D. Menegur secara pribadi dengan merujuk aturan netralitas ASN, memberi pembinaan, dan mengambil tindakan disiplin sesuai prosedur bila diulang","E. Memindahkan bawahan ke unit lain"],"ans":3,"scores":[2,1,4,5,3],"trick":"Atasan membina dan menegakkan aturan netralitas.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), A (2), B (1). Atasan membina dan menegakkan aturan netralitas."},{"id":"SKD-TKP-0221","sub":"Anti Radikalisme","q":"Seorang teman lama mengajak Anda mengikuti kajian tertutup yang menurutnya membahas 'negara yang benar' dan menolak Pancasila serta pemerintah yang sah. Sikap Anda adalah...","options":["A. Hadir sekali untuk mengetahui isinya, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Hadir karena tidak enak kepada teman, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Menolak ajakan tanpa memberi penjelasan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Bergabung dan ikut menyebarkan ajaran tersebut","E. Menolak ajakan dengan tegas dan santun, menjelaskan komitmen Anda pada Pancasila dan NKRI, serta melaporkan kepada pihak berwenang bila ada indikasi perekrutan"],"ans":4,"scores":[3,2,4,1,5],"trick":"Tolak ideologi yang bertentangan dengan Pancasila dan laporkan perekrutan.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), A (3), B (2), D (1). Tolak ideologi yang bertentangan dengan Pancasila dan laporkan perekrutan."},{"id":"SKD-TKP-0227","sub":"Anti Radikalisme","q":"Warga di lingkungan Anda menolak kehadiran pendatang karena berbeda keyakinan, dan beberapa mulai mengancam. Tindakan Anda adalah...","options":["A. Segera berkoordinasi dengan RT/RW, tokoh masyarakat, dan aparat untuk menenangkan situasi, serta memfasilitasi dialog damai","B. Menunggu situasi mereda sendiri, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Memprovokasi warga untuk mengusir pendatang","D. Menyarankan pendatang pindah demi keamanan, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","E. Mendukung penolakan warga"],"ans":0,"scores":[5,3,1,4,2],"trick":"Cegah kekerasan dengan mediasi dan koordinasi aparat.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Cegah kekerasan dengan mediasi dan koordinasi aparat."},{"id":"SKD-TKP-0233","sub":"Anti Radikalisme","q":"Teman kuliah Anda yang aktif di organisasi tertentu mengajak Anda menandatangani petisi menolak dasar negara. Sikap Anda adalah...","options":["A. Menandatangani agar tidak dimusuhi","B. Menolak menandatangani, menjelaskan alasan secara santun, dan menunjukkan bahwa perbedaan pendapat dapat disampaikan lewat cara konstitusional","C. Menolak tanpa komentar, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Meminta waktu untuk mempertimbangkan, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Menandatangani dan ikut menyebarkan"],"ans":1,"scores":[2,5,4,3,1],"trick":"Setia pada dasar negara, tetap hormati perbedaan dengan cara konstitusional.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Setia pada dasar negara, tetap hormati perbedaan dengan cara konstitusional."},{"id":"SKD-TKP-0239","sub":"Anti Radikalisme","q":"Anda ditugaskan di daerah dengan sebagian warga membawa bendera kelompok yang bukan lambang negara dalam peringatan hari kemerdekaan. Sikap Anda adalah...","options":["A. Meminta mereka menurunkan bendera tersebut","B. Memprovokasi warga","C. Berdialog dengan tokoh masyarakat, menjelaskan aturan penggunaan simbol negara, dan berkoordinasi dengan aparat bila ada indikasi pelanggaran","D. Membiarkan karena hanya simbol","E. Melaporkan kepada atasan tanpa berdialog"],"ans":2,"scores":[4,1,5,2,3],"trick":"Dialog dan penegakan aturan menjaga simbol negara.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), E (3), D (2), B (1). Dialog dan penegakan aturan menjaga simbol negara."},{"id":"SKD-TKP-0245","sub":"Anti Radikalisme","q":"Dalam pelatihan CPNS, seorang peserta berkata ia hanya setia pada kelompoknya dan menganggap negara tidak penting. Anda fasilitator. Sikap Anda adalah...","options":["A. Menyetujui bahwa kelompok penting","B. Mengabaikan komentar tersebut, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","C. Mengusir peserta dari pelatihan","D. Mengajak peserta berdiskusi, memaparkan sumpah janji ASN dan nilai kebangsaan, serta mengajak peserta lain berbagi pengalaman positif berbangsa","E. Menegur peserta secara tegas, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[2,3,1,5,4],"trick":"Tanamkan nilai kebangsaan lewat dialog.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), B (3), A (2), C (1). Tanamkan nilai kebangsaan lewat dialog."},{"id":"SKD-TKP-0251","sub":"Anti Radikalisme","q":"Anda mengetahui seorang kerabat dekat terindikasi terpapar paham radikal dan memintamu membantu menyembunyikan seseorang dari aparat. Sikap Anda adalah...","options":["A. Menolak membantu tanpa melapor, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","B. Membantu sementara agar tidak ada perpecahan, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Membantu menyembunyikan","D. Mendiamkan masalah itu demi keluarga, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","E. Menolak membantu, membujuk kerabat untuk menyerahkan diri atau berkoordinasi dengan aparat, dan melaporkan bila ada ancaman"],"ans":4,"scores":[4,2,1,3,5],"trick":"Hukum lebih utama daripada hubungan pribadi.","explanation":"Urutan skor tertinggi ke terendah: E (5), A (4), D (3), B (2), C (1). Hukum lebih utama daripada hubungan pribadi."},{"id":"SKD-TKP-0257","sub":"Anti Radikalisme","q":"Warga sekitar mengadakan pengajian yang sebagian materinya menyudutkan pemerintah dengan fitnah, dan Anda diminta hadir sebagai tamu undangan. Sikap Anda adalah...","options":["A. Hadir dengan sopan, tidak terlibat dalam fitnah, menyampaikan fakta secara santun bila ada kesempatan, dan melapor jika ada hasutan serius","B. Menolak hadir tanpa penjelasan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Meninggalkan acara sambil mengancam","D. Hadir dan diam saja, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Hadir dan ikut menyuarakan"],"ans":0,"scores":[5,3,1,4,2],"trick":"Hadapi fitnah dengan fakta dan kepala dingin.","explanation":"Urutan skor tertinggi ke terendah: A (5), D (4), B (3), E (2), C (1). Hadapi fitnah dengan fakta dan kepala dingin."},{"id":"SKD-TKP-0263","sub":"Anti Radikalisme","q":"Anda mendapati konten video di aplikasi pendek yang mengglorifikasi kelompok teroris dan menarik banyak penonton remaja. Anda adalah orang tua dan ASN. Sikap Anda adalah...","options":["A. Membiarkan karena hanya hiburan","B. Melaporkan konten ke platform, mengedukasi keluarga dan lingkungan, serta mengajak remaja berdiskusi secara terbuka tentang bahayanya","C. Membagikan video itu kepada teman","D. Menegur anak agar tidak menonton, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","E. Melaporkan konten dan menutup akun anak, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan"],"ans":1,"scores":[2,5,1,3,4],"trick":"Perlindungan digital dengan edukasi keluarga.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), D (3), A (2), C (1). Perlindungan digital dengan edukasi keluarga."},{"id":"SKD-TKP-0269","sub":"Anti Radikalisme","q":"Anda menemukan grup pesan yang mengaku sebagai kelompok pengajian tetapi menyebarkan pesan agar tidak membayar pajak dan menolak aturan negara. Sikap Anda adalah...","options":["A. Keluar dari grup, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan","B. Mengabaikan pesan tersebut, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Tidak ikut menyebarkan, melaporkan kepada pihak berwenang, dan menjelaskan kepada rekan tentang kewajiban warga negara serta dasar hukumnya","D. Menyebarkan pesan ke teman","E. Ikut mempertimbangkan pesan tersebut, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan"],"ans":2,"scores":[4,3,5,1,2],"trick":"Ajakan melanggar hukum dilaporkan dan diluruskan.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), E (2), D (1). Ajakan melanggar hukum dilaporkan dan diluruskan."},{"id":"SKD-TKP-0275","sub":"Anti Radikalisme","q":"Dalam grup alumni, seseorang menyebarkan ajakan jihad kekerasan melawan pemerintah dan beberapa anggota mulai menyetujui. Tindakan Anda adalah...","options":["A. Menyetujui agar dianggap sepaham","B. Diam agar tidak diserang, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","C. Keluar dari grup dengan diam, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Menyatakan penolakan secara tegas dan santun, mengingatkan anggota agar tidak terpengaruh, serta melaporkan grup kepada pihak berwenang","E. Menonaktifkan notifikasi grup, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":3,"scores":[1,2,4,5,3],"trick":"Tolak kekerasan dan laporkan hasutan.","explanation":"Urutan skor tertinggi ke terendah: D (5), C (4), E (3), B (2), A (1). Tolak kekerasan dan laporkan hasutan."},{"id":"SKD-TKP-0281","sub":"Anti Radikalisme","q":"Anda mengetahui seorang rekan sering menghina tokoh bangsa dan menyebut kemerdekaan Indonesia sebagai kesalahan sejarah. Sikap Anda adalah...","options":["A. Membiarkan karena kebebasan berpendapat","B. Menghindari pembicaraan dengan rekan, karena menurut Anda cara itu sudah cukup dan tidak perlu dibahas lebih jauh","C. Ikut menghina","D. Membantah di forum terbuka, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","E. Menegur dengan santun, memberi penjelasan sejarah yang benar, dan melaporkan kepada atasan bila rekan tetap menyebarkan hinaan"],"ans":4,"scores":[2,3,1,4,5],"trick":"Hargai sejarah bangsa dan luruskan dengan santun.","explanation":"Urutan skor tertinggi ke terendah: E (5), D (4), B (3), A (2), C (1). Hargai sejarah bangsa dan luruskan dengan santun."},{"id":"SKD-TKP-0287","sub":"Anti Radikalisme","q":"Anda mendapat kabar bahwa seorang pegawai yang baru pulang dari luar negeri mengajak rekan lain bergabung dalam gerakan yang menentang pemerintah. Sikap Anda adalah...","options":["A. Menghindari prasangka, mengumpulkan informasi secara hati-hati, dan melaporkan kepada atasan atau pengawas bila terdapat indikasi nyata","B. Menjauhi pegawai tersebut, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","C. Menyebarkan kabar itu kepada pegawai lain, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","D. Ikut bergabung dengan gerakan tersebut","E. Mengonfirmasi langsung kepada pegawai tersebut, meskipun belum memastikan apakah hasilnya benar-benar menyelesaikan persoalan"],"ans":0,"scores":[5,3,2,1,4],"trick":"Hati-hati menilai, laporkan dengan bukti.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), C (2), D (1). Hati-hati menilai, laporkan dengan bukti."},{"id":"SKD-TKP-0293","sub":"Anti Radikalisme","q":"Seorang rekan ASN aktif menjadi pengurus organisasi yang telah dilarang pemerintah. Anda mengetahuinya. Tindakan Anda adalah...","options":["A. Membiarkan karena urusan pribadi, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Mengumpulkan fakta secara hati-hati, menyampaikan kepada atasan atau unit pengawasan, dan tidak menyebarkan tuduhan sebelum terbukti","C. Menegur rekan tanpa melapor, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","D. Menjaga jarak dengan rekan tersebut, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","E. Menyebarkan informasi tersebut ke seluruh kantor"],"ans":1,"scores":[2,5,4,3,1],"trick":"Pelanggaran disiplin dilaporkan lewat jalur resmi dengan prinsip praduga tak bersalah.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), A (2), E (1). Pelanggaran disiplin dilaporkan lewat jalur resmi dengan prinsip praduga tak bersalah."},{"id":"SKD-TKP-0299","sub":"Anti Radikalisme","q":"Seorang anak SMA di lingkungan Anda tertarik bergabung dengan kelompok yang disebutnya sangat tegas melawan 'kezaliman negara'. Ia meminta pendapat Anda. Sikap Anda adalah...","options":["A. Menyatakan bahwa itu pilihannya","B. Mendukung ia bergabung","C. Mendengarkan tanpa menghakimi, menjelaskan cara menyalurkan aspirasi yang konstitusional, serta mengajak tokoh dan orang tuanya mendampingi","D. Melarang keras ia bergabung","E. Menyarankan menanyakan kepada guru"],"ans":2,"scores":[2,1,5,4,3],"trick":"Dampingi remaja memilih jalan aspirasi yang benar.","explanation":"Urutan skor tertinggi ke terendah: C (5), D (4), E (3), A (2), B (1). Dampingi remaja memilih jalan aspirasi yang benar."},{"id":"SKD-TKP-0305","sub":"Anti Radikalisme","q":"Anda dimintai pendapat oleh pimpinan tentang penanganan pegawai yang terbukti menyebarkan ujaran kebencian di media sosial. Sikap Anda adalah...","options":["A. Menyarankan menutup kasus agar citra instansi aman","B. Menyarankan teguran lisan saja, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Menyarankan pegawai tersebut dibiarkan, karena menurut Anda hal itu paling praktis dan tidak memerlukan banyak usaha tambahan","D. Menyarankan pemeriksaan berdasarkan aturan disiplin, pembinaan, dan sanksi proporsional agar menjadi pelajaran bagi pegawai lain","E. Menyerahkan keputusan kepada pimpinan tanpa masukan, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak"],"ans":3,"scores":[1,4,2,5,3],"trick":"Penegakan disiplin dilakukan adil dan mendidik.","explanation":"Urutan skor tertinggi ke terendah: D (5), B (4), E (3), C (2), A (1). Penegakan disiplin dilakukan adil dan mendidik."},{"id":"SKD-TKP-0311","sub":"Anti Radikalisme","q":"Seorang rekan kantor sering mengejek perayaan agama lain dan menyebut pemeluknya sesat. Sikap Anda adalah...","options":["A. Membiarkan karena kebebasan berpendapat, dan Anda memilih tidak memberi penjelasan apa pun supaya urusan cepat selesai","B. Menyindir rekan tersebut, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas","C. Ikut mengejek","D. Menjauhi rekan tersebut, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Menegur dengan santun bahwa sikap itu melanggar toleransi dan etika ASN, serta melapor kepada atasan jika tidak berubah"],"ans":4,"scores":[2,4,1,3,5],"trick":"Toleransi adalah nilai ASN.","explanation":"Urutan skor tertinggi ke terendah: E (5), B (4), D (3), A (2), C (1). Toleransi adalah nilai ASN."},{"id":"SKD-TKP-0317","sub":"Anti Radikalisme","q":"Anda menemukan unggahan media sosial milik rekan yang menyebut pemerintah sah sebagai thagut dan mengajak tidak memilih. Tindakan Anda adalah...","options":["A. Mengingatkan rekan secara langsung tentang kewajiban ASN, mendokumentasikan unggahan, dan melaporkan kepada atasan bila tidak dihapus","B. Mengomentari unggahan secara terbuka, kemudian menyerahkan sisa penyelesaiannya kepada pihak lain tanpa melakukan pemantauan","C. Membagikan unggahan tersebut","D. Meninggalkan akun rekan tersebut, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","E. Membiarkan karena akun pribadi"],"ans":0,"scores":[5,4,1,3,2],"trick":"ASN setia pada Pancasila, UUD 1945, dan pemerintah yang sah.","explanation":"Urutan skor tertinggi ke terendah: A (5), B (4), D (3), E (2), C (1). ASN setia pada Pancasila, UUD 1945, dan pemerintah yang sah."},{"id":"SKD-TKP-0323","sub":"Anti Radikalisme","q":"Seorang rekan tampak marah karena kebijakan pemerintah dan mengatakan ia ingin 'membalas' dengan cara kekerasan. Sikap Anda adalah...","options":["A. Mendukung keinginan rekan","B. Menenangkan rekan, mengarahkan menyalurkan keberatan lewat jalur resmi, dan melaporkan kepada atasan atau pihak berwenang bila ancaman tampak serius","C. Menenangkan rekan tanpa melaporkan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku","D. Menjauhi rekan itu, dengan harapan persoalannya selesai sendiri tanpa perlu melibatkan banyak pihak","E. Menganggapnya hanya bercanda"],"ans":1,"scores":[1,5,4,3,2],"trick":"Ancaman kekerasan harus ditanggapi serius.","explanation":"Urutan skor tertinggi ke terendah: B (5), C (4), D (3), E (2), A (1). Ancaman kekerasan harus ditanggapi serius."},{"id":"SKD-TKP-0329","sub":"Anti Radikalisme","q":"Anda mengetahui ada upaya penyebaran paham radikal melalui permainan daring yang dimainkan anak-anak di lingkungan Anda. Sikap Anda adalah...","options":["A. Melarang anak-anak bermain, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","B. Menunggu orang tua menyadari sendiri, sebab Anda ingin menghindari perdebatan yang bisa memakan waktu dan tenaga","C. Memberi tahu orang tua dan sekolah, mengedukasi anak-anak, dan melaporkan kepada pihak berwenang atau platform","D. Ikut bermain tanpa memperhatikan","E. Menganggap itu hanya permainan, dengan alasan situasinya sudah biasa terjadi dan tidak perlu dipersoalkan"],"ans":2,"scores":[4,3,5,1,2],"trick":"Lindungi anak dari paham radikal lewat edukasi dan pelaporan.","explanation":"Urutan skor tertinggi ke terendah: C (5), A (4), B (3), E (2), D (1). Lindungi anak dari paham radikal lewat edukasi dan pelaporan."},{"id":"SKD-TKP-0335","sub":"Anti Radikalisme","q":"Pada kelompok belajar remaja yang Anda dampingi, ada mentor yang mulai memasukkan paham antiperbedaan dan membenci pemerintah. Tindakan Anda adalah...","options":["A. Mendukung mentor","B. Membiarkan karena mentor dianggap berwibawa","C. Memindahkan remaja ke kelompok lain, walaupun Anda sadar langkah itu belum sepenuhnya sesuai prosedur dan kepentingan semua pihak","D. Menghentikan pengaruh tersebut secara tegas namun santun, memberi penjelasan kepada remaja, dan melapor kepada pengelola atau pihak berwenang","E. Menyampaikan keberatan kepada mentor secara pribadi, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":3,"scores":[1,2,3,5,4],"trick":"Lindungi remaja dari paham intoleran.","explanation":"Urutan skor tertinggi ke terendah: D (5), E (4), C (3), B (2), A (1). Lindungi remaja dari paham intoleran."},{"id":"SKD-TKP-0341","sub":"Anti Radikalisme","q":"Dalam pelatihan, peserta bertanya apakah Pancasila bertentangan dengan agama. Anda narasumber. Sikap Anda adalah...","options":["A. Menyuruh peserta mencari tahu sendiri","B. Menunda pertanyaan hingga akhir","C. Menjawab singkat bahwa keduanya tidak bertentangan","D. Menertawakan pertanyaan tersebut","E. Menjelaskan secara sabar dan berdasarkan sejarah bahwa Pancasila lahir dari nilai agama dan budaya bangsa, serta membuka dialog dengan peserta"],"ans":4,"scores":[2,3,4,1,5],"trick":"Edukasi Pancasila dengan dialog.","explanation":"Urutan skor tertinggi ke terendah: E (5), C (4), B (3), A (2), D (1). Edukasi Pancasila dengan dialog."},{"id":"SKD-TKP-0347","sub":"Anti Radikalisme","q":"Anda diminta mengisi acara pengajian lingkungan perumahan, dan seorang jamaah meminta Anda membahas pandangan bahwa warga yang berbeda mazhab pantas dijauhi. Sikap Anda adalah...","options":["A. Menolak membahas pandangan tersebut, menyampaikan pesan persaudaraan dan toleransi, serta mengajak jamaah menghormati perbedaan","B. Membahas secara netral tanpa sikap, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","C. Membahas pandangan itu secara mendalam","D. Menyetujui agar jamaah senang","E. Menghindari topik itu tanpa penjelasan, sambil tetap mengutamakan kepraktisan dibanding kelengkapan prosedur yang berlaku"],"ans":0,"scores":[5,3,1,2,4],"trick":"Sebarkan pesan persaudaraan, bukan pengucilan.","explanation":"Urutan skor tertinggi ke terendah: A (5), E (4), B (3), D (2), C (1). Sebarkan pesan persaudaraan, bukan pengucilan."},{"id":"SKD-TKP-0353","sub":"Anti Radikalisme","q":"Anda menemukan rekan kerja membagikan konten yang menghasut kebencian terhadap kelompok agama tertentu di grup kantor. Tindakan Anda adalah...","options":["A. Mengabaikan karena hanya satu kali, lalu meminta pihak lain mengambil keputusan karena Anda tidak ingin menanggung risikonya","B. Meminta rekan menghapus konten dengan sopan, mengingatkan etika dan aturan ASN, serta melapor kepada atasan bila berulang","C. Membalas dengan konten serupa","D. Ikut menyebarkan konten tersebut","E. Menghapus pesan tanpa menegur, tetapi tidak mencatat atau melaporkannya sehingga tidak ada tindak lanjut yang jelas"],"ans":1,"scores":[3,5,2,1,4],"trick":"Cegah ujaran kebencian dengan teguran dan eskalasi.","explanation":"Urutan skor tertinggi ke terendah: B (5), E (4), A (3), C (2), D (1). Cegah ujaran kebencian dengan teguran dan eskalasi."},{"id":"SKD-TKP-0359","sub":"Anti Radikalisme","q":"Pimpinan meminta Anda memilih pembicara untuk seminar kebangsaan, dan salah satu kandidat dikenal sering menyebarkan pandangan anti-keberagaman. Sikap Anda adalah...","options":["A. Menyerahkan pemilihan kepada pimpinan tanpa masukan, dan baru akan bertindak lebih jauh apabila ada pihak yang mengeluhkan hal tersebut","B. Memilih pembicara yang paling terkenal, lalu menunggu perkembangan selanjutnya sebelum mengambil langkah tambahan apa pun","C. Memilih pembicara yang kompeten dan sejalan dengan nilai Pancasila, serta menjelaskan alasan pemilihan kepada pimpinan","D. Memilih kandidat tersebut agar tidak berselisih","E. Memilih kandidat tersebut karena kenal baik"],"ans":2,"scores":[3,4,5,2,1],"trick":"Pilih narasumber yang menguatkan persatuan.","explanation":"Urutan skor tertinggi ke terendah: C (5), B (4), A (3), D (2), E (1). Pilih narasumber yang menguatkan persatuan."}];
  var CLEAN = [{"id":"SKD-TKP-0036","q":"Saat sedang melayani antrean masyarakat di loket pelayanan terpadu, sistem jaringan kantor mengalami pelambatan selama 15 menit sehingga warga mulai gelisah. Sikap Anda yang paling tepat adalah..."},{"id":"SKD-TKP-0037","q":"Unit kerja Anda ditugaskan menyusun program kolaborasi lintas dinas untuk percepatan penurunan angka kemiskinan daerah dalam waktu singkat. Sikap Anda yang paling tepat adalah..."},{"id":"SKD-TKP-0038","q":"Anda ditempatkan di wilayah kerja baru yang masyarakatnya memiliki tradisi gotong royong dan adat istiadat lokal yang sangat kuat, berbeda dengan daerah asal Anda. Sikap Anda yang paling tepat adalah..."},{"id":"SKD-TKP-0039","q":"Instansi Anda mengimplementasikan aplikasi manajemen kinerja dan persuratan elektronik baru berbasis cloud untuk mendukung percepatan SPBE. Sikap Anda yang paling tepat adalah..."},{"id":"SKD-TKP-0040","q":"Menjelang akhir tahun anggaran, Anda dihadapkan pada dua tugas penting yang tenggat waktunya berdekatan sementara ada urusan keluarga yang tidak mendesak di sore hari. Sikap Anda yang paling tepat adalah..."},{"id":"SKD-TKP-0041","q":"Anda menerima pesan berantai di grup percakapan lingkungan yang berisi provokasi SARA dan ajakan menolak kebijakan negara menggunakan cara-cara inkonstitusional. Sikap Anda yang paling tepat adalah..."}];
  var at = {};
  B.forEach(function (q, i) { at[q.id] = i; });
